  const diskLvl = !k ? 0 : (k.pct >= 95 || (k.full_days !== null && k.full_days <= 7)) ? 2 : (k.pct >= 80 || (k.full_days !== null && k.full_days <= 30)) ? 1 : 0;
  const cronLvl = cr.ago === null || cr.ago === undefined ? 1 : cr.ago > 300 ? 2 : (cr.ago > 150 || cr.over > 0) ? 1 : 0;
