    $('#type-help').textContent = isDm && dmSel.value === 'mail' ? DOMAIN_METRICS.mail.help : TYPES[typeSel.value].help;   // 1.227.0
    const isProc = typeSel.value === 'process';
    $('#res-wrap').hidden = !isContainer && !isProc;
