    $$('#proc-wrap input, #proc-wrap select', form).forEach((el) => { el.disabled = !isProc; });
    $('[data-res=disk]', form).hidden = isProc;
    $('[name=res_disk]', form).disabled = isProc;
    $$('[data-res=mem] .res-unit', form).forEach((u) => (u.textContent = isProc ? 'MB' : '%'));
