    <td class="small">${h.paths.length ? [h.canary ? '🪤 ' + L('lokaas') : '', h.snap ? '📸 ' + L('snapshot') : '', h.kill ? '⛔ ' + L('stoppen') : ''].filter(Boolean).join(' · ') || L('alleen melden') : ''}</td>
