// ---------------------------------------------------------------- RzSense bijwerken
let updatePoll = null;

/** Changelog-tekst (Markdown) als eenvoudige HTML: kopjes, opsommingen, vet, cursief en code. */
function mdLite(text) {
  const inline = (t) => esc(t).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').replace(/\*(.+?)\*/g, '<i>$1</i>').replace(/`([^`]+)`/g, '<code>$1</code>');
  let html = '', depth = 0;
  for (const line of text.split('\n')) {
    const m = line.match(/^(\s*)- (.*)$/);
    const d = m ? Math.floor(m[1].length / 2) + 1 : 0;
    while (depth < d) { html += '<ul>'; depth++; }
    while (depth > d) { html += '</ul>'; depth--; }
    if (m) html += `<li>${inline(m[2])}</li>`;
    else if (/^### /.test(line)) html += `<h4>${inline(line.slice(4))}</h4>`;
    else if (line.trim()) html += `<p>${inline(line)}</p>`;
  }
  while (depth-- > 0) html += '</ul>';
  return html;
}

async function loadUpdate(force) {
  const st = $('#update-status');
  let u;
  try { u = await api('update_info', null, force ? { force: 1 } : {}); } catch (ex) { st.textContent = ex.message; return; }
  const parts = [L('Je gebruikt <b>{v}</b>.', { v: esc(u.current) })];
  if (u.error) parts.push(`<b class="warn-txt">⚠️ ${esc(u.error)}</b>`);
  else if (u.available) parts.push(`<b class="good-txt">${L('Nieuwe versie beschikbaar: {v}', { v: esc(u.latest) })}</b>`);
  else if (u.latest) parts.push(`<span class="good-txt">✔ ${L('Dit is de nieuwste versie.')}</span>`);
  if (u.checked_at) parts.push(`<span class="muted">${L('Gecontroleerd {ago}.', { ago: ago(u.checked_at) })}</span>`);
  if (u.available && u.unavailable) {
    parts.push(`<br><b class="warn-txt">${L('Bijwerken vanuit RzSense kan nog niet:')}</b> ${esc(u.unavailable)}. ${L('Voer één keer uit op de server:')}`
      + copyBox('cmd-update-setup', 'curl -fsSL https://raw.githubusercontent.com/rembrand20/rzmon/main/install/install-rocky.sh -o install-rocky.sh && sudo bash install-rocky.sh'));
  }
  st.innerHTML = parts.join(' ');
  $('#update-notes').innerHTML = u.available && u.notes.length ? `<details class="update-notes" open><summary>${u.notes.length === 1 ? L('Wat is er nieuw (1 versie)') : L('Wat is er nieuw ({n} versies)', { n: u.notes.length })}</summary>
    ${u.notes.map((n) => `<div class="un-ver"><h3>${esc(n.version)} <span class="muted small">${esc(n.date)}</span></h3>${mdLite(n.text)}</div>`).join('')}</details>` : '';
  if (u.pinned) parts.push(`<br><span class="warn-txt">📌 ${L('Je hebt bewust versie {v} gekozen: automatisch bijwerken staat op pauze tot je weer naar de nieuwste gaat.', { v: esc(u.pinned) })}</span>`);
  st.innerHTML = parts.join(' ');
  $('#update-pick').hidden = !!u.unavailable || !(u.versions || []).some((v) => v.version !== u.current);
  const b = $('#update-start');
  b.hidden = !u.available || !!u.unavailable;
  b.textContent = `⬆ ${L('Nu bijwerken naar {v}', { v: u.latest })}`;
  updateInfo = u;
  settingsSummaries();
  showUpdateProgress(u.status, '');
  if (u.status && ['queued', 'running'].includes(u.status.state)) pollUpdate();
}

// 1.221.0: eerst ophalen, dan de back-up (snel of volledig, afhankelijk van de nieuwe versie)
const UPDATE_STEPS = [['check', L('Controleren')], ['download', L('Nieuwste versie ophalen')], ['backup', L('Back-up maken')], ['install', L('Installeren')], ['klaar', L('Klaar')]];

function showUpdateProgress(s, log) {
  const el = $('#update-progress');
  // Een afgeronde update van langer dan een dag geleden niet meer tonen
  if (!s || (['ok', 'error'].includes(s.state) && s.at < Date.now() / 1000 - 86400)) { el.hidden = true; return; }
  el.hidden = false;
  const cur = UPDATE_STEPS.findIndex(([k]) => k === s.step);
  const icon = (i) => s.state === 'ok' || i < cur ? '✔' : i === cur ? (s.state === 'error' ? '✘' : '⏳') : '·';
  el.innerHTML = `<div class="update-box ${s.state}">
    <b>${s.state === 'ok' ? '✔ ' : s.state === 'error' ? '✘ ' : '⏳ '}${esc(s.message || '')}</b>
    ${s.state === 'queued' && s.stuck ? `<p class="warn-txt small">${L('De hulpdienst reageert niet. Controleer op de server:')} <code>systemctl status rzmon-update.path</code></p>` : ''}
    ${s.state !== 'queued' ? `<ol class="update-steps">${UPDATE_STEPS.map(([k, l], i) => `<li class="${i === cur ? 'cur' : ''}">${icon(i)} ${l}</li>`).join('')}</ol>` : ''}
    ${log ? `<details ${s.state === 'error' ? 'open' : ''}><summary>${L('Logboek')}</summary><pre class="update-log">${esc(log)}</pre></details>` : ''}
  </div>`;
}

let updateFails = 0;   // opeenvolgende keren geen antwoord (RzSense wordt herstart)
let updatePollAt = 0;  // laatste vraag die een antwoord (of fout) kreeg; voor de waakhond hieronder
function pollUpdate() {
  clearTimeout(updatePoll);
  updatePoll = setTimeout(async () => {
    let r;
    // Hooguit 10 seconden wachten: tijdens het herstarten van PHP of Apache kan een verzoek anders blijven hangen
    try { r = await Promise.race([api('update_status'), new Promise((res, rej) => setTimeout(() => rej(new Error('timeout')), 10000))]); updateFails = 0; if (updDownAt) { updDownMs += Date.now() - updDownAt; updDownAt = 0; } }
    catch (ex) {   // even onbereikbaar tijdens het installeren
      updatePollAt = Date.now();
      updateFails++;
      if (!updDownAt) updDownAt = Date.now();
      const rn = $('#upd-now');
      if (rn) rn.hidden = false;
      pollUpdate();
      return;
    }
    updatePollAt = Date.now();
    // 1.206.1: een "klaar" van een update van vóór deze aanvraag (oude RzSense) is nog niet deze update
    if (r.status && r.status.state === 'ok' && updReqAt && ((+r.status.started || +r.status.at || 0) * 1000) < updReqAt - 30000) {
      r.status = { state: 'queued', step: 'queued', message: L('Wachten op de hulpdienst…'), at: updReqAt / 1000, stuck: Date.now() - updReqAt > 120000 };
    }
    showUpdateProgress(r.status, r.log);
    showUpdateDialog(r.status, r.log);
    if (r.status && ['queued', 'running'].includes(r.status.state)) return pollUpdate();
    if (r.status && r.status.state === 'ok') {
      toast(r.status.message);
      setTimeout(() => location.reload(), 3000);   // nieuwe versie laden
    }
  }, 1500);
}

// Waakhond: staat het venster open maar kwam er 20 seconden geen antwoord (bv. de telefoon sliep), dan opnieuw beginnen
setInterval(() => { if (updateDialogShown() && Date.now() - updatePollAt > 20000) { updatePollAt = Date.now(); pollUpdate(); } }, 5000);
document.addEventListener('visibilitychange', () => { if (!document.hidden && updateDialogShown()) pollUpdate(); });

// ---------------------------------------------------------------- Update-venster: vraag, voortgangsbalk en wat er gebeurt
// Alleen het venster van de RzSense-update; dat van pakketten bijwerken (Kwetsbaarheden) heeft dezelfde opmaak, maar is vu-dlg
const updateDialogShown = () => $('#modal').open && !!$('#modal-body .upd-dlg:not(.vu-dlg)');
let updatePct = 0;   // de balk gaat tijdens één update nooit terug

// 1.204.0: de bijwerk-vensters (RzSense en Pakketten bijwerken) in een nieuw jasje: kop met versies, ring, tijdlijn, terminal
const UPD_ARROW = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 19V5M5 12l7-7 7 7"/></svg>';
const UPD_SRV = '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="7" rx="2"/><rect x="3" y="13" width="18" height="7" rx="2"/><path d="M7 7.5h.01M7 16.5h.01"/></svg>';
function updHead(title, chips = [], icon = UPD_ARROW) {
  return `<div class="upd-head"><span class="upd-ic">${icon}</span><div class="upd-ht"><b>${title}</b>${chips.length ? `<div class="upd-vers">${chips.join('<span class="upd-arrow">→</span>')}</div>` : ''}</div>
    <button type="button" class="upd-x icon-btn" value="cancel" formnovalidate aria-label="${esc(L('Sluiten'))}">✕</button></div>`;
}
const updChip = (v, isNew) => `<span class="upd-chip${isNew ? ' new' : ''}">${esc(v)}</span>`;
/** Voortgangsring; pct null = onbekend (een draaiende boog). */
function updRing(pct, sub) {
  const C = +(2 * Math.PI * 60).toFixed(2);
  const known = typeof pct === 'number';
  return `<div class="upd-ring${known ? '' : ' indet'}" role="progressbar" aria-valuemin="0" aria-valuemax="100" ${known ? `aria-valuenow="${pct}"` : ''}>
    <svg viewBox="0 0 140 140"><circle class="trk" cx="70" cy="70" r="60"/><circle class="val" cx="70" cy="70" r="60" stroke-dasharray="${C}" stroke-dashoffset="${known ? (C * (1 - pct / 100)).toFixed(2) : (C * 0.72).toFixed(2)}"/></svg>
    <div class="upd-pct"><b>${known ? pct + '%' : '…'}</b>${sub ? `<small>${sub}</small>` : ''}</div></div>`;
}
/** Tijdlijn van de stappen: klaar ✓, bezig (pulserend), mislukt ✕; detail onder de huidige stap, duur rechts. */
function updSteps(steps, cur, state, detail, durs = []) {
  return `<ol class="upd-tl">${steps.map(([, l], i) => {
    const cls = state === 'ok' || i < cur ? 'done' : i === cur ? (state === 'error' ? 'fail' : 'cur') : '';
    const mark = cls === 'done' ? '✓' : cls === 'fail' ? '✕' : i + 1;
    return `<li class="${cls}"><span class="upd-dot">${mark}</span><span class="upd-st">${l}${i === cur && detail && state !== 'ok' ? `<small>${detail}</small>` : ''}</span><span class="upd-dur">${durs[i] || ''}</span></li>`;
  }).join('')}</ol>`;
}
// 1.206.2: het venster wordt elke paar seconden opnieuw opgebouwd; wat je zelf open- of dichtklapte (logboek, Alles lezen)
// en waar je in het logboek stond, blijft zo staan
const updKept = { log: null, notes: null, scroll: null };
document.addEventListener('toggle', (e) => {
  const d = e.target;
  if (!d.closest || !d.closest('#modal-body .upd-dlg')) return;
  if (d.classList.contains('upd-term')) updKept.log = d.open;
  if (d.classList.contains('upd-notes')) updKept.notes = d.open;
}, true);
function updKeepScroll() {
  const lg = $('#modal-body .upd-log');
  // onderaan (of nog nooit gescrold) = mee naar beneden; anders de plek houden
  updKept.scroll = lg && lg.scrollTop + lg.clientHeight < lg.scrollHeight - 8 ? lg.scrollTop : null;
}
function updLogScroll() {
  const lg = $('#modal-body .upd-log');
  if (lg) lg.scrollTop = updKept.scroll === null ? lg.scrollHeight : updKept.scroll;
}
function updLog(log, open, n = 12) {
  if (updKept.log !== null) open = updKept.log;
  const lines = (log || '').trim().split('\n').filter(Boolean);
  if (!lines.length) return '';
  return `<details class="upd-term" ${open ? 'open' : ''}><summary><span>▸ ${L('Logboek')}</span><span>${L('{n} regels', { n: lines.length })}</span></summary><pre class="upd-log">${esc(lines.slice(-n).join('\n'))}</pre></details>`;
}
const updMmss = (ms) => { const s = Math.max(0, Math.round(ms / 1000)); return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`; };
const updSecs = (ms) => (ms >= 60000 ? updMmss(ms) : L('{n} s', { n: Math.max(1, Math.round(ms / 1000)) }));
/** Highlights uit de changelog: de vetgedrukte punten (eerst Nieuw), als kaartjes. */
function updHighlights(notes) {
  const out = [];
  const plain = (t) => String(t).replace(/\*\*|`/g, '').replace(/\*(.+?)\*/g, '$1').trim();
  for (const n of notes || []) {
    let sec = '';
    for (const line of String(n.text || '').split('\n')) {
      if (/^### /.test(line)) { sec = line.slice(4).trim(); continue; }
      const m = line.match(/^- \*\*(.+?)\*\*[:\s]*(.*)$/) || line.match(/^- (.+?)()$/);
      if (!m) continue;
      const t = plain(m[1]);
      const lead = (t.match(EMOJI_LEAD) || [''])[0].trim();
      let d = plain(m[2]);
      if (d.length > 110) d = d.slice(0, 107).replace(/\s+\S*$/, '') + '…';
      out.push({ v: n.version, fix: /opgelost|fixed/i.test(sec), ic: lead || (/opgelost|fixed/i.test(sec) ? '🛠️' : '✨'), t: t.replace(EMOJI_LEAD, '').replace(/[:.]$/, ''), d });
    }
  }
  return out.sort((a, b) => a.fix - b.fix).slice(0, 3);
}
function updNotesBlock(notes) {
  if (!(notes || []).length) return '';
  const hl = updHighlights(notes);
  const all = notes.length === 1 ? L('Alles lezen (1 versie)') : L('Alles lezen ({n} versies)', { n: notes.length });
  return `<div class="upd-news"><div class="upd-news-h"><span>${L('Wat is er nieuw')}</span></div>
    ${hl.map((h) => `<div class="upd-hl"><span class="upd-hl-ic">${esc(h.ic)}</span><div><b>${esc(h.t)}</b>${h.d ? `<span>${esc(h.d)}</span>` : ''}</div><em>${esc(h.v)}</em></div>`).join('')}
    <details class="update-notes upd-notes"><summary>${all}</summary>
      ${notes.map((n) => `<div class="un-ver"><h3>${esc(n.version)} <span class="muted small">${esc(n.date)}</span></h3>${mdLite(n.text)}</div>`).join('')}</details></div>`;
}

// Tijden van deze update (in de browser): wanneer elke stap begon, en hoe lang RzSense onbereikbaar was
let updT = {}, updT0 = 0, updEnd = 0, updDownAt = 0, updDownMs = 0, updBackup = null, updReqAt = 0;
function updResetTimes() { updT = {}; updT0 = Date.now(); updEnd = 0; updDownAt = 0; updDownMs = 0; }

/** Vraag "wil je bijwerken?" (met back-up), of meteen de voortgang als er al een update loopt. */
async function openUpdateDialog(pick = false) {
  let u = updateInfo;
  try { u = await api('update_info'); updateInfo = u; } catch (ex) { if (!u) { toast(ex.message, 'err'); return; } }
  if (u.status && ['queued', 'running'].includes(u.status.state)) { showUpdateDialog(u.status, '', true); pollUpdate(); return; }
  const versions = (u.versions || []).filter((v) => v.version !== u.current);
  if ((!u.available && !(pick && versions.length)) || u.unavailable) {
    // Niets bij te werken, of het kan (nog) niet vanuit RzSense: de uitleg staat bij Instellingen
    showTab('settings/update');
    return;
  }
  const to = u.available ? u.latest : '?';
  modal({
    title: L('RzSense bijwerken'),
    body: `<div class="upd-dlg upd-ask">
      ${updHead(L('RzSense bijwerken'), [updChip(u.current), `<span id="upd-to">${updChip(to, true)}</span>`])}
      <div class="upd-body">
        ${updNotesBlock(u.notes)}
        <div class="upd-opts">
          <label class="upd-opt"><span class="grow">${L('Eerst een back-up maken')}<small>${L('Database en instellingen. Aanbevolen.')}</small></span>
            <span class="switch"><input type="checkbox" name="backup" ${u.backup ? 'checked' : ''}><span></span></span></label>
          ${versions.length ? `<label class="upd-opt"><span class="grow">${L('Versie')}<small>${L('Een oudere kiezen = terugzetten (met bevestigen)')}</small></span>
            <select name="version"><option value="">${L('De nieuwste ({v})', { v: esc(u.latest || '?') })}</option>
              ${versions.map((v) => `<option value="${esc(v.version)}">${esc(v.version)}${v.date ? ` – ${esc(v.date)}` : ''}${verCmp(v.version, u.current) < 0 ? ` · ${L('ouder: terugzetten')}` : ''}</option>`).join('')}</select></label>` : ''}
        </div>
        ${versions.length ? `<div id="upd-older" class="callout small" hidden>${L('⚠️ <b>Terugzetten naar een oudere versie.</b> Je instellingen en gegevens blijven staan; de database blijft zoals hij is (nieuwere kolommen worden niet gebruikt). Wat er sindsdien bij kwam, werkt niet meer. Automatisch bijwerken pauzeert tot je weer naar de nieuwste gaat. Agents hoef je niet terug te zetten.')}
          ${confirmField('TERUGZETTEN')}</div>` : ''}
        <div class="upd-facts"><span>${L('RzSense is tijdens het installeren even niet bereikbaar')}</span><span>${L('Agents houden hun metingen vast en geven tot {n} min geen alarm', { n: u.hold_min || 5 })}</span><span>${L('Dit venster laat zien hoe ver het is')}</span></div>
        ${(u.hold_old || []).length ? `<p class="callout small">⚠️ ${L('Deze agents zijn ouder dan {v} of onversleuteld en kunnen tijdens de update alarm geven: {names}', { v: '1.82.0', names: esc(u.hold_old.slice(0, 8).join(', ') + (u.hold_old.length > 8 ? ' …' : '')) })}</p>` : ''}
      </div></div>`,
    buttons: [
      { label: L('Annuleren'), onClick: () => $('#modal').close() },
      { label: '⬆ ' + (u.available ? L('Bijwerken naar {v}', { v: u.latest }) : L('Bijwerken')), cls: 'primary', onClick: async (btn) => {
        const f = $('#modal-form');
        const backup = f.backup.checked;
        const version = f.version ? f.version.value : '';
        btn.disabled = true;
        try {
          await api('update_start', { backup, version, confirm: f.confirm ? f.confirm.value : '' });
          if ($('#settings-form')) $('#settings-form').update_backup.checked = backup;   // keuze is opgeslagen
          updatePct = 0;
          updResetTimes();
          updReqAt = Date.now();   // 1.206.1
          updBackup = backup;
          const s = { state: 'queued', step: 'queued', message: L('Wachten op de hulpdienst…'), at: Date.now() / 1000, from: u.current, to: version || u.latest };
          showUpdateDialog(s, '', true);
          showUpdateProgress(s, '');
          pollUpdate();
        } catch (ex) { modalError(ex.message); btn.disabled = false; }
      } },
    ],
  });
  $('#modal').classList.add('upd-modal');
  // Een andere versie gekozen: de chip mee, en bij een oudere de waarschuwing en bevestigen
  const sel = $('#modal-form').version;
  if (sel) sel.onchange = () => {
    $('#upd-older').hidden = !(sel.value && verCmp(sel.value, u.current) < 0);
    $('#upd-to').innerHTML = updChip(sel.value || u.latest || '?', true);
  };
}

/** Percentage van de balk: van het script (pct), anders een schatting per stap. */
function updatePercent(s) {
  if (s.state === 'ok') return 100;
  const guess = { queued: 2, check: 4, backup: 10, download: 30, install: 45, klaar: 100 }[s.step] ?? 2;
  updatePct = Math.max(updatePct, typeof s.pct === 'number' ? s.pct : guess);
  return updatePct;
}

/** Het voortgangsvenster bijwerken (of openen, als er geen ander venster openstaat). */
function showUpdateDialog(s, log, force = false) {
  if (!s) return;
  if (!force && $('#modal').open && !updateDialogShown()) return;   // niet over een ander venster heen
  const now = Date.now();
  if (!updT0) updT0 = s.at ? Math.min(now, s.at * 1000) : now;
  const pct = updatePercent(s);
  const cur = s.state === 'ok' ? UPDATE_STEPS.length - 1 : UPDATE_STEPS.findIndex(([k]) => k === s.step);
  if (cur >= 0 && !updT[cur]) updT[cur] = now;
  if (s.state !== 'running' && s.state !== 'queued' && !updEnd) updEnd = now;
  // Duur per afgeronde stap (alleen als we het begin van die stap en de volgende gezien hebben)
  const durs = UPDATE_STEPS.map((_, i) => (updT[i] && updT[i + 1] && i < cur ? updSecs(updT[i + 1] - updT[i]) : i === cur && s.state === 'running' ? '…' : ''));
  // Waar de installatie nu mee bezig is: bij Installeren het onderdeel van het installatiescript
  const part = (s.detail || '').match(/^(\d+\/\d+) (.*)$/);
  const detail = s.state === 'queued' ? (s.agents ? esc(s.message || '') : L('Wachten op de hulpdienst…'))   // 1.205.0: eerst de agents waarschuwen
    : s.state === 'error' ? esc(s.message || L('Bijwerken mislukt'))
    : part ? L('Onderdeel {n}: {what}', { n: esc(part[1].replace('/', ' ' + L('van') + ' ')), what: esc(L(part[2])) }) : esc(s.message || '');
  const chips = s.from && s.to ? [updChip(s.from), updChip(s.to, true)] : s.to ? [updChip(s.to, true)] : [];
  const elapsed = updMmss((updEnd || now) - updT0);
  let body;
  if (s.state === 'ok') {
    const took = updEnd - updT0;
    body = `<div class="upd-dlg ok">${updHead(L('Bijgewerkt'), chips)}
      <div class="upd-body">
        <div class="upd-done"><span class="upd-check"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></span>
          <b>${L('RzSense draait nu op {v}', { v: esc(s.to || '') })}</b><span class="muted">${L('De pagina wordt over 3 seconden herladen.')}</span></div>
        <div class="upd-stats">
          <div><b>${took > 1500 ? updSecs(took) : '–'}</b><small>${L('duur')}</small></div>
          <div><b>${updBackup === null ? '–' : updBackup ? '✓' : '✕'}</b><small>${L('back-up gemaakt')}</small></div>
          <div><b>${updDownMs ? updSecs(updDownMs) : '–'}</b><small>${L('niet bereikbaar')}</small></div>
        </div>
        ${s.detail ? `<p class="muted small upd-durs">${esc(s.detail)}</p>` : ''}
        <div class="upd-reload"><i></i></div>
      </div></div>`;
  } else {
    const nothing = s.state === 'error' && cur >= 0 && cur < UPDATE_STEPS.findIndex(([k]) => k === 'install');
    body = `<div class="upd-dlg ${s.state}">${updHead(s.state === 'error' ? L('Bijwerken mislukt') : L('Bezig met bijwerken…'), chips)}
      <div class="upd-body">
        <div class="upd-prog">${updRing(pct, s.state === 'error' ? L('gestopt') : L('{t} verstreken', { t: elapsed }))}${updSteps(UPDATE_STEPS, Math.max(cur, 0), s.state === 'queued' ? 'running' : s.state, detail, durs)}</div>
        <div class="upd-restart" id="upd-now" ${updateFails ? '' : 'hidden'}><i></i>${L('RzSense wordt herstart; dit venster gaat vanzelf verder zodra hij terug is.')}</div>
        ${s.state === 'queued' && s.stuck ? `<p class="warn-txt small">${L('De hulpdienst reageert niet. Controleer op de server:')} <code>systemctl status rzmon-update.path</code></p>` : ''}
        ${s.state === 'error' ? `<div class="upd-err"><b>${nothing ? L('Er is niets veranderd.') : L('Het bijwerken is gestopt.')}</b>
          <span>${nothing ? L('Je draait nog steeds op {v}.', { v: esc(s.from || (updateInfo && updateInfo.current) || '') }) : L('Kijk in het logboek wat er misging.')}${updBackup ? ' ' + L('De back-up van vandaag staat bij Instellingen → Back-up.') : ''}</span></div>` : ''}
        ${s.stale ? `<p class="small">${L('Controleer op de server:')} <code>systemctl status rzmon-update.service</code> ${L('en')} <code>tail -30 /var/lib/rzmon/update.log</code></p>` : ''}
        ${updLog(log, s.state === 'error')}
      </div></div>`;
  }
  if (updateDialogShown()) updKeepScroll(); else { updKept.log = null; updKept.scroll = null; }
  modal({
    title: L('RzSense bijwerken'),
    body,
    buttons: s.state === 'ok' ? [{ label: L('Nu herladen'), cls: 'primary', onClick: () => location.reload() }]
      : s.state === 'error' ? [{ label: L('Sluiten'), onClick: () => $('#modal').close() }, { label: '↻ ' + L('Opnieuw proberen'), cls: 'primary', onClick: () => { $('#modal').close(); openUpdateDialog(); } }]
      : [{ label: L('Op de achtergrond'), onClick: () => $('#modal').close() }],
  });
  const dlg = $('#modal');
  dlg.classList.add('upd-modal');
  const ft = $('#modal-footer');
  if (s.state === 'running' || s.state === 'queued') ft.insertAdjacentHTML('afterbegin', `<span class="upd-note">${L('Je kunt dit venster sluiten; het bijwerken gaat door.')}</span>`);
  updLogScroll();
}

// ---------------------------------------------------------------- Back-up
let backupInfo = null;
let backupUnlockedUntil = 0;   // downloaden zonder opnieuw te bevestigen tot dit moment
const fmtSize = (b) => (b >= 1048576 ? `${dec((b / 1048576).toFixed(1))} MB` : `${Math.max(1, Math.round(b / 1024))} kB`);
const fmtDateTime = (dt) => new Date(dt.replace(' ', 'T')).toLocaleString(LOCALE,
  { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });

function backupFormToggle() {
  const f = $('#settings-form');
  $('.backup-weekday', f).hidden = f.backup_freq.value !== 'weekly';
  $('.update-time', f).hidden = !f.update_auto.checked;   // tijdstip alleen bij automatisch bijwerken
}

async function loadBackups() {
  const st = $('#backup-status');
  try { backupInfo = await api('backup_info'); } catch (ex) { st.textContent = ex.message; return; }
  const b = backupInfo;
  backupUnlockedUntil = Date.now() + b.unlocked * 1000 - 5000;
  ['#backup-now', '#backup-upload'].forEach((id) => ($(id).disabled = !!b.problem));
  if (b.problem) {
    st.innerHTML = `<b class="warn-txt">⚠️ ${esc(b.problem)}.</b> ${L('Voer dit één keer uit op de server:')}${copyBox('cmd-backup-fix', b.fix_cmd)}`;
    wireCopy(st);
    $('#backup-list').innerHTML = '';
    return;
  }
  const parts = [];
  if (b.last_error) parts.push(`<b class="bad">✘ ${L('Automatische back-up mislukt: {err}', { err: esc(b.last_error) })}</b> ${L('(RzSense probeert het elk uur opnieuw)')}`);
  const lastAuto = b.list.find((x) => x.type === 'auto');
  if (lastAuto) parts.push(L('Laatste automatische: <b>{ago}</b>', { ago: ago(lastAuto.at) }));
  parts.push(b.next ? L('Volgende: {date}', { date: fmtDateTime(b.next) }) : L('Automatische back-up staat uit'));
  if (!b.has_pass) parts.push(`<b class="warn-txt">⚠️ ${L('Geen zip-wachtwoord: back-ups worden niet versleuteld')}</b>`);
  if (!b.encryption) parts.push(`<b class="warn-txt">⚠️ ${L('Deze PHP kan geen versleutelde zip maken (libzip te oud)')}</b>`);
  st.innerHTML = parts.join(' · ');
  $('#backup-list').innerHTML = b.list.length ? b.list.map((x) => `
    <div class="key-row">
      <span class="grow"><strong>${fmtDateTime(x.at)}</strong> <span class="muted small">· ${esc(x.type_label)}</span><br>
        <span class="muted small">${fmtSize(x.size)} · ${x.encrypted ? '🔒 ' + L('versleuteld') : '🔓 ' + L('niet versleuteld')}${x.history ? '' : ' · ' + L('zonder meethistorie')}${x.version ? ` · v${esc(x.version)}` : ''}${x.server ? ` · ${esc(x.server)}` : ''}${x.valid ? '' : ` · <b class="bad">${L('beschadigd')}</b>`}</span></span>
      <button type="button" class="icon-btn" title="${L('Downloaden als zip')}" data-bk="dl" data-file="${esc(x.file)}">⬇</button>
      <button type="button" class="icon-btn" title="${L('Terugzetten')}" data-bk="restore" data-file="${esc(x.file)}" ${x.valid ? '' : 'disabled'}>↺</button>
      <button type="button" class="icon-btn" title="${L('Verwijderen')}" data-bk="del" data-file="${esc(x.file)}">🗑</button>
    </div>`).join('') : `<p class="muted small">${L('Nog geen back-ups.')}</p>`;
  settingsSummaries();
}

async function backupNow(e) {
  const b = e.currentTarget;
  b.disabled = true;
  b.textContent = '⏳ ' + L('Bezig…');
  try {
    const r = await api('backup_create', {});
    toast(L('Back-up gemaakt ({size})', { size: fmtSize(r.size) }));
  } catch (ex) { toast(L('Back-up') + ': ' + ex.message, 'err'); }
  b.disabled = false;
  b.textContent = '💾 ' + L('Nu back-up maken');
  loadBackups();
}

async function onBackupListClick(e) {
  const b = e.target.closest('[data-bk]');
  if (!b) return;
  const file = b.dataset.file;
  if (b.dataset.bk === 'dl') backupDownload(file);
  else if (b.dataset.bk === 'restore') backupRestore(file);
  else if (b.dataset.bk === 'del') {
    if (!confirm(L('Deze back-up verwijderen?'))) return;
    try { await api('backup_delete', { file }); toast(L('Back-up verwijderd')); }
    catch (ex) { toast(ex.message, 'err'); }
    loadBackups();
  }
}

function backupDownload(file) {
  const go = () => {
    const a = document.createElement('a');
    a.href = 'api.php?' + new URLSearchParams({ action: 'backup_download', file });
    a.download = file;
    document.body.append(a);
    a.click();
    a.remove();
  };
  if (Date.now() < backupUnlockedUntil) return go();
  modal({
    title: '⬇ ' + L('Back-up downloaden'),
    body: `<p style="margin-top:0">${L('De zip bevat ook <code>config.php</code> met het databasewachtwoord. Bevestig daarom eerst; daarna kun je 10 minuten downloaden zonder opnieuw te bevestigen.')}</p>
      ${backupInfo?.has_pass ? '' : `<p class="callout small">⚠️ ${L('Deze back-up is niet versleuteld. Stel een zip-wachtwoord in voor de volgende back-ups.')}</p>`}
      ${confirmField('DOWNLOADEN')}`,
    buttons: [{ label: '⬇ ' + L('Downloaden'), cls: 'primary', submit: true }],
    onSubmit: async (d) => {
      const r = await api('backup_unlock', { confirm: d.confirm });
      backupUnlockedUntil = Date.now() + r.unlocked * 1000 - 5000;
      setTimeout(go, 50);
    },
  });
}

function backupRestore(file) {
  const x = (backupInfo?.list || []).find((b) => b.file === file);
  if (!x) return;
  modal({
    title: '↺ ' + L('Back-up terugzetten'),
    body: `<p style="margin-top:0">${L('De database gaat terug naar <b>{date}</b>{server}.', { date: fmtDateTime(x.at), server: x.server ? ' ' + L('(server {name})', { name: esc(x.server) }) : '' })}
        ${L('Wat daarna is veranderd aan servers, checks, instellingen en gebruikers gaat verloren.')}</p>
      <ul class="small">
        <li>${L('RzSense maakt eerst een <b>veiligheidsback-up</b> van nu. Daarmee kun je altijd terug.')}</li>
        <li>${L('Het back-upschema en het zip-wachtwoord blijven zoals ze nu zijn.')}</li>
        ${x.history ? '' : `<li>${L('Deze back-up is zonder meethistorie: de huidige grafieken blijven staan.')}</li>`}
        <li>${L('Gebruikers en wachtwoorden worden die uit de back-up; misschien moet je opnieuw inloggen.')}</li>
        <li>${L('<code>config.php</code> wordt hier niet teruggezet. Voor een nieuwe server: zie de handleiding.')}</li>
      </ul>
      ${x.encrypted ? `<label>${L('Wachtwoord van deze zip')} <span class="hint">${L('(leeg = het ingestelde zip-wachtwoord)')}</span><input name="zip_pass" type="password" autocomplete="off"></label>` : ''}
      ${confirmField('HERSTELLEN')}`,
    buttons: [{ label: '↺ ' + L('Terugzetten'), cls: 'primary', submit: true }],
    onSubmit: async (d) => {
      const r = await api('backup_restore', { ...d, file });
      setTimeout(() => modal({
        title: '✔ ' + L('Back-up teruggezet'),
        body: `<p style="margin-top:0">${L('De database is teruggezet.')}${r.safety ? ' ' + L('De toestand van daarvoor staat in de veiligheidsback-up {file}.', { file: `<code>${esc(r.safety)}</code>` }) : ''}</p>
          <p class="muted small">${L('De pagina wordt opnieuw geladen.')}</p>`,
        buttons: [{ label: 'OK', cls: 'primary', submit: true }],
        onSubmit: async () => location.reload(),
      }), 50);
    },
  });
}

/** Zip uploaden in stukken van 1 MB (dan maakt de upload-limiet van PHP niet uit). */
async function backupUpload(file) {
  if (!file) return;
  const btn = $('#backup-upload');
  const CHUNK = 1024 * 1024;
  if (file.size > (backupInfo?.max_upload || Infinity)) { toast(L('Bestand is te groot (maximaal 2 GB)'), 'err'); return; }
  const id = [...crypto.getRandomValues(new Uint8Array(8))].map((v) => v.toString(16).padStart(2, '0')).join('');
  btn.disabled = true;
  try {
    let r = null;
    for (let off = 0; ; off += CHUNK) {
      const final = off + CHUNK >= file.size;
      btn.textContent = `⬆ ${Math.round((Math.min(off + CHUNK, file.size) / (file.size || 1)) * 100)}%`;
      const res = await fetch('api.php?' + new URLSearchParams({ action: 'backup_upload', id, offset: off, final: final ? '1' : '0' }), {
        method: 'POST',
        headers: { 'Content-Type': 'application/octet-stream', 'X-CSRF-Token': CSRF },
        body: file.slice(off, off + CHUNK),
        credentials: 'same-origin',
      });
      r = await res.json().catch(() => ({ error: `HTTP ${res.status}` }));
      if (!res.ok) throw new Error(r.error || `HTTP ${res.status}`);
      if (final) break;
    }
    toast(L('Zip geüpload'));
    await loadBackups();
    backupRestore(r.file);
  } catch (ex) { toast('Upload: ' + ex.message, 'err'); }
  btn.disabled = false;
  btn.textContent = '⬆ ' + L('Zip uploaden');
  $('#backup-file').value = '';
}

// ---------------------------------------------------------------- Analyse (1.106.0)
let anPeriod = uiGet('an_period', 'rzmon-an-period', '30d');
let anData = null;
const AN_PERIODS = [['1d', () => L('24 uur')], ['7d', () => L('7 dagen')], ['30d', () => L('30 dagen')], ['90d', () => L('90 dagen')], ['365d', () => L('1 jaar')]];

// ---------------------------------------------------------------- 1.155.0: Analyse en advies
// Slimme analyses (Insights): elk advies combineert gegevens uit agent, CVE-scan, IDS, netwerkscan en checks, met het
// bewijs, de stappen en (voor beheerders) een knop om het meteen te regelen. Daaronder de analyses in tabbladen.
let iaData = null, iaAn = null, iaFilter = 'open';
let iaTab = (() => { try { return localStorage.getItem('rzmon-an-tab') || 'trends'; } catch (e) { return 'trends'; } })();   // 1.224.0: Trends eerst
const iaOpen = new Set();
const IA_DOM = { access: ['🔑', () => L('Toegang en SSH')], exposure: ['🌐', () => L('Blootstelling van buiten')], vulns: ['🐞', () => L('Kwetsbaarheden en updates')],
  detect: ['🛡️', () => L('Detectie en reactie')], network: ['📡', () => L('Netwerk en apparaten')], recovery: ['💾', () => L('Herstel en monitoring')] };
const IA_SEV = [['t-mu', () => L('LAAG')], ['t-wa', () => L('MIDDEL')], ['t-cr', () => L('HOOG')]];
const IA_EFF = { click: () => L('1 KLIK'), 5: () => L('5 MIN'), 10: () => L('10 MIN'), 15: () => L('15 MIN'), 30: () => L('30 MIN'), 60: () => L('1 UUR+') };
const IA_ST = { done: () => L('Gemeld als gedaan'), later: () => L('Later'), na: () => L('Niet van toepassing') };
const iaScoreCls = (s) => (s >= 85 ? 'ok' : s >= 65 ? 'warn' : 'crit');

async function iaLoad() {
  const days = { '1d': 7, '7d': 7, '30d': 30, '90d': 90, '365d': 90 }[anPeriod] || 30;
  try { [iaData, iaAn] = await Promise.all([api('insights'), api('insight_analyses', null, { days })]); } catch (ex) { iaData = { error: ex.message }; }
}

/** De lijst die nu getoond wordt (filter bovenaan) */
function iaShown() {
  const all = iaData.advices || [];
  const vis = (a) => !a.status || a.status === 'done';
  if (iaFilter === 'open') return all.filter(vis);
  if (iaFilter === 'new') return all.filter((a) => vis(a) && a.new);
  if (iaFilter === 'quick') return all.filter((a) => vis(a) && (a.effort === 'click' || +a.effort <= 5));
  if (iaFilter === 'hidden') return all.filter((a) => a.status === 'later' || a.status === 'na');
  return all.filter((a) => vis(a) && a.dom === iaFilter);
}

function iaTop() {
  const d = iaData, s = d.score, cls = iaScoreCls(s);
  const open = (d.advices || []).filter((a) => !a.status || a.status === 'done');
  const quick = open.filter((a) => a.effort === 'click' || +a.effort <= 5).slice(0, 5);
  const after = Math.min(100, s + quick.reduce((t, a) => t + a.gain, 0));
  const r = 54, C = 2 * Math.PI * r;
  const hist = (d.history || []).map((h) => h.total);
  const domBars = Object.keys(IA_DOM).map((k) => {
    const v = d.domains[k] ?? 100, n = open.filter((a) => a.dom === k).length, worst = open.find((a) => a.dom === k);
    return `<button type="button" class="ia-dom ${iaFilter === k ? 'on' : ''}" data-ia-filter="${k}"><span class="ia-dom-h"><b>${IA_DOM[k][0]} ${esc(IA_DOM[k][1]())}</b>
      <span><b class="ia-v ${iaScoreCls(v)}">${v}</b>${n ? ` <span class="muted small">· ${esc(L('{n} adviezen', { n }))}</span>` : ''}</span></span>
      <span class="ia-meter"><i class="${iaScoreCls(v)}" style="width:${v}%"></i></span><span class="muted small ia-dom-s">${esc(worst ? worst.title : L('Niets te doen'))}</span></button>`;
  }).join('');
  return `<div class="ia-top">
    <div class="cc-card cc-score ia-score ${cls}"><svg width="132" height="132" viewBox="0 0 132 132" aria-hidden="true"><circle cx="66" cy="66" r="${r}" class="cc-ring-bg"/>
        <circle cx="66" cy="66" r="${r}" class="cc-ring" stroke-dasharray="${(C * s / 100).toFixed(1)} ${C.toFixed(1)}" transform="rotate(-90 66 66)"/>
        <text x="66" y="72" text-anchor="middle" class="cc-ring-n">${s}</text><text x="66" y="92" text-anchor="middle" class="cc-ring-s">${esc(L('veiligheid'))}</text></svg>
      <div class="ia-score-t"><span class="cc-hl ${cls}">${esc(cls === 'ok' ? L('Goed beveiligd') : cls === 'warn' ? L('Redelijk · kan beter') : L('Kwetsbaar · nu aanpakken'))}</span>
        <div>${esc(L('{n} open adviezen', { n: open.length }))}${open.filter((a) => a.sev === 2).length ? ` · <b class="crit-txt">${esc(L('{n} hoog risico', { n: open.filter((a) => a.sev === 2).length }))}</b>` : ''}</div>
        ${quick.length && after > s ? `<div class="small">${L('Met de {n} snelste adviezen ga je naar <b>≈ {s}</b>.', { n: quick.length, s: after })}</div>` : ''}
        ${hist.length > 1 ? `${afSpark(hist.slice(-60), 190, 34, '')}<span class="muted small">${esc(L('verloop van de score'))} · ${hist.length >= 2 ? (hist[hist.length - 1] - hist[0] >= 0 ? '↑ ' : '↓ ') + Math.abs(hist[hist.length - 1] - hist[0]) + ' ' + esc(L('punten')) : ''}</span>`
          : `<span class="muted small">${esc(L('Het verloop verschijnt na een paar dagen (elke nacht bewaard)'))}</span>`}</div></div>
    <div class="cc-card ia-doms"><div class="cc-h"><span class="cc-hl">${esc(L('Score per onderdeel'))}</span><span class="muted small">${esc(L('klik voor de adviezen van dat onderdeel'))}</span></div>
      <div class="ia-domgrid">${domBars}</div></div></div>`;
}

function iaCard(a) {
  const open = iaOpen.has(a.key);
  const admin = iaData.admin;
  const acts = (a.acts || []).map((x, i) => {
    const lbl = { upgrade: '⬆ ' + (x.label ? L('Bijwerken op {h}', { h: x.label }) : L('Bijwerken via de agent')), cve: '🐞 ' + x.cve, ip: '🔎 ' + L('Alles over {ip}', { ip: x.ip }),
      block: '⛔ ' + L('Blokkeren'), ids_block: '⛔ ' + L('Nu op Blokkeren zetten'), ids_on: L('IDS aanzetten'), set: '✔ ' + L('Nu aanzetten'), go: (x.label || L('Bekijken')) + ' →' }[x.k] || x.k;
    // 1.181.0: wat iets verandert (bijwerken, blokkeren, een instelling) alleen voor beheerders
    const adm = ['upgrade', 'ids_block', 'set', 'block', 'ids_on'].includes(x.k) ? ' need-admin' : '';
    return `<button type="button" class="btn small-btn${adm} ${i === 0 && adm ? 'primary' : ''}" data-ia-act="${i}">${esc(lbl)}</button>`;
  }).join('');
  const cmds = (a.cmds || []).map(([l, c]) => `<div class="ia-cmd"><span class="small muted">${esc(l)}</span><pre>${esc(c)}</pre><button type="button" class="linkbtn small" data-ia-copy>${esc(L('Kopiëren'))}</button></div>`).join('');
  const st = a.status ? `<span class="cc-tag ${a.status === 'done' ? 'ok' : ''}">${esc(IA_ST[a.status]())}</span>` : '';
  const stBtns = a.status === 'later' || a.status === 'na' ? `<button type="button" class="btn small-btn" data-ia-st="open">${esc(L('Weer tonen'))}</button>`
    : `<button type="button" class="btn small-btn" data-ia-st="done">✔ ${esc(L('Ik heb het gedaan'))}</button><button type="button" class="btn small-btn" data-ia-st="later">${esc(L('Later (7 dagen)'))}</button>
       <button type="button" class="btn small-btn" data-ia-st="na">${esc(L('Niet van toepassing'))}</button>`;
  return `<article class="ia s${a.sev} ${open ? 'open' : ''}" data-ia="${esc(a.key)}">
    <button type="button" class="ia-head" data-ia-toggle aria-expanded="${open}"><i class="ia-bar s${a.sev}"></i>
      <span class="ia-ttl"><b>${a.new ? `<span class="cc-tag warn">${esc(L('NIEUW'))}</span> ` : ''}${esc(a.title)}</b>
        <small class="muted">${IA_DOM[a.dom][0]} ${esc(IA_DOM[a.dom][1]())}${a.host ? ' · ' + esc(a.host) : ''}${a.crit ? ' · 🚨 ' + esc(L('wereldwijd bekend, gemeld')) : ''}</small></span>
      <span class="ia-tags"><span class="tag-s ${IA_SEV[a.sev][0]}">${esc(IA_SEV[a.sev][1]())}</span><span class="tag-s t-cy">${esc((IA_EFF[a.effort] || IA_EFF[30])())}</span><span class="tag-s t-ok">+${a.gain}</span>${st}</span>
      <span class="ia-chev" aria-hidden="true">▾</span></button>
    ${open ? `<div class="ia-body">
      <div class="ia-why"><h4>${esc(L('Waarom (uit je gegevens)'))}</h4><ul>${a.why.map((w) => `<li>${esc(w)}</li>`).join('')}</ul></div>
      <div class="ia-do"><h4>${esc(L('Wat te doen'))}</h4><p>${esc(a.do)}</p>${cmds}${a.note ? `<p class="small warn-txt">⚠ ${esc(a.note)}</p>` : ''}${a.check ? `<p class="small muted">${esc(L('Controleren'))}: <code>${esc(a.check)}</code></p>` : ''}</div>
      <div class="ia-acts">${acts}<span class="ia-sp"></span>${a.status === 'done' ? `<span class="small warn-txt">${esc(L('RzSense ziet het nog; het verdwijnt vanzelf zodra het echt is opgelost.'))}</span>` : ''}${stBtns}</div>
      ${!admin && (a.acts || []).length < 1 ? '' : ''}</div>` : ''}</article>`;
}

function iaList() {
  const all = iaData.advices || [];
  const vis = all.filter((a) => !a.status || a.status === 'done');
  const chips = [['open', L('Alle'), vis.length], ['new', L('Nieuw'), vis.filter((a) => a.new).length], ['quick', L('Snelle winst'), vis.filter((a) => a.effort === 'click' || +a.effort <= 5).length],
    ...Object.keys(IA_DOM).map((k) => [k, IA_DOM[k][0], vis.filter((a) => a.dom === k).length]), ['hidden', L('Verborgen'), all.filter((a) => a.status === 'later' || a.status === 'na').length]];
  const list = iaShown();
  if (!iaOpen.size && !iaList.done) { list.filter((a) => a.sev === 2).slice(0, 2).forEach((a) => iaOpen.add(a.key)); iaList.done = true; }
  const res = iaData.resolved || [];
  return `<section class="ia-sec"><div class="ia-sec-h"><div><h2>${esc(L('Adviezen'))}</h2><span class="muted small">${esc(L('belangrijkste eerst: risico, en winst per minuut werk · elk advies met het bewijs uit je eigen gegevens'))}</span></div>
      <div class="dash-chips ia-chips">${chips.map(([k, l, n]) => `<button type="button" class="dchip ${iaFilter === k ? 'on' : ''}" data-ia-filter="${k}" title="${esc(IA_DOM[k] ? IA_DOM[k][1]() : l)}">${esc(l)} <b>${n}</b></button>`).join('')}</div></div>
    ${list.length ? `<div class="ia-list">${list.map(iaCard).join('')}</div>` : `<p class="good-txt">✔ ${esc(iaFilter === 'open' ? L('Geen adviezen. Netjes!') : L('Niets in deze selectie.'))}</p>`}
    ${res.length ? `<details class="ia-res"><summary>${esc(L('Opgelost in de laatste 30 dagen ({n})', { n: res.length }))}</summary><ul>${res.map((r) => `<li><span class="good-txt">✔</span> ${esc(r.title)}
      <span class="muted small">· ${esc(fmtDateTime(r.at))} · +${r.gain}</span></li>`).join('')}</ul></details>` : ''}</section>`;
}

/** Analyses: aanvallen (wanneer, gebruikersnamen, werken de blokkades) en het aanvalsoppervlak per server */
function iaAttacks(sec) {
  const a = iaAn;
  if (!a) return sec;
  const max = Math.max(1, ...a.heat.flat());
  const days = [L('ma'), L('di'), L('wo'), L('do'), L('vr'), L('za'), L('zo')];
  const heat = `<div class="ia-heat" role="img" aria-label="${esc(L('Aanvallen per weekdag en uur'))}"><span></span>${Array.from({ length: 24 }, (_, h) => `<span class="ia-hh">${h % 3 ? '' : h}</span>`).join('')}
    ${a.heat.map((row, d) => `<span class="ia-hd">${esc(days[d])}</span>${row.map((v, h) => `<i style="opacity:${v ? (0.12 + 0.88 * v / max).toFixed(2) : 0.05}" title="${esc(`${days[d]} ${h}:00 · ${v}`)}"></i>`).join('')}`).join('')}</div>`;
  let peak = [0, 0, 0];
  a.heat.forEach((row, d) => row.forEach((v, h) => { if (v > peak[2]) peak = [d, h, v]; }));
  const users = a.users.length ? a.users.map((u) => `<div class="ia-u"><span class="mono">${esc(u.u)}</span><span class="ia-meter"><i class="${u.exists ? 'crit' : 'warn'}" style="width:${Math.min(100, u.pct * 2)}%"></i></span>
      <span class="small">${esc(dec(u.pct))}%</span><span class="tag-s ${u.exists ? 't-cr' : 't-mu'}">${esc(u.exists ? L('BESTAAT') : L('NIET'))}</span></div>`).join('')
    : `<p class="muted small">${esc(L('Nog geen losse SSH-pogingen (agent 1.74.0 en nieuwer).'))}</p>`;
  const exist = a.users.filter((u) => u.exists).reduce((t, u) => t + u.pct, 0);
  const b = a.blocks;
  const ports = a.ports.length ? anHbars(a.ports.map((p) => ({ label: `${p.svc || L('poort')} ${p.port}`, v: p.n }))) : `<p class="muted small">${esc(L('Geen aanvallen in deze periode.'))}</p>`;
  return anSec('⚔️', L('Aanvallen'), `<div class="an-grid">
    ${anBox(L('Wanneer wordt er aangevallen'), heat + (peak[2] ? `<p class="small muted">${esc(L('Het drukst op {d} rond {h}:00 ({n} pogingen in dat uur).', { d: days[peak[0]], h: peak[1], n: peak[2] }))}</p>` : ''), '', true)}
    ${anBox(L('Welke gebruikersnamen proberen ze'), users + (a.users.length ? `<p class="small muted">${esc(L('{p}% van de pogingen richt zich op accounts die bij jou bestaan.', { p: dec(exist.toFixed(0)) }))}</p>` : ''))}
    ${anBox(L('Werken de blokkades?'), `<div class="an-stats"><div><b class="${b.drop !== null && b.drop >= 80 ? 'good-txt' : 'warn-txt'}">${b.drop === null ? '–' : (b.drop > 0 ? '−' : '') + Math.abs(b.drop) + '%'}</b><span>${esc(L('pogingen in het uur na een blokkade'))}</span></div>
      <div><b>${b.ttb === null ? '–' : esc(anDur(b.ttb))}</b><span>${esc(L('van eerste poging tot blokkade (gem.)'))}</span></div><div><b class="${b.repeat ? 'warn-txt' : ''}">${b.repeat}</b><span>${esc(L('kwamen terug na hun blokkade'))}</span></div></div>`,
      L('Vergelijkt de losse SSH-pogingen in het uur voor en na elke blokkade.'))}
    ${anBox(L('Poorten onder vuur'), ports)}
  </div>`) + sec;
}

function iaSurface() {
  const s = (iaAn && iaAn.surface) || [];
  if (!s.length) return anSec('🎯', L('Aanvalsoppervlak per server'), `<p class="muted">${esc(L('Nog geen servers met een agent die open poorten meldt.'))}</p>`);
  return anSec('🎯', L('Aanvalsoppervlak per server'), `<p class="muted small">${esc(L('Per server de open poorten, de ergste kwetsbaarheid daarop, de aanvallen van buiten, de hardening-score en het risico.'))}</p><div class="table-wrap"><table class="small ia-surf"><thead><tr><th>${esc(L('Server'))}</th><th>${esc(L('Open poorten'))}</th><th>${esc(L('Ergste kwetsbaarheid'))}</th><th class="num">${esc(L('Aanvallen'))}</th><th class="num">${esc(L('Hardening'))}</th><th class="num">${esc(L('Risico'))}</th><th>${esc(L('Adviezen'))}</th></tr></thead><tbody>
    ${s.map((h) => { const n = (iaData.advices || []).filter((x) => x.host_id === h.id && !x.status).length;
      return `<tr><td><b>${esc(h.name)}</b></td><td class="mono">${h.ports.map((p) => `<span title="${esc(p.proc || '')}">${p.port}${p.out ? ' <span class="crit-txt">●</span>' : ''}</span>`).join(' ') || '–'}</td>
      <td>${h.worst ? `<button type="button" class="linkbtn" data-ia-cve="${esc(h.worst.cve)}">${esc(h.worst.cve)}</button> ${urgPill(h.worst.risk, [], true)}${h.worst.kev ? ' ⚠️' : ''}` : '<span class="muted">–</span>'}</td>
      <td class="num">${amN(h.attacks)}</td><td class="num">${h.hardening === null ? '–' : h.hardening}</td><td class="num">${urgPill(h.risk, [], true)}</td>
      <td>${n ? `<button type="button" class="linkbtn" data-ia-host="${h.id}">${esc(L('{n} adviezen', { n }))}</button>` : `<span class="good-txt small">${esc(L('in orde'))}</span>`}</td></tr>`; }).join('')}
  </tbody></table></div><p class="muted small"><span class="crit-txt">●</span> = ${esc(L('in deze periode van buiten aangevallen, dus bereikbaar vanaf internet'))}</p>`);
}

/** De hele pagina: score, adviezen, en de analyses als tabbladen (de bestaande onderdelen van Analyse blijven) */
function iaRender(p) {
  if (!iaData || iaData.error) return `${iaData && iaData.error ? `<p class="form-error">${esc(iaData.error)}</p>` : ''}${p.kpis}${p.qual}${p.rel}${p.cap}${p.sec}${p.net}${p.bk}${p.noise}`;
  if (iaTab === 'trends' && !tnData) tnLoad();   // 1.224.0: pas laden als je het tabblad opent
  const tabs = [['trends', '📉 ' + L('Trends'), tnRender()], ['attacks', '⚔️ ' + L('Aanvallen'), iaAttacks(p.sec)], ['surface', '🎯 ' + L('Blootstelling'), iaSurface()], ['rel', '🟢 ' + L('Betrouwbaarheid'), p.kpis + p.rel],
    ['cap', '📈 ' + L('Capaciteit'), p.cap], ['net', '🌐 ' + L('Netwerk'), p.net], ['bk', '💾 ' + L('Back-ups'), p.bk], ['noise', '🔔 ' + L('Meldingen en ruis'), p.noise + p.qual]];
  if (!tabs.some((t) => t[0] === iaTab)) iaTab = 'trends';
  return `${iaTop()}${iaList()}
    <section class="ia-sec"><div class="ia-sec-h"><div><h2>${esc(L('Analyses'))}</h2><span class="muted small">${esc(L('de patronen achter de adviezen'))}</span></div>
      <div class="seg ia-tabs" role="tablist">${tabs.map(([k, l]) => `<button type="button" class="seg-btn ${k === iaTab ? 'active' : ''}" role="tab" aria-selected="${k === iaTab}" data-ia-tab="${k}">${esc(l)}</button>`).join('')}</div></div>
      <div class="ia-pane">${tabs.find((t) => t[0] === iaTab)[2]}</div></section>`;
}

/** Klikken in het advies-deel (één keer gekoppeld aan #an-body) */
function iaClick(e) {
  const t = e.target.closest('[data-ia-filter], [data-ia-toggle], [data-ia-st], [data-ia-act], [data-ia-copy], [data-ia-tab], [data-ia-cve], [data-ia-host]');
  if (!t) return false;
  e.preventDefault();
  const card = t.closest('[data-ia]'), key = card && card.dataset.ia, adv = key && (iaData.advices || []).find((a) => a.key === key);
  if (t.dataset.iaFilter) { iaFilter = iaFilter === t.dataset.iaFilter && t.dataset.iaFilter !== 'open' ? 'open' : t.dataset.iaFilter; renderAnalytics(); return true; }
  if (t.dataset.iaTab) { iaTab = t.dataset.iaTab; try { localStorage.setItem('rzmon-an-tab', iaTab); } catch (ex) { /* alleen nu */ } renderAnalytics(); return true; }
  if (t.dataset.iaCve) { vulnDetail(t.dataset.iaCve); return true; }
  if (t.dataset.iaHost) { iaFilter = 'open'; const h = (iaData.advices || []).find((a) => a.host_id === +t.dataset.iaHost); if (h) iaOpen.add(h.key); renderAnalytics(); $('.ia-list')?.scrollIntoView({ behavior: 'smooth', block: 'start' }); return true; }
  if (t.dataset.iaToggle !== undefined && key) { iaOpen.has(key) ? iaOpen.delete(key) : iaOpen.add(key); renderAnalytics(); return true; }
  if (t.dataset.iaCopy !== undefined) { const pre = t.parentElement.querySelector('pre'); navigator.clipboard?.writeText(pre.textContent).then(() => toast(L('Gekopieerd')), () => {}); return true; }
  if (t.dataset.iaSt && key) {
    api('insight_set', { key, status: t.dataset.iaSt }).then(async () => {
      toast({ done: L('Gemarkeerd als gedaan; RzSense controleert het zelf'), later: L('7 dagen verborgen'), na: L('Verborgen: niet van toepassing'), open: L('Weer zichtbaar') }[t.dataset.iaSt]);
      await iaLoad(); renderAnalytics();
    }).catch((ex) => toast(ex.message, 'err'));
    return true;
  }
  if (t.dataset.iaAct !== undefined && adv) iaAction(adv, adv.acts[+t.dataset.iaAct]);
  return true;
}

/** Een knop van een advies: altijd met bevestiging als er iets verandert */
function iaAction(a, x) {
  if (!x) return;
  const done = async (msg) => { toast(msg); await iaLoad(); renderAnalytics(); };
  if (x.k === 'go') { if (x.go.startsWith('check:')) checkInfo(x.go.slice(6)); else showTab(x.go); return; }
  if (x.k === 'cve') return vulnDetail(x.cve);
  if (x.k === 'ip') return amDetail(x.ip);
  if (x.k === 'block') return blockDialog(x.ip);
  if (x.k === 'upgrade') return vulnUpgrade({ id: x.host_id, name: x.label || a.host || '?' }, x.pkgs);
  if (x.k === 'ids_block' || x.k === 'ids_on') {
    return modal({
      title: '⛔ ' + (x.k === 'ids_on' ? L('IDS aanzetten') : L('IDS: blokkeren aanzetten')),
      body: `<div style="padding:1rem 1.2rem"><p style="margin-top:0">${L('RzSense gaat dan echt IP-adressen blokkeren op je servers (eigen nftables-tabel van de agent), bij brute force en als jij op ⛔ klikt. Je LAN, RzSense zelf en de lijst <i>Nooit blokkeren</i> worden nooit automatisch geblokkeerd; op TrueNAS wordt alleen gedetecteerd.')}</p>
        ${x.k === 'ids_block' ? confirmField('BLOKKEREN') : ''}</div>`,
      buttons: [{ label: L('Annuleren'), onClick: () => $('#modal').close() }, { label: x.k === 'ids_on' ? L('IDS aanzetten') : L('Blokkeren aanzetten'), cls: 'primary', submit: true }],
      onSubmit: async (d) => { await api('ids_set', x.k === 'ids_on' ? { enabled: true } : { mode: 'block', confirm: d.confirm }); await done(L('Gedaan')); },
    });
  }
  if (x.k === 'set') {
    return modal({
      title: a.title, body: `<div style="padding:1rem 1.2rem"><p style="margin-top:0">${esc(a.do)}</p><p class="muted small">${esc(L('Dit verandert een instelling van RzSense en komt in het wijzigingslogboek, waar je het kunt terugdraaien.'))}</p></div>`,
      buttons: [{ label: L('Annuleren'), onClick: () => $('#modal').close() }, { label: L('Nu aanzetten'), cls: 'primary', submit: true }],
      onSubmit: async () => { await api('settings_save', { [x.name]: x.value }); await done(L('Instelling aangepast')); },
    });
  }
}

function initAnalytics() {
  $('#an-period').onclick = (e) => { const b = e.target.closest('[data-anp]'); if (b) { anPeriod = b.dataset.anp; uiSet('an_period', 'rzmon-an-period', anPeriod); loadAnalytics(); } };
  $('#an-go').onclick = () => { const f = $('#an-from').value, t = $('#an-to').value; if (f && t && f <= t) { anPeriod = `${f}..${t}`; loadAnalytics(); } };
  $('#an-body').onclick = (e) => {
    const tf = e.target.closest('[data-tr-f]');   // 1.224.0: filter van Trends
    if (tf) { tnFilter = tf.dataset.trF; renderAnalytics(); return; }
    if (iaClick(e)) return;   // 1.155.0: adviezen en tabbladen
    const g = e.target.closest('[data-an-go]');
    if (!g) return;
    const go = g.dataset.anGo;
    if (go.startsWith('check:')) checkInfo(go.slice(6)); else showTab(go);
  };
  $('#an-report').onclick = (e) => { const g = e.target.closest('a[data-goto]'); if (g) { e.preventDefault(); showTab(g.dataset.goto); } };   // 1.180.0

}

async function loadAnalytics(fresh = false) {
  $('#an-period').innerHTML = AN_PERIODS.map(([k, l]) => `<button type="button" class="dchip ${anPeriod === k ? 'on' : ''}" data-anp="${k}">${l()}</button>`).join('');
  $('#an-info').textContent = '⏳';
  try { [anData] = await Promise.all([api('analytics', null, { period: anPeriod, ...(fresh ? { fresh: 1 } : {}) }), iaLoad()]); } catch (ex) { $('#an-body').innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  renderAnalytics();
}

/** Getal met eenheid; dec() voor de komma */
const anNum = (v, d = 0) => (v === null || v === undefined ? '–' : dec((+v).toFixed(d)));
const anDur = (s) => (s === null || s === undefined ? '–' : s >= 86400 ? `${anNum(s / 86400, 1)} ${L('dagen')}` : s >= 3600 ? `${anNum(s / 3600, 1)} ${L('uur')}` : `${Math.max(1, Math.round(s / 60))} min`);
const anDay = (d) => new Date(d + 'T12:00:00').toLocaleDateString(LOCALE, { day: 'numeric', month: 'short' });

/** Verschil met de vorige periode: ▲/▼ en of dat goed of slecht is */
function anDelta(now, prev, lowerBetter = false, unit = '%') {
  if (now === null || prev === null || prev === undefined || now === undefined) return `<span class="muted small">${L('geen vorige periode')}</span>`;
  const diff = unit === 'pt' ? now - prev : prev ? (now - prev) / prev * 100 : (now ? 100 : 0);
  if (Math.abs(diff) < (unit === 'pt' ? 0.01 : 0.5)) return `<span class="muted small">= ${L('gelijk')}</span>`;
  const better = lowerBetter ? diff < 0 : diff > 0;
  return `<span class="small ${better ? 'good-txt' : 'crit-txt'}" title="${esc(L('t.o.v. de vorige periode van dezelfde lengte'))}">${diff > 0 ? '▲' : '▼'} ${anNum(Math.abs(diff), unit === 'pt' ? 2 : 0)}${unit === 'pt' ? ' ' + L('punt') : '%'}</span> <span class="muted small">${L('vs. vorige')}</span>`;
}

/** Lijn (of vlak) over de dagen, één reeks, met een tooltip per dag */
function anLine(series, { unit = '', d = 0, h = 110, cls = '' } = {}) {
  const ks = Object.keys(series);
  const vals = ks.map((k) => series[k]);
  const nums = vals.filter((v) => v !== null && v !== undefined);
  if (!nums.length) return `<p class="muted small">${L('Nog geen gegevens in deze periode.')}</p>`;
  const W = 600, top = 6, bot = h - 18;
  let lo = Math.min(...nums), hi = Math.max(...nums);
  if (lo === hi) { lo = Math.min(0, lo); hi = hi || 1; }
  const x = (i) => (ks.length < 2 ? W / 2 : i / (ks.length - 1) * W);
  const y = (v) => bot - (v - lo) / (hi - lo) * (bot - top);
  // Lijn en vlak per aaneengesloten stuk: dagen zonder gegevens blijven leeg
  let path = '', area = '', seg = [];
  const close = () => {
    if (seg.length) area += `M${seg[0][0]},${bot}${seg.map(([px, py]) => `L${px},${py}`).join('')}L${seg[seg.length - 1][0]},${bot}Z`;
    seg = [];
  };
  vals.forEach((v, i) => {
    if (v === null || v === undefined) { close(); return; }
    const p = [x(i).toFixed(1), y(v).toFixed(1)];
    path += `${seg.length ? 'L' : 'M'}${p[0]},${p[1]}`;
    seg.push(p);
  });
  close();
  const step = ks.length < 2 ? W : W / (ks.length - 1);
  const hits = ks.map((k, i) => `<rect x="${(x(i) - step / 2).toFixed(1)}" y="0" width="${step.toFixed(1)}" height="${h}" fill="transparent"><title>${esc(anDay(k))}: ${vals[i] === null ? '–' : anNum(vals[i], d) + unit}</title></rect>`).join('');
  return `<div class="an-chart ${cls}"><svg viewBox="0 0 ${W} ${h}" preserveAspectRatio="none" role="img">
      <line x1="0" x2="${W}" y1="${bot}" y2="${bot}" class="an-axis"/><path d="${area}" class="an-area"/><path d="${path}" class="an-line" vector-effect="non-scaling-stroke"/>${hits}</svg>
    <div class="an-yl"><span>${anNum(hi, d)}${unit}</span><span>${anNum(lo, d)}${unit}</span></div>
    <div class="an-xl"><span>${esc(anDay(ks[0]))}</span><span>${esc(anDay(ks[ks.length - 1]))}</span></div></div>`;
}

/** Staafjes per dag (aantallen), één reeks */
function anBars(series, { h = 90, cls = '' } = {}) {
  const ks = Object.keys(series);
  const vals = ks.map((k) => +series[k] || 0);
  const hi = Math.max(...vals, 0);
  if (!hi) return `<p class="muted small">${L('Niets in deze periode.')}</p>`;
  const W = 600, bot = h - 2, bw = W / ks.length;
  const bars = vals.map((v, i) => {
    const bh = v ? Math.max(2, v / hi * (bot - 4)) : 0;
    return `<g><rect x="${(i * bw + 1).toFixed(1)}" y="0" width="${Math.max(1, bw - 2).toFixed(1)}" height="${h}" fill="transparent"/>${bh ? `<rect class="an-bar" x="${(i * bw + 1).toFixed(1)}" y="${(bot - bh).toFixed(1)}" width="${Math.max(1, bw - 2).toFixed(1)}" height="${bh.toFixed(1)}" rx="2"/>` : ''}<title>${esc(anDay(ks[i]))}: ${anNum(v)}</title></g>`;
  }).join('');
  return `<div class="an-chart ${cls}"><svg viewBox="0 0 ${W} ${h}" preserveAspectRatio="none" role="img"><line x1="0" x2="${W}" y1="${bot}" y2="${bot}" class="an-axis"/>${bars}</svg>
    <div class="an-yl"><span>${anNum(hi)}</span><span>0</span></div><div class="an-xl"><span>${esc(anDay(ks[0]))}</span><span>${esc(anDay(ks[ks.length - 1]))}</span></div></div>`;
}

/** Horizontale balken met label en waarde (ranglijst) */
function anHbars(rows, { max = null, fmt = (v) => anNum(v), cls = () => '' } = {}) {
  if (!rows.length) return `<p class="muted small">${L('Niets in deze periode.')}</p>`;
  const m = max ?? Math.max(...rows.map((r) => +r.v || 0), 1);
  return `<div class="an-hbars">${rows.map((r) => `<div class="an-hrow" title="${esc(r.title || '')}"><span class="an-hl">${r.html ?? esc(r.label)}</span>
    <span class="an-ht"><span class="an-hb ${cls(r)}" style="width:${Math.max(1, (+r.v || 0) / m * 100).toFixed(1)}%"></span></span><span class="an-hv">${fmt(r.v, r)}</span></div>`).join('')}</div>`;
}

/** Heatmap weekdag × uur (één kleur, donkerder = vaker) */
function anHeat(m) {
  const hi = Math.max(...m.flat(), 0);
  if (!hi) return `<p class="muted small">${L('Geen storingen in deze periode.')}</p>`;
  const days = [L('ma'), L('di'), L('wo'), L('do'), L('vr'), L('za'), L('zo')];
  return `<div class="an-heat"><span></span>${Array.from({ length: 24 }, (_, h) => `<span class="an-hh">${h % 3 === 0 ? h : ''}</span>`).join('')}
    ${m.map((row, w) => `<span class="an-hd">${days[w]}</span>${row.map((n, h) => `<span class="an-cell" style="--o:${n ? (0.18 + n / hi * 0.82).toFixed(2) : 0}" title="${esc(days[w])} ${h}:00–${h + 1}:00 · ${n} ${L('storing(en)')}"></span>`).join('')}`).join('')}</div>`;
}

const anSec = (icon, title, body, sub = '') => `<section class="card an-sec"><h2>${icon} ${title}${sub ? ` <span class="muted small">${sub}</span>` : ''}</h2>${body}</section>`;
const anBox = (title, body, help = '', wide = false) => `<div class="an-box${wide ? ' an-wide' : ''}"><h3>${title}</h3>${help ? `<p class="muted small an-help">${help}</p>` : ''}${body}</div>`;

function renderAnalytics() {
  const d = anData;
  const k = d.kpi;
  // Geen vorige periode als er toen nog geen gegevens waren (dan is elk verschil "100%")
  if (!d.since || d.prev[1] < d.since) ['avail', 'incidents', 'mttr', 'alerts', 'security'].forEach((x) => { k[x][1] = null; });
  $('#an-info').textContent = `${anDay(d.from)} – ${anDay(d.to)}${d.since ? ' · ' + L('gegevens sinds {d}', { d: anDay(d.since) }) : ''}${d.cached ? '' : ''}`;
  $('#an-from').value = d.from; $('#an-to').value = d.to;
  $('#an-report').innerHTML = `<a class="btn small-btn" href="#settings/reports" data-goto="settings/reports">📬 ${L('Rapporten')}</a>`;   // 1.180.0: instellen in de beheerportal
  const tile = (lbl, val, sub, spark = '', cls = '') => `<div class="kpi ${cls}"><div class="kpi-lbl">${lbl}</div><div class="kpi-val">${val}</div><div class="kpi-sub">${sub}</div>${spark}</div>`;
  const kspark = (s) => `<div class="an-kspark">${anLine(s, { h: 34, cls: 'an-mini' })}</div>`;
  const score = k.score;
  const kpis = `<div class="kpis an-kpis">
    ${tile(L('Score'), `${score}<small>/100</small>`, score >= 90 ? L('prima') : score >= 70 ? L('een paar aandachtspunten') : L('werk aan de winkel'), '', score >= 90 ? '' : score >= 70 ? 'warn' : 'bad')}
    ${tile(L('Beschikbaarheid'), k.avail[0] === null ? '–' : `${anNum(k.avail[0], 2)}<small>%</small>`, anDelta(k.avail[0], k.avail[1], false, 'pt'), kspark(k.avail[2]))}
    ${tile(L('Storingen'), anNum(k.incidents[0]), anDelta(k.incidents[0], k.incidents[1], true), kspark(k.incidents[2]), k.incidents[0] ? 'warn' : '')}
    ${tile(L('Hersteltijd (gemiddeld)'), anDur(k.mttr[0]), k.mttr[2] ? L('{n} storingen opgelost', { n: k.mttr[2] }) + (k.mttr[1] !== null && k.mttr[1] !== undefined ? ' · ' + anDelta(k.mttr[0], k.mttr[1], true) : '') : L('geen storingen opgelost'))}
    ${tile(L('Meldingen'), anNum(k.alerts[0]), anDelta(k.alerts[0], k.alerts[1], true), kspark(k.alerts[2]))}
    ${tile(L('IDS (critical)'), anNum(k.security[0]), anDelta(k.security[0], k.security[1], true), kspark(k.security[2]), k.security[0] ? 'bad' : '')}
  </div>`;
  // 🎯 Wat nu aanpakken
  const sevCls = ['muted', 'warn-txt', 'crit-txt'], sevIc = ['ℹ️', '⚠️', '🔴'];
  const todo = anSec('🎯', L('Wat nu aanpakken'), d.todo.length
    ? `<ol class="an-todo">${d.todo.map((t) => `<li><span class="${sevCls[t.sev]}">${sevIc[t.sev]}</span> ${t.icon} ${esc(t.text)} <button type="button" class="link-btn small" data-an-go="${esc(t.go)}">${L('bekijken')} →</button></li>`).join('')}</ol>`
    : `<p class="good-txt">✔ ${L('Niets dringends. Netjes!')}</p>`);
  // 🟢 Betrouwbaarheid
  const r = d.reliability;
  const availCls = (x) => (x.v < 95 ? 'crit' : x.v < 99 ? 'warn' : 'ok');
  const rel = anSec('🟢', L('Betrouwbaarheid'), `<div class="an-grid">
    ${anBox(L('Beschikbaarheid per dag (alle servers)'), anLine(d.avail_series, { unit: '%', d: 2 }))}
    ${anBox(L('Beschikbaarheid per server'), anHbars(r.hosts.map((h) => ({ label: h.name, v: h.pct, title: L('~{m} min onbereikbaar', { m: h.down_min }) + (h.mttr ? ' · ' + L('hersteltijd {t}', { t: anDur(h.mttr.avg) }) : '') })),
      { max: 100, fmt: (v, x) => `${anNum(v, 2)}% <span class="muted">${x.title.split(' · ')[0]}</span>`, cls: availCls }), L('Slechtste bovenaan. Gebaseerd op ping, anders TCP en HTTP.'))}
    ${anBox(L('Wanneer gaat het mis? (storingen per weekdag en uur)'), anHeat(r.heat), L('Een donker vakje dat steeds terugkomt wijst op iets geplands: back-ups, updates of een herstart.'))}
    ${anBox(L('Lastigste checks'), r.top.length ? `<table class="vuln-table an-table"><thead><tr><th>${L('Check')}</th><th>${L('Wissels')}</th><th>${L('Niet OK')}</th><th>${L('Laatste oorzaak')}</th></tr></thead><tbody>
      ${r.top.map((c) => `<tr><td><button type="button" class="link-btn" data-an-go="check:${c.id}">${esc(c.name)}</button><br><span class="muted small">${esc(c.host)}</span></td><td>${anNum(c.chg)}</td><td>${anNum(c.bad_pct, 1)}%</td>
        <td class="small muted">${c.last ? esc(String(c.last.message).slice(0, 90)) : '–'}</td></tr>`).join('')}</tbody></table>` : `<p class="muted small">${L('Geen wisselingen in deze periode.')}</p>`, '', true)}
    ${anBox(L('Responstijden (gemiddeld per dag)'), r.resp.length ? r.resp.map((c) => `<div class="an-resp"><div><b>${esc(c.name)}</b> <span class="muted small">${esc(c.host)} · ${L('gem.')} ${anNum(c.avg, 1)} ms${c.trend !== null ? ` · <span class="${c.trend > 20 ? 'warn-txt' : c.trend < -10 ? 'good-txt' : 'muted'}">${c.trend > 0 ? '▲' : '▼'} ${Math.abs(c.trend)}%</span>` : ''}</span></div>${anLine(c.series, { unit: ' ms', d: 1, h: 46, cls: 'an-mini' })}</div>`).join('') : `<p class="muted small">${L('Geen ping- of HTTP-metingen in deze periode.')}</p>`)}
    ${r.reboots.length ? anBox(L('Herstarts'), anHbars(r.reboots.map((x) => ({ label: x.name, v: +x.n })))) : ''}
  </div>`);
  // 📈 Capaciteit
  const c = d.capacity;
  const cap = anSec('📈', L('Capaciteit'), `<div class="an-grid">
    ${anBox(L('Disks: wanneer vol?'), c.disks.length ? anHbars(c.disks.map((x) => ({ label: `${x.host} ${x.mount}`, v: x.pct, days: x.days })), { max: 100,
      fmt: (v, x) => `${anNum(v, 1)}% <span class="${x.days !== null && x.days <= 30 ? 'crit-txt' : 'muted'}">${x.days !== null ? L('vol over ~{n} d', { n: Math.round(x.days) }) : ''}</span>`, cls: (x) => (x.v >= 90 ? 'crit' : x.v >= 80 ? 'warn' : '') }) : `<p class="muted small">${L('Geen diskchecks.')}</p>`, L('Voorspelling uit de groei van de laatste 7 dagen; de eerstvolgende bovenaan.'))}
    ${anBox(L('CPU en RAM per server'), Object.keys(c.res).length ? `<table class="vuln-table an-table"><thead><tr><th>${L('Server')}</th><th>CPU ${L('gem. / piek')}</th><th>RAM ${L('gem. / piek')}</th></tr></thead><tbody>
      ${Object.entries(c.res).map(([h, x]) => `<tr><td>${esc(h)}</td>${['cpu', 'ram'].map((t) => `<td>${x[t] ? `<span class="${x[t].avg >= 85 ? 'crit-txt' : x[t].avg >= 70 ? 'warn-txt' : ''}">${anNum(x[t].avg)}%</span> / ${anNum(x[t].max)}%` : '–'}</td>`).join('')}</tr>`).join('')}</tbody></table>
      <p class="muted small">${L('Hoog gemiddelde = structureel te krap; alleen een hoge piek = korte drukte.')}</p>` : `<p class="muted small">${L('Geen CPU- of RAM-checks.')}</p>`)}
    ${c.pve.length ? anBox(L('Proxmox: grootste guests (RAM)'), anHbars(c.pve.map((g) => ({ label: `${g.kind === 'ct' ? '📦' : '🖥️'} ${g.vmid} ${g.name}`, v: g.mem / 1073741824, title: g.host })), { fmt: (v, g) => `${anNum(v, 1)} GB <span class="muted">${esc(g.title)}</span>` })) : ''}
    ${anBox(L('Groei'), `<p class="small">${L('{h} servers, {c} checks', { h: c.now.hosts, c: c.now.checks })}</p>${anLine(c.growth.checks, { h: 60 })}`, L('Aantal checks per dag (vanaf nu bijgehouden).'))}
  </div>`);
  // 🛡️ Beveiliging
  const s = d.security;
  const lg = s.logins;
  const sec = anSec('🛡️', L('Beveiliging'), `<div class="an-grid">
    ${anBox(L('Mislukte logins per dag'), anBars(s.series.auth_fail))}
    ${anBox(L('IDS-incidenten per dag (critical)'), anBars(s.series.ids, { cls: 'an-crit' }))}
    ${anBox(L('Nieuwe blokkades per dag'), anBars(s.series.blk) + `<p class="muted small">${L('{t} IP\'s geblokkeerd, waarvan {a} automatisch', { t: anNum(s.blk_total), a: anNum(s.blk_auto) })}</p>`)}
    ${anBox(L('Waar komen aanvallen vandaan?'), anHbars(s.countries.map((x) => ({ html: ccTag(x.cc) || esc(x.cc), v: +x.n }))))}
    ${anBox(L('Meest actieve IP\'s'), s.ips.length ? `<table class="vuln-table an-table"><tbody>${s.ips.map((x) => `<tr><td class="mono small">${esc(x.ip)}${x.cc ? ccTag(x.cc) : ''}</td><td>${anNum(x.hits)}×</td><td class="small">${L('{n} server(s)', { n: x.hosts })}</td><td>${x.blocked ? `<span class="good-txt small">⛔ ${L('geblokkeerd')}</span>` : `<span class="warn-txt small">${L('niet geblokkeerd')}</span>`}</td></tr>`).join('')}</tbody></table>` : `<p class="muted small">${L('Niets in deze periode.')}</p>`, '', true)}
    ${anBox(L('Meest aangevallen servers'), anHbars(s.targets.map((x) => ({ label: x.name, v: x.n }))))}
    ${anBox(L('Logins op je servers'), `<div class="an-stats"><div><b>${anNum(lg.ok)}</b><span>${L('geslaagd')}</span></div><div><b class="${lg.outside ? 'warn-txt' : ''}">${anNum(lg.outside)}</b><span>${L('van buiten')}</span></div>
      <div><b class="${lg.night ? 'warn-txt' : ''}">${anNum(lg.night)}</b><span>${L('\'s nachts (0–6 uur)')}</span></div><div><b class="${lg.fail ? 'crit-txt' : ''}">${anNum(lg.fail)}</b><span>${L('mislukt')}</span></div></div>`)}
    ${s.vulns ? anBox(L('Kwetsbaarheden'), `<div class="an-stats">${[4, 3, 2, 1].map((sv) => { const x = s.vulns.by_sev.find((y) => +y.s === sv) || { n: 0, fix: 0 }; return `<div><b class="${sv >= 4 && +x.n ? 'crit-txt' : sv === 3 && +x.n ? 'warn-txt' : ''}">${anNum(x.n)}</b><span>${['', 'low', 'medium', 'high', 'critical'][sv]} · ${L('{n} op te lossen', { n: x.fix })}</span></div>`; }).join('')}</div>${anLine(s.vulns.series, { h: 60 })}`, L('Open kwetsbaarheden per dag (vanaf nu bijgehouden).')) : ''}
    ${s.hardening.length ? anBox(L('Hardening-score per server'), anHbars(s.hardening.map((x) => ({ label: x.name, v: x.score })), { max: 100, fmt: (v) => `${v}/100`, cls: (x) => (x.v < 70 ? 'crit' : x.v < 90 ? 'warn' : 'ok') })) : ''}
  </div>`);
  // 🌐 Netwerk
  const n = d.network;
  const nk = (k2) => (NET_KIND[k2] || NET_KIND.unknown);
  const net = !n.on ? anSec('🌐', L('Netwerk'), `<p class="muted">${L('De netwerkscan staat uit (Instellingen → Beveiliging → Netwerkscan).')}</p>`)
    : anSec('🌐', L('Netwerk'), `<div class="an-grid">
    ${anBox(L('Apparaten'), `<div class="an-stats"><div><b>${n.total}</b><span>${L('totaal')}</span></div><div><b class="${n.new_open ? 'warn-txt' : ''}">${n.new_open}</b><span>${L('nog niet beoordeeld')}</span></div><div><b>${n.blocked}</b><span>${L('geweerd')}</span></div><div><b class="${n.risky.length ? 'crit-txt' : ''}">${n.risky.length}</b><span>${L('met riskante poort')}</span></div></div>
      <h4 class="acc-sub">${L('Nieuwe apparaten per dag')}</h4>${anBars(n.series.new)}`)}
    ${anBox(L('Soorten apparaten'), anHbars(Object.entries(n.kinds).map(([k2, v]) => ({ html: `${nk(k2)[0]} ${esc(nk(k2)[1]())}`, v }))))}
    ${anBox(L('Fabrikanten'), anHbars(Object.entries(n.vendors).map(([k2, v]) => ({ label: k2, v }))))}
    ${Object.keys(n.aps).length ? anBox(L('Wifi: clients per access point'), anHbars(Object.entries(n.aps).map(([k2, v]) => ({ label: k2, v }))) + `<h4 class="acc-sub">${L('Per wifi-netwerk')}</h4>` + anHbars(Object.entries(n.ssids).map(([k2, v]) => ({ label: k2, v })))) : ''}
    ${n.adguard ? anBox(L('DNS (AdGuard Home)'), `<div class="an-stats"><div><b>${anNum(n.adguard.queries)}</b><span>${L('verzoeken')}</span></div><div><b>${anNum(n.adguard.blocked)}</b><span>${L('geblokkeerd')} (${n.adguard.queries ? anNum(n.adguard.blocked / n.adguard.queries * 100, 1) : 0}%)</span></div></div>
      <h4 class="acc-sub">${L('Meeste verzoeken')}</h4>${anHbars(Object.entries(n.adguard.clients).map(([k2, v]) => ({ label: k2, v })))}
      <h4 class="acc-sub">${L('Meest geblokkeerd')}</h4>${anHbars(Object.entries(n.adguard.blocked_domains).map(([k2, v]) => ({ label: k2, v })))}`, L('Uit de statistiek van AdGuard (zijn eigen periode, meestal 24 uur).')) : ''}
  </div>`);
  // 💾 Back-ups
  const b = d.backups;
  const now = Date.now() / 1000;
  const bk = anSec('💾', L('Back-ups'), `<div class="an-grid">
    ${b.pve.length ? anBox(L('Proxmox: laatste back-up per guest'), anHbars(b.pve.map((g) => ({ label: `${g.kind === 'ct' ? '📦' : '🖥️'} ${g.vmid} ${g.name}`, v: g.last ? (now - g.last) / 86400 : 30, g })), { max: 14,
      fmt: (v, x) => (x.g.last ? `${anNum(v, 1)} ${L('dagen')}` : `<span class="crit-txt">${L('nooit')}</span>`) + (x.g.job === 0 ? ` <span class="warn-txt">${L('geen taak')}</span>` : ''), cls: (x) => (!x.g.last || x.v > 7 ? 'crit' : x.v > 2 ? 'warn' : 'ok') }), L('Langer balkje = ouder. Groen tot 2 dagen, oranje tot 7, daarna rood.')) : ''}
    ${b.tasks.length ? anBox(L('Back-uptaken Proxmox'), b.tasks.map((t) => `<p class="small"><b>${esc(t.host)}</b>: ${t.last ? `${t.last.status === 'OK' ? '<span class="good-txt">✔ OK</span>' : '<span class="crit-txt">✘ ' + esc(t.last.status) + '</span>'} · ${esc(new Date(t.last.start * 1000).toLocaleString(LOCALE))}` : L('nog geen taak')}${t.fail && (!t.last || t.fail.start !== t.last.start) ? `<br><span class="muted">${L('Laatst mislukt: {t} ({s})', { t: esc(new Date(t.fail.start * 1000).toLocaleString(LOCALE)), s: esc(t.fail.status) })}</span>` : ''}</p>`).join('')) : ''}
    ${b.hb.length ? anBox(L('Heartbeats (scripts en back-ups)'), `<table class="vuln-table an-table"><tbody>${b.hb.map((x) => `<tr><td><button type="button" class="link-btn" data-an-go="check:${x.id}">${esc(x.name)}</button><br><span class="muted small">${esc(x.host)}</span></td>
      <td>${+x.status === 0 ? '<span class="good-txt">✔</span>' : +x.status === 1 ? '<span class="warn-txt">⚠️</span>' : +x.status === 2 ? '<span class="crit-txt">✘</span>' : '<span class="muted">?</span>'}</td>
      <td class="small">${x.last ? esc(ago(new Date(x.last * 1000).toISOString())) : '–'}${x.dur ? ` · ${L('duur {d}', { d: anDur(x.dur) })}` : ''}</td></tr>`).join('')}</tbody></table>`) : ''}
    ${anBox(L('RzSense zelf'), `<p class="small">${b.rzmon ? L('Laatste back-up van RzSense: {t}', { t: esc(fmtDateTime(b.rzmon)) }) : `<span class="warn-txt">${L('Nog geen back-up van RzSense zelf.')}</span>`}</p>
      ${b.tasks_rz.length ? `<p class="small warn-txt">${L('Achtergrondtaken met een probleem: {list}', { list: esc(b.tasks_rz.map((t) => t.label).join(', ')) })}</p>` : `<p class="small good-txt">✔ ${L('Alle achtergrondtaken lopen.')}</p>`}`)}
  </div>`);
  // 🔔 Meldingen en ruis
  const no = d.noise;
  const noise = anSec('🔔', L('Meldingen en ruis'), `<div class="an-grid">
    ${anBox(L('Meldingen per dag (storingen en herstel)'), anBars(no.series.notify))}
    ${anBox(L('Per kanaal'), anHbars([['📱 Pushover', no.totals.push], ['✉️ ' + L('E-mail'), no.totals.mail], ['🔗 Webhook', no.totals.hook]].map(([l, v]) => ({ html: l, v })))
      + `<p class="muted small">${L('Daarnaast {i} info-meldingen, {d} IDS en {s} beveiliging.', { i: anNum(no.totals.info), d: anNum(no.totals.ids), s: anNum(no.totals.sec) })}</p>`)}
    ${anBox(L('Meeste meldingen'), anHbars(no.top.map((x) => ({ html: `<button type="button" class="link-btn" data-an-go="check:${x.check_id}">${esc(x.name)}</button> <span class="muted small">${esc(x.host)}</span>`, v: +x.n }))))}
    ${anBox(L('Snel weer goed (ruis)'), no.quick.length ? anHbars(no.quick.map((x) => ({ html: `<button type="button" class="link-btn" data-an-go="check:${x.id}">${esc(x.name)}</button> <span class="muted small">${esc(x.host)}</span>`, v: x.n })), { fmt: (v) => `${v}× ${L('binnen 5 min')}` })
      + `<p class="muted small">${L('Zet bij zulke checks "melden na N fouten" op 3: dan krijg je alleen nog een melding als het echt mis is.')}</p>` : `<p class="good-txt small">✔ ${L('Geen checks die steeds binnen 5 minuten herstelden.')}</p>`)}
  </div>`);
  // 🎯 Doelen (SLO) en "na de actie" (1.146.0)
  const qu = d.quality || null;
  let qual = '';
  if (qu) {
    const s = qu.slo, lp = qu.loops;
    const pctTxt = (v, n = 1) => (v === null || v === undefined ? '–' : dec((+v).toFixed(n)) + '%');
    const okCls = (good) => (good ? 'good-txt' : 'crit-txt');
    qual = anSec('🎯', L('Doelen en "na de actie"'), `<div class="an-grid">
      ${anBox(L('Melding binnen {m} minuten', { m: s.notify.target_min }), s.notify.n
        ? `<p class="an-big ${okCls(s.notify.pct >= 95)}">${pctTxt(s.notify.pct)}</p><p class="small">${L('{w} van {n} storingen (doel 95%) · mediaan {a} · 90% binnen {b}', { w: s.notify.within, n: s.notify.n, a: anDur(s.notify.p50), b: anDur(s.notify.p90) })}</p>`
        : `<p class="muted small">${L('Nog geen storingen met een melding in deze periode.')}</p>`,
        L('Van de overgang naar critical tot de eerste melding. Je meldregels tellen mee: met "melden na 10 minuten" haal je 5 minuten nooit.'))}
      ${anBox(L('Agents rapporteren'), s.agents.agents
        ? `<p class="an-big ${okCls(s.agents.coverage >= 99.5)}">${pctTxt(s.agents.coverage, 2)}</p><p class="small">${L('{g} keer stil, samen {t} (doel 99,5%)', { g: s.agents.gaps, t: s.agents.silent_s ? anDur(s.agents.silent_s) : '0 min' })}</p>`
          + (s.agents.hosts.length ? anHbars(s.agents.hosts.map((x) => ({ label: x.host, v: x.secs / 60 })), { fmt: (v) => anDur(v * 60) }) : '')
        : `<p class="muted small">${L('Geen servers met een agent.')}</p>`, L('Vanaf 1.146.0 bijgehouden: elke keer dat een agent langer stil was dan de grens voor "agent stil".'))}
      ${anBox(L('Zelf herstellen'), lp.heal.n
        ? `<p class="an-big ${okCls(lp.heal.pct >= 80)}">${pctTxt(lp.heal.pct)}</p><p class="small">${L('{ok} van {n} keer gelukt (laatste {d} dagen)', { ok: lp.heal.ok, n: lp.heal.n, d: lp.days })}</p>`
          + anHbars(lp.heal.checks.map((x) => ({ html: `<button type="button" class="link-btn" data-an-go="check:${x.id}">${esc(x.name)}</button> <span class="muted small">${esc(x.host)}</span>`, v: x.n, x })),
            { fmt: (v, r) => L('{ok}/{n} gelukt', { ok: r.x.ok, n: v }), cls: (r) => (r.x.ok < r.x.n ? 'warn' : 'ok') })
        : `<p class="muted small">${L('Nog geen herstelacties (of nog niet bijgehouden: vanaf 1.146.0).')}</p>`)}
      ${anBox(L('Automatische blokkades'), lp.blocks.n
        ? `<p class="an-big ${okCls(lp.blocks.pct <= 5)}">${pctTxt(lp.blocks.pct)}</p><p class="small">${L('{e} van {n} vroegtijdig opgeheven (waarschijnlijk onterecht)', { e: lp.blocks.early, n: lp.blocks.n })}</p>`
          + (lp.blocks.list.length ? `<ul class="small">${lp.blocks.list.map((b) => `<li><code>${esc(b.ip)}</code> · ${esc(b.host)} · ${esc(b.reason)} <span class="muted">(${esc(b.removed_by || '?')})</span></li>`).join('')}</ul>` : '')
        : `<p class="muted small">${L('Geen automatische blokkades in deze periode.')}</p>`, L('Vroegtijdig opgeheven door iemand of via de whitelist. Komt een IP vaak terug in deze lijst, zet hem dan op de whitelist of pas de regel aan.'))}
      ${anBox(L('Slimme drempels met méér ruis'), lp.smart.length
        ? anHbars(lp.smart.map((x) => ({ html: `<button type="button" class="link-btn" data-an-go="check:${x.id}">${esc(x.name)}</button> <span class="muted small">${esc(x.host)}</span>`, v: x.after, x })),
            { fmt: (v, r) => L('{a} → {b} warnings ({d} dagen)', { a: r.x.before, b: v, d: r.x.days }), cls: () => 'warn' })
          + `<p class="muted small">${L('Na het aanzetten van slimme drempels méér warnings dan ervoor: zet de gevoeligheid lager of de check terug op vaste drempels.')}</p>`
        : `<p class="good-txt small">✔ ${L('Geen checks die met slimme drempels meer ruis gaven.')}</p>`)}
    </div>`);
  }
  void todo;   // 1.155.0: "Wat nu aanpakken" is vervangen door de adviezen
  $('#an-body').innerHTML = iaRender({ kpis, qual, rel, cap, sec, net, bk, noise });
}

// ---------------------------------------------------------------- 1.224.0: Trends (Analyse → Trends)
// Langzame veranderingen over 90 dagen: een robuuste lijn (Theil-Sen) door de dagwaarden, alleen "beweegt" als de
// verandering groot genoeg en consequent is, en een verwachting wanneer een grens geraakt wordt.
let tnData = null, tnFilter = 'moving';
const TN_GRP = { hw: ['🔋', () => L('Hardware veroudert')], slow: ['🐢', () => L('Langzaam trager')], cap: ['📦', () => L('Capaciteit')],
  rel: ['🟢', () => L('Betrouwbaarheid')], sec: ['🛡️', () => L('Beveiliging en onderhoud')] };

let tnBusy = false;
async function tnLoad() {
  if (tnBusy) return;
  tnBusy = true;
  try { tnData = await api('trends'); } catch (ex) { tnData = { error: ex.message }; }
  tnBusy = false;
  if (iaTab === 'trends') renderAnalytics();
}

const tnFmt = (v, x) => (v === null || v === undefined ? '–' : x.bytes ? fmtBytes(v) : anNum(v, x.d || 0) + (x.unit || ''));
const tnDate = (d) => new Date(d + 'T12:00:00').toLocaleDateString(LOCALE, { day: 'numeric', month: 'long', year: 'numeric' });

/** Pijl en percentage; rood als de richting slecht is, groen als goed, grijs als het niet beweegt */
function tnChip(x) {
  if (!x.sig) return `<span class="tn-chg flat">→ ${L('stabiel')}</span>`;
  const up = x.chg > 0, cls = x.bad ? 'bad' : 'good';
  const val = `${up ? '+' : '−'}${x.chg_abs === null || x.chg_abs === undefined ? anNum(Math.abs(x.chg)) + '%' : x.unit === '%' ? anNum(Math.abs(x.chg_abs), 1) + ' ' + L('pt') : tnFmt(Math.abs(x.chg_abs), { ...x, d: Math.max(x.d || 0, Math.abs(x.chg_abs) < 10 ? 1 : 0) })}`;
  return `<span class="tn-chg ${cls}" title="${esc(L('verandering over {n} dagen volgens de trendlijn', { n: x.per || 30 }))}">${up ? '↗' : '↘'} ${val}<small>/${x.per === 7 ? L('week') : L('maand')}</small></span>`;
}

/** Lijn per dag (of staafjes per week), de trendlijn en de verwachting tot de grens */
function tnSpark(x, H = 74) {
  const ks = Object.keys(x.series || {});
  if (ks.length < 2) return `<p class="muted small">${L('Nog te weinig gegevens.')}</p>`;
  const vals = ks.map((k) => x.series[k]);
  const n = ks.length, ahead = x.sig && x.fit ? Math.min(x.ahead || 0, Math.round(n * 0.5)) : 0, tot = n - 1 + ahead;
  const fitAt = (i) => (x.fit ? x.fit[1] + x.fit[0] * i : null);
  const nums = vals.filter((v) => v !== null);
  let lo = Math.min(...nums), hi = Math.max(...nums);
  if (ahead) { lo = Math.min(lo, fitAt(tot)); hi = Math.max(hi, fitAt(tot)); }
  if (x.limit !== null && x.limit !== undefined && x.eta_days !== null && x.eta_days !== undefined && x.eta_days <= ahead) { lo = Math.min(lo, x.limit); hi = Math.max(hi, x.limit); }
  if (x.bars) lo = Math.min(0, lo);
  if (hi === lo) { hi += 1; lo -= 1; }
  const pad = (hi - lo) * 0.08;
  hi += pad; if (!x.bars) lo -= pad;
  const W = 300, top = 4, bot = H - 4;
  const X = (i) => (i / tot) * W, Y = (v) => bot - ((v - lo) / (hi - lo)) * (bot - top);
  let body = '';
  if (x.bars) {
    const bw = W / (tot + 1);
    body = vals.map((v, i) => (v === null ? '' : `<rect class="tn-bar" x="${(X(i) - bw / 2 + 1).toFixed(1)}" y="${Y(v).toFixed(1)}" width="${Math.max(1, bw - 2).toFixed(1)}" height="${Math.max(1, bot - Y(v)).toFixed(1)}" rx="1.5"><title>${esc(L('week van {d}', { d: anDay(ks[i]) }))}: ${esc(tnFmt(v, x))}</title></rect>`)).join('');
  } else {
    let p = '';
    vals.forEach((v, i) => { if (v === null) return; p += `${p && vals[i - 1] !== null ? 'L' : 'M'}${X(i).toFixed(1)},${Y(v).toFixed(1)}`; });
    const hits = ks.map((k, i) => (vals[i] === null ? '' : `<rect x="${(X(i) - W / tot / 2).toFixed(1)}" y="0" width="${(W / tot).toFixed(1)}" height="${H}" fill="transparent"><title>${esc(anDay(k))}: ${esc(tnFmt(vals[i], x))}</title></rect>`)).join('');
    body = `<path class="tn-ln" d="${p}" vector-effect="non-scaling-stroke"/>${hits}`;
  }
  let fit = '';
  if (x.fit && x.sig) {
    fit = `<line class="tn-fit ${x.bad ? 'bad' : 'good'}" x1="0" y1="${Y(fitAt(0)).toFixed(1)}" x2="${X(n - 1).toFixed(1)}" y2="${Y(fitAt(n - 1)).toFixed(1)}" vector-effect="non-scaling-stroke"/>`;
    if (ahead) fit += `<rect class="tn-ahead" x="${X(n - 1).toFixed(1)}" y="0" width="${(W - X(n - 1)).toFixed(1)}" height="${H}"/><line class="tn-fit ${x.bad ? 'bad' : 'good'} dash" x1="${X(n - 1).toFixed(1)}" y1="${Y(fitAt(n - 1)).toFixed(1)}" x2="${W}" y2="${Y(fitAt(tot)).toFixed(1)}" vector-effect="non-scaling-stroke"/>`;
  }
  const lim = x.limit !== null && x.limit !== undefined && x.limit >= lo && x.limit <= hi
    ? `<line class="tn-lim" x1="0" x2="${W}" y1="${Y(x.limit).toFixed(1)}" y2="${Y(x.limit).toFixed(1)}" vector-effect="non-scaling-stroke"/>` : '';
  const limLbl = lim ? `<span class="tn-liml" style="top:${(Y(x.limit) / H * 100).toFixed(1)}%">${esc(x.limit_lbl || L('grens'))} ${esc(tnFmt(x.limit, x))}</span>` : '';
  return `<div class="tn-spark"><svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="${esc(x.title)}">${lim}${fit}${body}</svg>${limLbl}
    <div class="tn-xl"><span>${esc(anDay(ks[0]))}</span>${ahead ? `<span class="tn-xa">${esc(L('verwachting'))} →</span>` : `<span>${esc(L('vandaag'))}</span>`}</div></div>`;
}

function tnCard(x) {
  const cls = !x.sig ? 'flat' : x.bad ? 'bad' : 'good';
  const eta = x.eta && x.sig && x.bad
    ? `<span class="tn-eta ${x.eta_days <= 30 ? 'crit' : x.eta_days <= 90 ? 'warn' : ''}">⏳ ${esc(x.eta_lbl || L('grens'))}: ${esc(tnDate(x.eta))} <small>(${esc(L('over ~{n} dagen', { n: x.eta_days }))})</small></span>` : '';
  return `<article class="tn-card ${cls}${tnData.moving && tnData.moving.includes(x.id) ? ' top' : ''}">
    <header class="tn-h"><span class="tn-ic">${x.icon}</span><div class="tn-t"><b>${esc(x.title)}</b><span>${esc(x.sub || '')}</span></div>${tnChip(x)}</header>
    <div class="tn-now"><b>${esc(tnFmt(x.now, x))}</b> <span class="muted small">${x.was !== null && x.was !== undefined ? esc(L('was {v} op {d}', { v: tnFmt(x.was, x), d: anDay(Object.keys(x.series)[0]) })) : ''}</span></div>
    ${tnSpark(x)}
    <p class="tn-txt">${esc(x.text)}</p>
    <footer class="tn-f">${eta}${x.go ? `<button type="button" class="link-btn small" data-an-go="${esc(x.go)}">${L('bekijken')} →</button>` : ''}</footer>
  </article>`;
}

function tnRender() {
  const d = tnData;
  if (!d) return `<p class="muted">⏳ ${L('Trends laden…')}</p>`;
  if (d.error) return `<p class="form-error">${esc(d.error)}</p>`;
  const items = d.items || [];
  if (!items.length) return `<p class="muted">${esc(L('Nog geen trends: RzSense heeft minstens 14 dagen aan dagwaarden nodig. Die worden vanzelf elke dag bewaard.'))}</p>`;
  const mov = items.filter((x) => x.sig), bad = mov.filter((x) => x.bad), good = mov.filter((x) => !x.bad), flat = items.filter((x) => !x.sig);
  const top = (d.moving || []).map((id) => items.find((x) => x.id === id)).filter(Boolean);
  const head = `<div class="tn-top">
    <div class="tn-sum"><div class="tn-k bad"><b>${bad.length}</b><span>${esc(L('gaan de verkeerde kant op'))}</span></div>
      <div class="tn-k good"><b>${good.length}</b><span>${esc(L('verbeteren'))}</span></div>
      <div class="tn-k"><b>${flat.length}</b><span>${esc(L('stabiel'))}</span></div></div>
    <div class="tn-moves"><h3>${esc(L('Wat beweegt er'))}</h3>${top.length ? `<ol>${top.map((x) => `<li><span class="tn-ic">${x.icon}</span><span><b>${esc(x.title)}</b> <span class="muted small">${esc(x.sub || '')}</span><br><span class="small">${esc(x.short || x.text)}</span></span>${tnChip(x)}</li>`).join('')}</ol>`
      : `<p class="good-txt small">✔ ${esc(L('Niets dat langzaam de verkeerde kant op gaat. Alles stabiel.'))}</p>`}</div></div>`;
  const chips = [['moving', L('Wat beweegt ({n})', { n: mov.length })], ['all', L('Alles ({n})', { n: items.length })],
    ...Object.keys(TN_GRP).filter((g) => items.some((x) => x.grp === g)).map((g) => [g, `${TN_GRP[g][0]} ${TN_GRP[g][1]()}`])];
  const bar = `<div class="dash-chips tn-chips" role="group">${chips.map(([k, l]) => `<button type="button" class="dchip ${tnFilter === k ? 'on' : ''}" data-tr-f="${k}">${esc(l)}</button>`).join('')}</div>`;
  const groups = Object.keys(TN_GRP).map((g) => {
    if (!['moving', 'all', g].includes(tnFilter)) return '';
    const list = items.filter((x) => x.grp === g), show = tnFilter === 'moving' ? list.filter((x) => x.sig) : list, rest = list.filter((x) => !x.sig);
    if (!list.length) return '';
    show.sort((a, b) => (b.sig - a.sig) || (b.bad - a.bad) || ((a.eta_days ?? 1e9) - (b.eta_days ?? 1e9)) || (Math.abs(b.chg) - Math.abs(a.chg)));
    return `<section class="tn-grp"><h3>${TN_GRP[g][0]} ${esc(TN_GRP[g][1]())}</h3>
      ${show.length ? `<div class="tn-grid">${show.map(tnCard).join('')}</div>` : ''}
      ${tnFilter === 'moving' && rest.length ? `<p class="tn-flat"><span class="muted small">→ ${esc(L('stabiel'))}:</span> ${rest.slice(0, 12).map((x) => `<span class="tn-pill" title="${esc(x.text)}">${x.icon} ${esc(x.title)}${x.sub ? ` <span class="muted">${esc(x.sub)}</span>` : ''}</span>`).join('')}${rest.length > 12 ? ` <button type="button" class="link-btn small" data-tr-f="${g}">${esc(L('+{n} meer', { n: rest.length - 12 }))}</button>` : ''}</p>` : ''}
    </section>`;
  }).join('');
  return `${head}${bar}${groups}<p class="muted small tn-foot">${esc(L('Uit de dagwaarden van de laatste {n} dagen. Dag- en weekritme (zoals nachtelijke back-ups) tellen niet mee: RzSense gebruikt een robuuste lijn (Theil-Sen) en noemt iets pas een trend als de verandering groot genoeg én consequent is. Bijgewerkt: {t}.', { n: d.days, t: fmtDateTime(d.at) }))}</p>`;
}

// ---------------------------------------------------------------- Netwerk (1.103.0)
const NET_KIND = {
  router: ['🌐', () => L('Router')], network: ['🔀', () => L('Netwerkapparaat')], server: ['🖥️', () => L('Server')], nas: ['🗄️', () => 'NAS'],
  computer: ['💻', () => L('Computer')], phone: ['📱', () => L('Telefoon of tablet')], media: ['📺', () => L('Tv of media')], printer: ['🖨️', () => L('Printer')],
  camera: ['📷', () => L('Camera')], iot: ['💡', () => L('Slim apparaat (IoT)')], smarthome: ['🏠', () => L('Smart home')], unknown: ['❔', () => L('Onbekend')],
};
/** Soort in RzSense (hostForm) bij de soort uit de netwerkscan */
const NET_TO_HOST = { router: 'router', network: 'switch', server: 'server', nas: 'nas', printer: 'printer', camera: 'camera', smarthome: 'smarthome', iot: 'smarthome' };
let netData = null;
let netFilter = 'all';
let netSortTr = false;   // 1.186.0: Apparaten sorteren op verkeer
const netKind = (d) => d.kind_user || d.kind || 'unknown';

function initNet() {
  $('#net-tabs').onclick = (e) => { const b = e.target.closest('[data-nsub]'); if (b) setNetSub(b.dataset.nsub); };
  $('#net-group').value = (() => { try { return localStorage.getItem('rzmon-net-group') || ''; } catch (ex) { return ''; } })();
  $('#net-group').onchange = (e) => { try { localStorage.setItem('rzmon-net-group', e.target.value); } catch (ex) { /* niet erg */ } renderNet(); };
  $('#net-disc').onclick = ndClick;
  $('#net-map').onclick = nmClick;
  setNetSub(netSub);
  $('#net-search').oninput = () => renderNet();
  $('#net-filter').onclick = (e) => { const b = e.target.closest('[data-nf]'); if (b) { netFilter = b.dataset.nf; renderNet(); } };
  $('#net-counts').onclick = (e) => { const b = e.target.closest('[data-nf]'); if (b) { netFilter = netFilter === b.dataset.nf ? 'all' : b.dataset.nf; renderNet(); } };
  $('#net-scan').onclick = (e) => netScanNow(e.currentTarget);
  $('#net-banner').onclick = (e) => { if (e.target.closest('[data-net-scan]')) netScanNow(e.target.closest('[data-net-scan]')); };
  $('#net-approve-all').onclick = async () => {
    const n = (netData?.devices || []).filter((d) => d.status === 'new').length;
    if (!n || !confirm(L('Alle {n} nieuwe apparaten als bekend markeren?', { n }))) return;
    try { await api('net_approve_all', {}); toast(L('{n} apparaten bekend', { n })); loadNet(); refresh(); } catch (ex) { toast(ex.message, 'err'); }
  };
  $('#net-list').onclick = (e) => { if (e.target.closest('[data-net-sort]')) { netSortTr = !netSortTr; renderNet(); return; } netClick(e); };
}

async function loadNet() {
  try { netData = await api('net_devices'); renderNet(); } catch (ex) { $('#net-list').innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; }
  if (netSub === 'disc') ndLoad();
}

// ---------------------------------------------------------------- 1.183.0: Netwerk → Ontdekken
let netSub = (() => { try { return localStorage.getItem('rzmon-net-sub') || 'map'; } catch (ex) { return 'map'; } })();   // 1.184.0: standaard het overzicht
let nmKind = '';
let ndData = null;
let ndFilter = '';
let ndPresKind = '';
function setNetSub(s) {
  netSub = ['disc', 'map'].includes(s) ? s : 'list';
  try { localStorage.setItem('rzmon-net-sub', netSub); } catch (ex) { /* niet erg */ }
  $('#tab-net').classList.toggle('net-dc', netSub === 'disc');
  $('#tab-net').classList.toggle('net-mp', netSub === 'map');
  if (netSub === 'map') renderNetMap();
  $$('#net-tabs [data-nsub]').forEach((b) => { const on = b.dataset.nsub === netSub; b.classList.toggle('active', on); b.setAttribute('aria-selected', on ? 'true' : 'false'); });
  if (netSub === 'disc') withPageWait('net', ndLoad);
  crumbs();   // 1.199.0
}
async function ndLoad() {
  if (!ndData) $('#net-disc').innerHTML = `<p class="muted">${L('laden…')}</p>`;
  try {
    const [d] = await Promise.all([api('net_discover'), netData ? null : api('net_devices').then((x) => { netData = x; })]);
    ndData = d;
    renderNetDisc();
  } catch (ex) { $('#net-disc').innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; }
}
const ND_EV = () => ({
  new: ['🆕', L('Nieuw apparaat')], ip: ['🔁', L('Ander IP-adres')], ports_new: ['🚪', L('Nieuwe poort open')], ports_gone: ['🔒', L('Poort dicht')],
  domains: ['🌐', L('Praat met nieuwe domeinen')], gone: ['💤', L('Al dagen weg')], back: ['👋', L('Weer terug')],
  traffic: ['📈', L('Ongewoon veel verkeer')], traffic_night: ['🌙', L('Verkeer \'s nachts')],
});
function ndEvText(e, dev) {
  const x = e.detail || {};
  switch (e.kind) {
    case 'new': return L('verscheen op je netwerk als {ip}', { ip: x.ip || dev?.ip || '?' });
    case 'ip': return L('{from} → {to}', { from: x.from || '?', to: x.to || '?' });
    case 'ports_new': return L('poort {p} open', { p: (x.ports || []).join(', ') }) + ((x.risky || []).length ? ' · ⚠️ ' + L('riskant') : '');
    case 'ports_gone': return L('poort {p} niet meer open', { p: (x.ports || []).join(', ') });
    case 'domains': return (x.domains || []).join(', ') + (x.n > (x.domains || []).length ? ' ' + L('en nog {n}', { n: x.n - x.domains.length }) : '');
    case 'gone': return L('niet meer gezien sinds {t}', { t: x.last ? fmtDay(x.last) : '?' });
    case 'back': return L('weer gezien na {d} dagen', { d: x.days ?? '?' });
    case 'traffic': return L('{dir} {b} op {day} (normaal {n})', { dir: x.dir === 'up' ? '↑ ' + L('upload') : '↓ ' + L('download'), b: fmtBytes(x.bytes), day: fmtDay(x.day), n: fmtBytes(x.normal) });
    case 'traffic_night': return L('{b} tussen 0 en 6 uur op {day}, terwijl het \'s nachts normaal stil is', { b: fmtBytes(x.bytes), day: fmtDay(x.day) });
    default: return '';
  }
}
function renderNetDisc() {
  const d = ndData, nd = netData;
  if (!d || !nd) return;
  const box = $('#net-disc');
  if (!d.enabled) { box.innerHTML = `<div class="v-banner">ℹ️ <span>${L('De netwerkscan staat uit.')} ${isAdmin() ? L('Zet hem aan bij <a href="#settings/netscan" data-goto="settings/netscan">Instellingen → Beveiliging → Netwerkscan</a>.') : L('Een beheerder kan hem aanzetten.')}</span></div>`; return; }
  const byId = Object.fromEntries(nd.devices.map((x) => [x.id, x]));
  const ev = ND_EV();
  const week = Date.now() - 7 * 86400e3;
  const ts = (s) => new Date(String(s).replace(' ', 'T')).getTime();
  const ev7 = d.events.filter((e) => ts(e.at) > week);
  const newDevs = nd.devices.filter((x) => x.status === 'new').sort((a, b) => ts(b.first_seen) - ts(a.first_seen));
  const hourAgo = Date.now() - 3600e3;
  const onlineNow = nd.devices.filter((x) => x.status !== 'ignored' && ts(x.last_seen) > hourAgo - 15 * 60e3).length;
  const devLink = (id, label) => `<button type="button" class="nd-link" data-nd-open="${id}">${esc(label)}</button>`;
  const icon = (x) => (NET_KIND[netKind(x)] || NET_KIND.unknown)[0];
  // Kerncijfers
  const kpis = `<div class="kpis nd-kpis">
    <div class="kpi ${newDevs.length ? 'warn' : ''}"><div class="kpi-lbl">🆕 ${L('Nieuw en onbekend')}</div><div class="kpi-val">${newDevs.length}</div><div class="kpi-sub">${L('{n} deze week verschenen', { n: ev7.filter((e) => e.kind === 'new').length })}</div></div>
    <div class="kpi"><div class="kpi-lbl">🔄 ${L('Veranderingen')}</div><div class="kpi-val">${ev7.filter((e) => e.kind !== 'new').length}</div><div class="kpi-sub">${L('laatste 7 dagen')}</div></div>
    <div class="kpi"><div class="kpi-lbl">💡 ${L('Voorstellen')}</div><div class="kpi-val">${d.suggestions.length}</div><div class="kpi-sub">${L('nog niet in RzSense')}</div></div>
    <div class="kpi"><div class="kpi-lbl">🟢 ${L('Nu online')}</div><div class="kpi-val">${onlineNow}<small>/${nd.devices.filter((x) => x.status !== 'ignored').length}</small></div><div class="kpi-sub">${L('het laatste uur gezien')}</div></div>
  </div>`;
  // Nieuw en onbekend, met nieuwe apparaten per dag
  const days = [];
  for (let i = 29; i >= 0; i--) { const t = new Date(Date.now() - i * 86400e3); days.push(t.toISOString().slice(0, 10)); }
  const max = Math.max(1, ...days.map((k) => d.new_per_day[k] || 0));
  const spark = `<div class="nd-bars" role="img" aria-label="${esc(L('Nieuwe apparaten per dag, laatste 30 dagen'))}">${days.map((k) => { const n = d.new_per_day[k] || 0;
    return `<span class="nd-bar ${n ? '' : 'z'}" style="--h:${Math.round((n / max) * 100)}%" title="${esc(fmtDay(k) + ': ' + n)}"></span>`; }).join('')}</div>
    <div class="nd-bars-ax muted small"><span>${esc(fmtDay(days[0]))}</span><span>${L('vandaag')}</span></div>`;
  const newHtml = `<section class="card nd-sec"><h3>🆕 ${L('Nieuw en onbekend')} <span class="muted small">${L('apparaten die je nog niet beoordeelde')}</span></h3>
    ${spark}
    ${newDevs.length ? `<div class="nd-list">${newDevs.slice(0, 30).map((x) => `<div class="nd-row">
        <span class="nd-ic">${icon(x)}</span>
        <div class="nd-t">${devLink(x.id, x.label)} <span class="muted small mono">${esc(x.ip)}</span><small>${esc([x.vendor, x.info.unifi?.essid ? '📶 ' + x.info.unifi.essid : ''].filter(Boolean).join(' · ') || L('onbekende fabrikant'))} · ${L('verschenen {t}', { t: ago(x.first_seen) })}</small></div>
        <div class="nd-acts need-admin"><button type="button" class="btn small-btn" data-nd-st="known:${x.id}">✔ ${L('Bekend')}</button><button type="button" class="icon-btn" data-nd-st="ignored:${x.id}" title="${esc(L('Negeren: niet meer tonen'))}">🙈</button></div>
      </div>`).join('')}${newDevs.length > 30 ? `<p class="muted small">${L('en nog {n} op Apparaten', { n: newDevs.length - 30 })}</p>` : ''}</div>`
      : `<p class="good-txt small">✔ ${L('Alles op je netwerk is beoordeeld.')}</p>`}</section>`;
  // Veranderingen
  const kinds = Object.keys(ev);
  const evList = d.events.filter((e) => !ndFilter || e.kind === ndFilter);
  const chHtml = `<section class="card nd-sec"><h3>🔄 ${L('Veranderingen')} <span class="muted small">${L('laatste 30 dagen')}</span></h3>
    <div class="dash-chips nd-chips"><button type="button" class="dchip ${ndFilter ? '' : 'on'}" data-nd-f="">${L('Alles')} <b>${d.events.length}</b></button>
      ${kinds.map((k) => { const n = d.events.filter((e) => e.kind === k).length; return n ? `<button type="button" class="dchip ${ndFilter === k ? 'on' : ''}" data-nd-f="${k}">${ev[k][0]} ${esc(ev[k][1])} <b>${n}</b></button>` : ''; }).join('')}</div>
    ${evList.length ? `<div class="nd-list">${evList.slice(0, 80).map((e) => { const x = byId[e.device]; const [ic, w] = ev[e.kind] || ['•', e.kind];
      const bad = (e.kind === 'ports_new' && (e.detail.risky || []).length) || e.kind === 'domains' || e.kind === 'traffic' || e.kind === 'traffic_night';
      return `<div class="nd-row ${bad ? 'nd-bad' : ''}"><span class="nd-ic">${ic}</span>
        <div class="nd-t">${x ? devLink(x.id, x.label) : `<span class="muted">${L('(vergeten apparaat)')}</span>`} <span class="muted small">· ${esc(w)}</span><small>${esc(ndEvText(e, x))}</small></div>
        <span class="muted small nowrap" title="${esc(e.at)}">${esc(ago(e.at))}</span></div>`; }).join('')}</div>`
      : `<p class="muted small">${L('Nog niets veranderd. RzSense houdt dit bij vanaf 1.183.0: nieuwe apparaten, een ander IP-adres, nieuwe of gesloten poorten, apparaten die al {g} dagen weg zijn{dom}.', { g: d.gone_days, dom: d.adguard ? L(' en nieuwe domeinen (via AdGuard, na {n} dagen leren)', { n: d.learn_days }) : '' })}</p>`}</section>`;
  // Voorstellen
  const sugHtml = `<section class="card nd-sec"><h3>💡 ${L('Voorstellen')} <span class="muted small">${L('apparaten die je waarschijnlijk wilt bewaken')}</span></h3>
    ${d.suggestions.length ? `<div class="nd-sug">${d.suggestions.slice(0, 24).map((s, i) => `<div class="nd-sc" data-nd-sug="${s.id}">
        <div class="nd-sh"><span class="nd-ic">${(NET_KIND[s.kind] || NET_KIND.unknown)[0]}</span><div>${devLink(s.id, s.label)}<small class="muted mono">${esc(s.ip)} · ${esc((NET_KIND[s.kind] || NET_KIND.unknown)[1]())}</small></div></div>
        <div class="nd-checks">${s.checks.map((c, j) => `<label class="nd-ck"><input type="checkbox" value="${esc(c.key)}" ${j < 3 ? 'checked' : ''} ${isAdmin() ? '' : 'disabled'}> ${esc(c.label)}${c.target && c.type !== 'tcp' ? '' : c.type === 'tcp' ? ` <span class="muted mono">:${esc(c.target)}</span>` : ''}</label>`).join('')}</div>
        ${s.snmp ? `<p class="muted small">📡 ${L('Ondersteunt dit apparaat SNMP? Zet dat daarna aan bij de server voor poorten, temperatuur en meer.')}</p>` : ''}
        <div class="nd-acts need-admin"><button type="button" class="btn small-btn primary" data-nd-adopt="${s.id}">＋ ${L('In RzSense met deze checks')}</button>
          <button type="button" class="btn small-btn" data-nd-form="${s.id}">✎ ${L('Zelf instellen')}</button><button type="button" class="icon-btn" data-nd-st="ignored:${s.id}" title="${esc(L('Negeren: niet meer voorstellen'))}">🙈</button></div>
      </div>`).join('')}</div>` : `<p class="good-txt small">✔ ${L('Geen voorstellen: wat je wilt bewaken, staat al in RzSense.')}</p>`}</section>`;
  // Aanwezigheid
  const pdays = [];
  for (let i = 6; i >= 0; i--) pdays.push(new Date(Date.now() - i * 86400e3).toISOString().slice(0, 10));
  const pres = nd.devices.filter((x) => x.status !== 'ignored' && d.presence[x.id] && (!ndPresKind || netKind(x) === ndPresKind))
    .map((x) => { const p = d.presence[x.id]; let on = 0, night = 0;
      pdays.forEach((k) => { const h = p[k] || 0; for (let b = 0; b < 24; b++) if (h & (1 << b)) { on++; if (b < 6) night++; } });
      return { x, p, on, night }; }).sort((a, b) => b.on - a.on);
  const presKinds = [...new Set(nd.devices.filter((x) => d.presence[x.id]).map(netKind))];
  const trG = d.traffic || {};
  const hasTr = Object.keys(trG).length > 0;
  const trMax = {};
  Object.entries(trG).forEach(([id, h]) => { trMax[id] = Math.max(1, ...Object.values(h)); });
  const presHtml = `<section class="card nd-sec"><h3>🕒 ${hasTr ? L('Aanwezigheid en verkeer') : L('Aanwezigheid')} <span class="muted small">${hasTr ? L('wanneer een apparaat online was en hoe druk, laatste 7 dagen') : L('wanneer een apparaat online was, laatste 7 dagen')}</span></h3>
    <div class="nd-pbar"><select id="nd-pkind" aria-label="${esc(L('Soort'))}"><option value="">${L('Alle soorten')}</option>${presKinds.map((k) => `<option value="${k}" ${ndPresKind === k ? 'selected' : ''}>${(NET_KIND[k] || NET_KIND.unknown)[0]} ${esc((NET_KIND[k] || NET_KIND.unknown)[1]())}</option>`).join('')}</select>
      <span class="muted small">${L('Elk blokje is een uur; 🌙 = ook \'s nachts (0–6 uur) online.')}${hasTr ? ' ' + L('Hoe donkerder, hoe meer verkeer in dat uur.') : ''}</span></div>
    ${pres.length ? `<div class="nd-pres"><div class="nd-prow nd-phead"><span></span>${pdays.map((k) => `<span class="nd-pday">${esc(new Date(k + 'T12:00').toLocaleDateString(LOCALE, { weekday: 'short', day: 'numeric' }))}</span>`).join('')}<span></span></div>
      ${pres.slice(0, 60).map(({ x, p, on, night }) => `<div class="nd-prow"><span class="nd-pname">${icon(x)} ${devLink(x.id, x.label)}</span>
        ${pdays.map((k) => { const h = p[k] || 0; const tg = trG[x.id] || {};
          return `<span class="nd-pday">${Array.from({ length: 24 }, (_, b) => { const tb = tg[`${k} ${String(b).padStart(2, '0')}`] || 0;
            const lv = tb ? Math.min(4, 1 + Math.floor(Math.sqrt(tb / trMax[x.id]) * 3.999)) : 0;
            return `<i class="${h & (1 << b) || tb ? 'on' : ''} ${b < 6 ? 'n' : ''} ${lv ? 't' + lv : ''}" ${tb ? `title="${esc(k + ' ' + b + ':00 · ' + fmtBytes(tb))}"` : ''}></i>`; }).join('')}</span>`; }).join('')}
        <span class="nd-ppct small">${Math.round((on / 168) * 100)}%${night ? ' 🌙' : ''}</span></div>`).join('')}</div>`
      : `<p class="muted small">${L('Nog geen gegevens: vanaf 1.183.0 houdt elke scan bij welke apparaten er zijn. Na een paar uur zie je hier de eerste blokjes.')}</p>`}</section>`;
  box.innerHTML = kpis + `<div class="nd-grid">${newHtml}${chHtml}</div>` + sugHtml + presHtml;
  $('#nd-pkind')?.addEventListener('change', (e) => { ndPresKind = e.target.value; renderNetDisc(); });
  const badge = $('#net-disc-badge');
  if (badge) { const n = newDevs.length; badge.hidden = !n; badge.textContent = n; }
}
async function ndClick(e) {
  const f = e.target.closest('[data-nd-f]');
  if (f) { ndFilter = f.dataset.ndF; return renderNetDisc(); }
  const find = (id) => netData.devices.find((x) => +x.id === +id);
  const op = e.target.closest('[data-nd-open]');
  if (op) return netDialog(find(op.dataset.ndOpen));
  const fm = e.target.closest('[data-nd-form]');
  if (fm) return netAddHost(find(fm.dataset.ndForm));
  const st = e.target.closest('[data-nd-st]');
  if (st) {
    const [status, id] = st.dataset.ndSt.split(':');
    try { await api('net_device_save', { id: +id, status }); await loadNet(); refresh(); } catch (ex) { toast(ex.message, 'err'); }
    return;
  }
  const ad = e.target.closest('[data-nd-adopt]');
  if (ad) {
    const card = ad.closest('[data-nd-sug]');
    const checks = $$('input[type=checkbox]:checked', card).map((c) => c.value);
    const x = find(ad.dataset.ndAdopt);
    if (!checks.length) return toast(L('Kies minstens één check'), 'err');
    ad.disabled = true;
    try {
      await api('net_adopt', { id: +ad.dataset.ndAdopt, checks, name: x?.name || x?.label || '' });
      toast(L('{name} staat nu in RzSense met {n} checks', { name: x?.label || '', n: checks.length }));
      await loadNet(); refresh();
    } catch (ex) { toast(ex.message, 'err'); ad.disabled = false; }
  }
}

async function netScanNow(btn) {
  btn.disabled = true;
  const old = btn.textContent;
  btn.textContent = '⏳ ' + L('Scannen…');
  try { const r = await api('net_scan_now', { deep: true }); toast(r.message); await loadNet(); refresh(); } catch (ex) { toast(ex.message, 'err'); }
  btn.disabled = false;
  btn.textContent = old;
}

function renderNet() { withMorph(renderNetNow); if (netSub === 'map') renderNetMap(); }

// ---------------------------------------------------------------- 1.186.0: verkeer per apparaat
const fmtRate = (bps) => (bps >= 125000 ? dec(((bps * 8) / 1e6).toFixed(bps * 8 >= 1e8 ? 0 : 1)) + ' Mbit/s' : dec(((bps * 8) / 1e3).toFixed(0)) + ' kbit/s');
const netTr = (x) => netData?.traffic?.[x.id] || null;
/** Minigrafiek: 24 staafjes (bytes per uur) */
function trSpark(arr) {
  const max = Math.max(1, ...arr);
  return `<span class="tr-spark" aria-hidden="true">${arr.map((v) => `<i style="--h:${Math.max(v ? 8 : 0, Math.round((v / max) * 100))}%"></i>`).join('')}</span>`;
}
/** 1.188.0: welke bronnen het verkeer leveren */
const TR_SRC = () => ({ unifi: 'UniFi', snmp: L('SNMP (switchpoort)'), agent: L('agent (netwerkkaart)') });
function trSources(st) {
  const s = Object.keys(st.sources || {}).sort((a, b) => ['unifi', 'snmp', 'agent'].indexOf(a) - ['unifi', 'snmp', 'agent'].indexOf(b));
  return s.length ? L('bron: {s}', { s: s.map((k) => TR_SRC()[k] || k).join(', ') }) : L('volgens UniFi');
}
/** Top 10 van de laatste 24 uur (download en upload naast elkaar) */
function trTopHtml(limit = 10) {
  const d = netData;
  if (!d) return '';
  const st = d.traffic_state || {};
  const rows = d.devices.map((x) => ({ x, t: netTr(x) })).filter((r) => r.t && r.t.rx + r.t.tx > 0).sort((a, b) => (b.t.rx + b.t.tx) - (a.t.rx + a.t.tx)).slice(0, limit);
  const tt = d.traffic_totals || { today: [0, 0], yesterday: [0, 0] };
  const pct = (a, b) => (b > 0 ? Math.round(((a - b) / b) * 100) : null);
  const cmp = (a, b) => { const p = pct(a, b); return p === null ? '' : ` <small class="${p > 0 ? 'warn-txt' : 'good-txt'}">${p > 0 ? '+' : ''}${p}% ${L('t.o.v. gisteren')}</small>`; };
  if (!st.on) {
    return `<p class="muted small">${!st.unifi && st.setting ? L('Nog geen bron voor verkeer. Koppel UniFi (aanbevolen), zet SNMP aan op je switch, of werk de agent op je servers bij naar 1.80.0.') + ' ' + L('Koppel UniFi (Instellingen → Koppelingen → UniFi) om het verkeer per apparaat te zien.')
      : !st.account ? L('Verkeer per apparaat vraagt een lokaal UniFi-account; met alleen een API-sleutel geeft UniFi geen tellers.')
      : !st.setting ? L('Verkeer per apparaat staat uit (Instellingen → Beveiliging → Netwerkscan).') : L('De netwerkscan staat uit.')}</p>`;
  }
  if (st.error) return `<p class="warn-txt small">⚠️ ${esc(st.error)}</p>`;
  if (!rows.length) return `<p class="muted small">${L('Nog geen verkeer gemeten. Na 5 tot 10 minuten zie je hier de eerste cijfers.')}</p>`;
  const max = Math.max(1, ...rows.map((r) => Math.max(r.t.rx, r.t.tx)));
  return `<div class="tr-tot"><span>↓ <b>${fmtBytes(tt.today[0])}</b>${cmp(tt.today[0], tt.yesterday[0])}</span><span>↑ <b>${fmtBytes(tt.today[1])}</b>${cmp(tt.today[1], tt.yesterday[1])}</span><small class="muted">${L('vandaag, alle apparaten')}</small></div>
    <div class="tr-top">${rows.map(({ x, t }) => `<div class="tr-row"><button type="button" class="nd-link" data-nm-open="${x.id}">${(NET_KIND[netKind(x)] || NET_KIND.unknown)[0]} ${esc(x.label)}</button>
      <span class="tr-bars"><i class="dn" style="width:${(t.rx / max) * 100}%"></i><i class="up" style="width:${(t.tx / max) * 100}%"></i></span>
      <span class="tr-num small">↓ ${fmtBytes(t.rx)} · ↑ ${fmtBytes(t.tx)}</span></div>`).join('')}</div>
    <p class="muted small tr-legend"><i class="lg dn"></i> ${L('download')} <i class="lg up"></i> ${L('upload')} · ${L('laatste 24 uur')} · ${trSources(st)}</p>`;
}
/** 1.187.0: de internetlijn deze maand (UniFi-gateway, anders de som van de apparaten), met de datalimiet */
function wanHtml() {
  const w = netData?.wan;
  if (!w || !w.days || !w.days.length) return '';
  const used = w.rx + w.tx;
  const mx = Math.max(1, ...w.days.map((d) => d[1] + d[2]));
  const daysIn = new Date(+w.month.slice(0, 4), +w.month.slice(5, 7), 0).getDate();
  const byDay = Object.fromEntries(w.days.map((d) => [d[0], d]));
  const bars = Array.from({ length: daysIn }, (_, i) => { const k = `${w.month}-${String(i + 1).padStart(2, '0')}`; const d = byDay[k];
    return `<span title="${esc(fmtDay(k) + (d ? ': ↓ ' + fmtBytes(d[1]) + ' · ↑ ' + fmtBytes(d[2]) : ''))}">${d ? `<i class="up" style="height:${(d[2] / mx) * 100}%"></i><i class="dn" style="height:${(d[1] / mx) * 100}%"></i>` : ''}</span>`; }).join('');
  const pct = w.cap ? Math.min(100, Math.round((used / w.cap) * 100)) : null;
  return `<section class="card nm-wan"><h3>🌐 ${L('Internetlijn deze maand')}</h3>
    <div class="tr-tot"><span>↓ <b>${fmtBytes(w.rx)}</b></span><span>↑ <b>${fmtBytes(w.tx)}</b></span>
      ${w.forecast ? `<small class="muted">${L('verwacht aan het eind van de maand: {f}', { f: fmtBytes(w.forecast) })}</small>` : ''}</div>
    ${w.cap ? `<div class="wan-cap"><span class="wan-bar"><i class="${pct >= 100 ? 'bad' : pct >= 80 ? 'warn' : ''}" style="width:${pct}%"></i>${w.forecast ? `<b style="left:${Math.min(100, (w.forecast / w.cap) * 100)}%" title="${esc(L('verwacht'))}"></b>` : ''}</span>
      <small>${L('{u} van {c} ({p}%)', { u: fmtBytes(used), c: fmtBytes(w.cap), p: pct })}${w.forecast && w.forecast > w.cap ? ' · <span class="warn-txt">⚠️ ' + L('je komt er deze maand waarschijnlijk overheen') + '</span>' : ''}</small></div>` : ''}
    <div class="tr-days wan-days">${bars}</div>
    <p class="muted small tr-legend"><i class="lg dn"></i> ${L('download')} <i class="lg up"></i> ${L('upload')} · ${w.src === 'unifi' ? L('van je UniFi-gateway') : L('de som van alle apparaten (geen gegevens van de gateway)')}</p></section>`;
}

/** 1.187.0: diensten (UniFi DPI) in het venster van een apparaat */
async function netDpiBox(x, box) {
  let d;
  try { d = await api('net_dpi', null, { id: x.id }); } catch (ex) { box.innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  if (d.error) { box.innerHTML = `<p class="muted">${esc(d.error)}</p>`; return; }
  if (!d.cats.length) { box.innerHTML = `<p class="muted">${L('Geen gegevens. Staat DPI aan in UniFi (Settings → Traffic Identification)?')}</p>`; return; }
  const tot = d.cats.reduce((a, c) => a + c.rx + c.tx, 0) || 1;
  box.innerHTML = `<div class="dpi-list">${d.cats.slice(0, 10).map((c) => { const p = ((c.rx + c.tx) / tot) * 100;
    return `<div class="dpi-row"><span>${esc(c.name)}</span><span class="dpi-bar"><i style="width:${p}%"></i></span><span class="small muted nowrap">${dec(p.toFixed(p < 10 ? 1 : 0))}% · ↓ ${fmtBytes(c.rx)} ↑ ${fmtBytes(c.tx)}</span></div>`; }).join('')}</div>
    <p class="muted small">${L('Volgens UniFi (Traffic Identification), sinds het apparaat verbonden is.')}</p>`;
}

/** Verkeer in het venster van een apparaat */
async function netTrafficBox(x, box) {
  let d;
  try { d = await api('net_traffic_device', null, { id: x.id }); } catch (ex) { box.innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  if (!d.hours.length && !d.days.length) { box.innerHTML = `<p class="muted small">${L('Nog geen verkeer gemeten voor dit apparaat.')}</p>`; return; }
  // per uur, 7 dagen: twee lijnen (download, upload)
  const hrs = [];
  const start = new Date(); start.setHours(0, 0, 0, 0); start.setDate(start.getDate() - 6);
  const byH = Object.fromEntries(d.hours.map(([h, rx, tx]) => [h, [rx, tx]]));
  for (let i = 0; i < 7 * 24; i++) {
    const t = new Date(start.getTime() + i * 3600e3);
    const k = `${t.getFullYear()}-${String(t.getMonth() + 1).padStart(2, '0')}-${String(t.getDate()).padStart(2, '0')} ${String(t.getHours()).padStart(2, '0')}`;
    hrs.push([t, ...(byH[k] || [0, 0])]);
  }
  const W = 700, H = 150, P = 4;
  const mx = Math.max(1, ...hrs.map((h) => Math.max(h[1], h[2])));
  const xy = (i, v) => `${(P + (i / (hrs.length - 1)) * (W - 2 * P)).toFixed(1)},${(H - P - (v / mx) * (H - 2 * P - 14)).toFixed(1)}`;
  const line = (k) => hrs.map((h, i) => xy(i, h[k])).join(' ');
  const dayTicks = Array.from({ length: 7 }, (_, j) => { const xx = P + ((j * 24) / (hrs.length - 1)) * (W - 2 * P);
    return `<line x1="${xx}" y1="0" x2="${xx}" y2="${H}" class="tr-grid"/><text x="${xx + 4}" y="12" class="tr-ax">${esc(hrs[j * 24][0].toLocaleDateString(LOCALE, { weekday: 'short', day: 'numeric' }))}</text>`; }).join('');
  const days = d.days;
  const dmx = Math.max(1, ...days.map((r) => r[1] + r[2]));
  const sum = (k) => days.slice(-1).reduce((a, r) => a + r[k], 0);
  const n = d.normal;
  const ratio = (v, nv) => (nv > 0 ? v / nv : null);
  const rUp = n ? ratio(sum(2), n.tx) : null, rDn = n ? ratio(sum(1), n.rx) : null;
  box.innerHTML = `<div class="tr-dev">
    <div class="tr-dev-head"><span>↓ <b>${fmtBytes(sum(1))}</b> ↑ <b>${fmtBytes(sum(2))}</b> <small class="muted">${L('vandaag')}</small></span>
      ${d.rate ? `<span class="small">${L('nu')}: ↓ ${fmtRate(d.rate.rx)} · ↑ ${fmtRate(d.rate.tx)}</span>` : ''}
      ${n ? `<span class="small muted">${L('normaal per dag')}: ↓ ${fmtBytes(n.rx)} · ↑ ${fmtBytes(n.tx)}</span>` : `<span class="small muted">${L('nog aan het leren wat normaal is (7 dagen)')}</span>`}
      ${(rUp && rUp >= 5) || (rDn && rDn >= 5) ? `<span class="warn-txt small">⚠️ ${L('vandaag {x}× zoveel als normaal', { x: dec(Math.max(rUp || 0, rDn || 0).toFixed(1)) })}</span>` : ''}</div>
    <p class="small muted" style="margin:.4rem 0 .2rem">${L('Per uur, laatste 7 dagen')}</p>
    <svg viewBox="0 0 ${W} ${H}" class="tr-chart" role="img" aria-label="${esc(L('Verkeer per uur, laatste 7 dagen'))}">${dayTicks}
      <polyline points="${line(1)}" class="tr-l dn"/><polyline points="${line(2)}" class="tr-l up"/></svg>
    <p class="small muted" style="margin:.6rem 0 .2rem">${L('Per dag, laatste 30 dagen')}</p>
    <div class="tr-days">${days.map(([day, rx, tx]) => `<span title="${esc(fmtDay(day) + ': ↓ ' + fmtBytes(rx) + ' · ↑ ' + fmtBytes(tx))}"><i class="up" style="height:${(tx / dmx) * 100}%"></i><i class="dn" style="height:${(rx / dmx) * 100}%"></i></span>`).join('')}</div>
    <p class="muted small tr-legend"><i class="lg dn"></i> ${L('download')} <i class="lg up"></i> ${L('upload')} · ${d.src ? L('bron: {s}', { s: TR_SRC()[d.src] || d.src }) : L('volgens UniFi')}</p></div>`;
}

// ---------------------------------------------------------------- 1.184.0: Netwerk → Overzicht (netwerkkaart)
const ipNum = (ip) => String(ip).split('.').reduce((a, o) => a * 256 + (+o || 0), 0);
function ipInCidr(ip, cidr) {
  const [base, bits] = String(cidr).split('/');
  if (!/^\d+\.\d+\.\d+\.\d+$/.test(ip) || bits === undefined) return false;
  const size = 2 ** (32 - +bits);
  return Math.floor(ipNum(ip) / size) === Math.floor(ipNum(base) / size);
}
function renderNetMap() {
  const d = netData, box = $('#net-map');
  if (!box) return;
  if (!d) { box.innerHTML = `<p class="muted">${L('laden…')}</p>`; return; }
  if (!d.enabled) { box.innerHTML = `<div class="v-banner">ℹ️ <span>${L('De netwerkscan staat uit.')} ${isAdmin() ? L('Zet hem aan bij <a href="#settings/netscan" data-goto="settings/netscan">Instellingen → Beveiliging → Netwerkscan</a>.') : L('Een beheerder kan hem aanzetten.')}</span></div>`; return; }
  const day = Date.now() - 86400e3;
  const ts = (s) => new Date(String(s).replace(' ', 'T')).getTime();
  const devs = d.devices.filter((x) => x.status !== 'ignored');
  const online = (x) => ts(x.last_seen) > day;
  const icon = (x) => (NET_KIND[netKind(x)] || NET_KIND.unknown)[0];
  // Router: de standaardgateway, anders een apparaat van de soort router
  const router = devs.find((x) => x.info.gateway) || devs.find((x) => netKind(x) === 'router');
  // Infrastructuur uit UniFi: de namen van access points en switches waar clients aan hangen
  const infra = new Map();
  const norm = (s) => String(s || '').trim().toLowerCase();
  const infraDev = (name) => devs.find((x) => x !== router && [x.name, x.info.unifi?.name, x.label, x.hostname].some((v) => v && norm(v) === norm(name)));
  devs.forEach((x) => {
    const u = x.info.unifi || {};
    const via = u.essid && u.ap ? ['ap', u.ap] : u.sw ? ['sw', u.sw] : null;
    if (!via) return;
    const key = via[0] + ':' + via[1];
    if (!infra.has(key)) infra.set(key, { kind: via[0], name: via[1], dev: infraDev(via[1]), clients: [], ssids: new Set() });
    infra.get(key).clients.push(x);
    if (u.essid) infra.get(key).ssids.add(u.essid);
  });
  const infraDevs = new Set([...infra.values()].map((n) => n.dev).filter(Boolean));
  // Netwerkapparaten zonder clients (switch zonder UniFi-gegevens) ook als knoop
  devs.filter((x) => x !== router && netKind(x) === 'network' && !infraDevs.has(x)).forEach((x) => {
    infra.set('dev:' + x.id, { kind: 'net', name: x.label, dev: x, clients: [], ssids: new Set() });
    infraDevs.add(x);
  });
  const placed = new Set([router, ...infraDevs, ...[...infra.values()].flatMap((n) => n.clients)].filter(Boolean));
  const wired = devs.filter((x) => !placed.has(x) && x.info.unifi?.wired);
  const rest = devs.filter((x) => !placed.has(x) && !x.info.unifi?.wired);
  const hasUnifi = devs.some((x) => x.info.unifi);
  // Tellers per soort en per netwerk
  const kinds = {};
  devs.forEach((x) => { const k = netKind(x); kinds[k] = kinds[k] || { n: 0, on: 0 }; kinds[k].n++; if (online(x)) kinds[k].on++; });
  const nets = (d.networks?.scan || []).map((c) => { const xs = devs.filter((x) => ipInCidr(x.ip, c)); return { c, n: xs.length, on: xs.filter(online).length }; });
  const other = devs.filter((x) => !(d.networks?.scan || []).some((c) => ipInCidr(x.ip, c)));
  if (other.length) nets.push({ c: L('Andere netwerken'), n: other.length, on: other.filter(online).length });
  const kindChips = Object.entries(kinds).sort((a, b) => b[1].n - a[1].n).map(([k, v]) => `<button type="button" class="nm-kind ${nmKind === k ? 'on' : ''}" data-nm-kind="${k}">
      <span class="nm-ki">${(NET_KIND[k] || NET_KIND.unknown)[0]}</span><b>${v.n}</b><small>${esc((NET_KIND[k] || NET_KIND.unknown)[1]())}${v.on < v.n ? ` · ${L('{n} online', { n: v.on })}` : ''}</small></button>`).join('');
  const netRows = nets.map((n) => `<div class="nm-net"><span class="mono">${esc(n.c)}</span><span class="nm-netbar"><i style="width:${n.n ? Math.round((n.on / n.n) * 100) : 0}%"></i></span><span class="small">${L('{on} van {n} online', { on: n.on, n: n.n })}</span></div>`).join('');
  // Een apparaat als bolletje
  const dot = (x) => {
    const cls = [online(x) ? 'on' : 'off', x.status === 'new' ? 'new' : '', x.risky.length ? 'risky' : '', x.host ? 'rz' : '', nmKind && netKind(x) !== nmKind ? 'dim' : ''].join(' ');
    const tip = [x.label, x.ip, x.vendor, online(x) ? L('online') : L('offline'), x.status === 'new' ? L('nieuw') : '', x.risky.length ? L('riskante poort') : '', x.host ? L('in RzSense') : ''].filter(Boolean).join(' · ');
    const t = netTr(x);
    const tb = t ? t.rx + t.tx : 0;
    return `<button type="button" class="nm-dot ${cls} ${tb >= 1e9 ? 'heavy' : ''}" data-nm-open="${x.id}" title="${esc(tip + (t ? ` · ↓ ${fmtBytes(t.rx)} ↑ ${fmtBytes(t.tx)} (24 u)` : ''))}" aria-label="${esc(tip)}"><span>${icon(x)}</span><small>${esc(x.label)}</small>${tb ? `<em class="nm-tr">${fmtBytes(tb)}</em>` : ''}</button>`;
  };
  const node = (n) => {
    const x = n.dev;
    const ic = n.kind === 'ap' ? '📶' : '🔀';
    const on = n.clients.filter(online).length;
    return `<div class="nm-node ${nmKind && !n.clients.some((c) => netKind(c) === nmKind) && !(x && netKind(x) === nmKind) ? 'dim' : ''}">
      <div class="nm-nh">${x ? `<button type="button" class="nd-link" data-nm-open="${x.id}">${ic} ${esc(n.name)}</button>` : `<b>${ic} ${esc(n.name)}</b>`}
        <small class="muted">${n.kind === 'ap' ? L('access point') : n.kind === 'sw' ? L('switch') : L('netwerkapparaat')}${n.ssids.size ? ' · ' + [...n.ssids].map(esc).join(', ') : ''}${x ? ' · ' + esc(x.ip) : ''}</small>
        <span class="nm-cnt">${n.clients.length ? L('{on}/{n} online', { on, n: n.clients.length }) : ''}</span></div>
      <div class="nm-dots">${n.clients.sort((a, b) => netKind(a).localeCompare(netKind(b)) || a.label.localeCompare(b.label)).map(dot).join('') || `<span class="muted small">${L('geen clients bekend')}</span>`}</div></div>`;
  };
  const nodes = [...infra.values()].sort((a, b) => (a.kind === 'sw' ? 0 : 1) - (b.kind === 'sw' ? 0 : 1) || b.clients.length - a.clients.length);
  const bucket = (title, ic, xs, sub) => (xs.length ? `<div class="nm-node nm-bucket"><div class="nm-nh"><b>${ic} ${esc(title)}</b><small class="muted">${esc(sub)}</small><span class="nm-cnt">${L('{on}/{n} online', { on: xs.filter(online).length, n: xs.length })}</span></div>
    <div class="nm-dots">${xs.sort((a, b) => netKind(a).localeCompare(netKind(b)) || a.label.localeCompare(b.label)).map(dot).join('')}</div></div>` : '');
  box.innerHTML = `<div class="nm-top">
      <section class="card nm-kinds-card"><h3>${L('Wat zit er op je netwerk')}</h3><div class="nm-kinds">${kindChips}</div></section>
      <section class="card nm-nets-card"><h3>${L('Per netwerk')}</h3>${netRows || `<p class="muted small">${L('Nog geen netwerk ingesteld.')}</p>`}</section>
    </div>
    <div class="nm-tr2"><section class="card nm-traffic"><h3>📊 ${L('Verkeer vandaag')}</h3>${trTopHtml(10)}</section>${wanHtml()}</div>
    <section class="card nm-map">
      <div class="nm-legend small muted"><span><i class="lg on"></i> ${L('online')}</span><span><i class="lg off"></i> ${L('offline (24 uur niet gezien)')}</span><span><i class="lg new"></i> ${L('nieuw')}</span><span><i class="lg risky"></i> ${L('riskante poort')}</span><span><i class="lg rz"></i> ${L('in RzSense')}</span></div>
      <div class="nm-tree">
        <div class="nm-root"><div class="nm-inet">☁️ ${L('Internet')}</div><div class="nm-line"></div>
          <div class="nm-router">${router ? `<button type="button" class="nd-link" data-nm-open="${router.id}">🌐 ${esc(router.label)}</button><small class="muted mono">${esc(router.ip)}</small>` : `<b>🌐 ${L('Router')}</b><small class="muted">${L('nog niet herkend')}</small>`}</div>
          <div class="nm-line"></div></div>
        <div class="nm-level">${nodes.map(node).join('')}${bucket(L('Bedraad'), '🔌', wired, L('switch onbekend'))}${bucket(hasUnifi ? L('Verbinding onbekend') : L('Op je netwerk'), hasUnifi ? '❔' : '🏠', rest, hasUnifi ? L('niet in UniFi gezien') : L('koppel UniFi om te zien aan welk access point of welke switch elk apparaat hangt'))}</div>
      </div>
    </section>`;
}
function nmClick(e) {
  const k = e.target.closest('[data-nm-kind]');
  if (k) { nmKind = nmKind === k.dataset.nmKind ? '' : k.dataset.nmKind; return renderNetMap(); }
  const o = e.target.closest('[data-nm-open]');
  if (o) netDialog(netData.devices.find((x) => +x.id === +o.dataset.nmOpen));
}
function renderNetNow() {
  const d = netData;
  if (!d) return;
  try { ccNetChart(); } catch (e) { /* idem */ }
  const devs = d.devices;
  const day = Date.now() - 86400e3;
  const online = (x) => new Date(String(x.last_seen).replace(' ', 'T')).getTime() > day;
  const cnt = {
    all: devs.length, new: devs.filter((x) => x.status === 'new').length, norz: devs.filter((x) => !x.host && x.status !== 'ignored').length,
    rz: devs.filter((x) => x.host).length, risky: devs.filter((x) => x.risky.length && x.status !== 'ignored').length,
    known: devs.filter((x) => x.status === 'known').length, ignored: devs.filter((x) => x.status === 'ignored').length, online: devs.filter(online).length,
    blocked: devs.filter((x) => x.blocked).length,
  };
  $('#net-counts').innerHTML = [['new', '🆕', L('Nieuw'), 's1'], ['risky', '⚠️', L('Riskante poort'), 's2'], ['norz', '➕', L('Niet in RzSense'), 'si'], ['rz', '✔', L('In RzSense'), 's0']]
    .map(([k, ic, w, cls]) => `<button type="button" class="hc ${cls} ${cnt[k] ? '' : 'zero'} ${netFilter === k ? 'on' : ''}" data-nf="${k}"><span class="hc-dot"></span><b>${cnt[k]}</b> <span class="hc-w">${ic} ${w}</span></button>`).join('');
  const st = d.state || {};
  $('#net-last').textContent = st.sweep_at ? L('laatste scan {t}', { t: ago(new Date(st.sweep_at * 1000).toISOString()) }) + (st.deep_at ? ' · ' + L('diep {t}', { t: ago(new Date(st.deep_at * 1000).toISOString()) }) : '') : '';
  // Uitleg bovenaan: uit, geen netwerk, of nog nooit gescand
  const nets = d.networks || { scan: [], skip: [] };
  $('#net-banner').innerHTML = !d.enabled
    ? `<div class="v-banner">ℹ️ <span>${L('De netwerkscan staat uit.')} ${isAdmin() ? L('Zet hem aan bij <a href="#settings/netscan" data-goto="settings/netscan">Instellingen → Beveiliging → Netwerkscan</a>.') : L('Een beheerder kan hem aanzetten.')}</span></div>`
    : !nets.scan.length ? `<div class="v-banner">⚠️ <span>${L('Geen netwerk om te scannen: zet je netwerk (bv. 192.168.1.0/24) bij <a href="#settings/access" data-goto="settings/access">Toegang → Lokale netwerken</a>.')}</span></div>`
    : st.sweep_error ? `<div class="v-banner">⚠️ <span>${esc(st.sweep_error)}</span></div>`
    : st.links_error ? `<div class="v-banner">⚠️ <span>${esc(st.links_error)}</span> ${isAdmin() ? `<a href="#settings/netlinks" data-goto="settings/netlinks">${L('Instellingen')}</a>` : ''}</div>`
    : !st.sweep_at ? `<div class="v-banner">⏳ <span>${L('Nog niet gescand. De eerste scan volgt binnen een minuut, of start hem nu.')}</span> <button type="button" class="btn need-admin" data-net-scan>🔍 ${L('Nu scannen')}</button></div>` : '';
  $('#net-kpis').innerHTML = `
    <div class="kpi kpi-main"><div class="kpi-txt"><div class="kpi-lbl">${L('Apparaten')}</div><div class="kpi-val">${cnt.online}<small>/${cnt.all}</small></div>
      <div class="kpi-sub">${L('laatste 24 uur gezien')}</div></div></div>
    <div class="kpi ${cnt.new ? 'warn' : ''}"><div class="kpi-lbl">${L('Nieuw')}</div><div class="kpi-val">${cnt.new}</div><div class="kpi-sub">${cnt.new ? L('nog niet beoordeeld') : L('alles beoordeeld')}</div></div>
    <div class="kpi"><div class="kpi-lbl">${L('Niet in RzSense')}</div><div class="kpi-val">${cnt.norz}</div><div class="kpi-sub">${L('{n} wel', { n: cnt.rz })}</div></div>
    <div class="kpi ${cnt.risky ? 'bad' : ''}"><div class="kpi-lbl">${L('Riskante poort open')}</div><div class="kpi-val">${cnt.risky}</div><div class="kpi-sub">${cnt.risky ? L('Telnet, FTP, VNC …') : L('niets gevonden')}</div></div>
    <div class="kpi"><div class="kpi-lbl">${L('Netwerken')}</div><div class="kpi-val kpi-val-txt">${esc(nets.scan.join(', ') || '–')}</div>
      <div class="kpi-sub">${st.sweep_ms ? L('scan duurde {s} s', { s: dec((st.sweep_ms / 1000).toFixed(1)) }) : ''}</div></div>`;
  $('#net-filter').innerHTML = [['all', L('Alles')], ['new', '🆕 ' + L('Nieuw')], ['norz', L('Niet in RzSense')], ['known', L('Bekend')], ['risky', '⚠️ ' + L('Riskant')], ['blocked', '⛔ ' + L('Geweerd')], ['ignored', L('Genegeerd')]]
    .map(([k, l]) => `<button type="button" class="dchip ${netFilter === k ? 'on' : ''}" data-nf="${k}">${l} <b>${cnt[k]}</b></button>`).join('');
  const q = $('#net-search').value.trim().toLowerCase();
  const list = devs.filter((x) => (netFilter === 'all' ? x.status !== 'ignored' : netFilter === 'new' ? x.status === 'new' : netFilter === 'norz' ? !x.host && x.status !== 'ignored'
      : netFilter === 'rz' ? x.host : netFilter === 'known' ? x.status === 'known' : netFilter === 'risky' ? x.risky.length && x.status !== 'ignored' : netFilter === 'blocked' ? x.blocked : x.status === 'ignored')
    && (!q || [x.label, x.ip, x.mac, x.vendor, x.hostname, x.name, x.info.netbios, x.info.ssdp?.model].some((v) => String(v || '').toLowerCase().includes(q))));
  if (!devs.length) { $('#net-list').innerHTML = `<p class="muted">${d.enabled ? L('Nog geen apparaten gevonden.') : L('De netwerkscan staat uit.')}</p>`; return; }
  if (!list.length) { $('#net-list').innerHTML = `<p class="muted">${L('Niets gevonden met dit filter.')}</p>`; return; }
  // 1.183.0: groeperen per soort, fabrikant of verbinding
  const grp = $('#net-group')?.value || '';
  const gKey = (x) => (grp === 'kind' ? netKind(x) : grp === 'vendor' ? (x.vendor || (+x.random_mac ? '🎭' : '')) : grp === 'conn' ? (x.info.unifi?.essid ? 'w:' + x.info.unifi.essid : x.info.unifi?.wired ? 'cable' : '') : '');
  const gName = (k) => (grp === 'kind' ? (NET_KIND[k] || NET_KIND.unknown)[0] + ' ' + (NET_KIND[k] || NET_KIND.unknown)[1]()
    : grp === 'vendor' ? (k === '🎭' ? '🎭 ' + L('Privé-adres (geen fabrikant)') : k || L('Onbekende fabrikant'))
    : k.startsWith('w:') ? '📶 ' + k.slice(2) : k === 'cable' ? '🔌 ' + L('Bedraad') : L('Onbekend (geen UniFi-gegevens)'));
  const hasTr = !!(d.traffic_state?.on && Object.keys(d.traffic || {}).length);
  if (hasTr && netSortTr) list.sort((a, b) => ((netTr(b)?.rx || 0) + (netTr(b)?.tx || 0)) - ((netTr(a)?.rx || 0) + (netTr(a)?.tx || 0)));
  const groups = [];
  if (grp) {
    const m = new Map();
    list.forEach((x) => { const k = gKey(x); if (!m.has(k)) m.set(k, []); m.get(k).push(x); });
    [...m.entries()].sort((a, b) => b[1].length - a[1].length || String(a[0]).localeCompare(String(b[0]))).forEach(([k, xs]) => groups.push([gName(k), xs]));
  } else groups.push(['', list]);
  const row = (x) => {
      const [ic, kl] = NET_KIND[netKind(x)] || NET_KIND.unknown;
      const u = x.info.unifi || {};
      const sub = [kl(), x.name && x.hostname ? x.hostname : '', x.info.ssdp?.model || '', u.essid ? '📶 ' + u.essid + (u.ap ? ' · ' + u.ap : '') : u.wired ? '🔌 ' + L('bedraad') : ''].filter(Boolean).join(' · ');
      return `<tr class="${x.status === 'ignored' ? 'muted' : ''}" data-net="${x.id}"><td><button type="button" class="link-btn net-open" data-net-open="${x.id}"><span class="net-ic">${ic}</span> <b>${esc(x.label)}</b></button>
          ${x.status === 'new' ? ` <span class="badge-root">${L('nieuw')}</span>` : ''}${x.blocked ? ` <span class="badge-root bad-badge" title="${esc(netBlockedText(x))}">⛔ ${L('geweerd')}</span>` : ''}${x.host ? ` <span class="badge" title="${esc(L('In RzSense als {name}', { name: x.host.name }))}">✔ RzSense</span>` : ''}
          <br><span class="muted small">${esc(sub)}</span></td>
        <td class="small"><span class="mono">${esc(x.ip)}</span>${online(x) ? '' : ` <span class="muted">(${L('offline')})</span>`}</td>
        <td class="small">${x.mac ? `<span class="mono">${esc(x.mac.toUpperCase())}</span>` : '–'}${+x.random_mac ? ` <span class="badge" title="${esc(L('Willekeurig MAC-adres (privé-wifiadres): telefoons en laptops gebruiken dat per netwerk, en soms wisselt het'))}">🎭 ${L('privé')}</span>` : ''}<br><span class="muted">${esc(x.vendor || '')}</span></td>
        <td class="small">${x.ports.length ? x.ports.map((p) => `<span class="port-tag ${x.risky.includes(p) ? 'bad' : ''}" title="${esc(x.risky.includes(p) ? d.risky_reasons[p] : '')}">${p}</span>`).join(' ') : `<span class="muted">${x.deep_at ? L('geen') : '…'}</span>`}</td>
        ${hasTr ? `<td class="small nowrap">${netTr(x) ? `${trSpark(netTr(x).spark)}<br>↓ ${fmtBytes(netTr(x).rx)} · ↑ ${fmtBytes(netTr(x).tx)}` : '<span class="muted">–</span>'}</td>` : ''}
        <td class="small">${esc(ago(x.last_seen))}<br><span class="muted">${L('sinds {d}', { d: esc(fmtDay(x.first_seen)) })}</span></td>
        <td class="nowrap">${!x.host ? `<button type="button" class="btn small-btn need-admin" data-net-add="${x.id}" title="${esc(L('Toevoegen aan RzSense'))}">＋ RzSense</button>` : ''}
          ${x.status !== 'known' ? `<button type="button" class="icon-btn need-admin" data-net-st="known:${x.id}" title="${esc(L('Bekend: dit apparaat hoort hier'))}">✔</button>` : ''}
          ${x.status !== 'ignored' ? `<button type="button" class="icon-btn need-admin" data-net-st="ignored:${x.id}" title="${esc(L('Negeren: niet meer tonen'))}">🙈</button>` : `<button type="button" class="icon-btn need-admin" data-net-st="new:${x.id}" title="${esc(L('Weer tonen'))}">↩</button>`}</td></tr>`;
  };
  $('#net-list').innerHTML = `<div class="table-scroll"><table class="vuln-table net-table"><thead><tr><th>${L('Apparaat')}</th><th>${L('IP-adres')}</th><th>${L('MAC en fabrikant')}</th><th>${L('Poorten')}</th>${hasTr ? `<th><button type="button" class="link-btn" data-net-sort="tr">${L('Verkeer 24 u')} ${netSortTr ? '▼' : '⇅'}</button></th>` : ''}<th>${L('Gezien')}</th><th></th></tr></thead>
    ${groups.map(([name, xs]) => `<tbody>${name ? `<tr class="net-grp"><th colspan="${hasTr ? 7 : 6}">${esc(name)} <span class="muted">${xs.length}</span></th></tr>` : ''}${xs.map(row).join('')}</tbody>`).join('')}</table></div>`;
}

async function netClick(e) {
  const open = e.target.closest('[data-net-open]'), add = e.target.closest('[data-net-add]'), stb = e.target.closest('[data-net-st]');
  const find = (id) => netData.devices.find((x) => +x.id === +id);
  if (open) return netDialog(find(open.dataset.netOpen));
  if (add) return netAddHost(find(add.dataset.netAdd));
  if (stb) {
    const [status, id] = stb.dataset.netSt.split(':');
    try { await api('net_device_save', { id: +id, status }); await loadNet(); refresh(); } catch (ex) { toast(ex.message, 'err'); }
  }
}

/** Server toevoegen met naam, adres en soort uit de scan; ping-check aan */
function netAddHost(x) {
  if (!x) return;
  hostForm(null, { name: x.name || x.label, address: x.ip, kind: NET_TO_HOST[netKind(x)] || '' });
}

function netDialog(x) {
  if (!x) return;
  const [ic] = NET_KIND[netKind(x)] || NET_KIND.unknown;
  const i = x.info || {};
  const row = (k, v) => (v ? `<tr><th>${k}</th><td>${v}</td></tr>` : '');
  const admin = isAdmin();
  modal({
    title: `${ic} ${x.label}`,
    wide: true,
    body: `<table class="kv-table">
        ${row(L('IP-adres'), `<span class="mono">${esc(x.ip)}</span>${(i.ips || []).length ? ` <span class="muted small">(${L('eerder: {ips}', { ips: esc(i.ips.join(', ')) })})</span>` : ''}`)}
        ${row(L('MAC-adres'), x.mac ? `<span class="mono">${esc(x.mac.toUpperCase())}</span>${+x.random_mac ? ' · 🎭 ' + L('privé-adres (willekeurig)') : ''}` : L('onbekend (ander netwerk)'))}
        ${row(L('Fabrikant'), esc(x.vendor || ''))}
        ${row('UniFi', i.unifi ? esc([i.unifi.name, i.unifi.hostname, i.unifi.essid ? '📶 ' + i.unifi.essid : '', i.unifi.ap ? L('via {ap}', { ap: i.unifi.ap }) : '', i.unifi.wired ? '🔌 ' + L('bedraad') : '', i.unifi.blocked ? '⛔ ' + L('geblokkeerd in UniFi') : ''].filter(Boolean).join(' · ')) : '')}
        ${row('AdGuard', esc(i.adguard || ''))}
        ${row(L('DNS-naam'), esc(x.hostname || ''))}
        ${row('NetBIOS', esc(i.netbios || ''))}
        ${row('mDNS', i.mdns ? esc([i.mdns.name, i.mdns.host].filter(Boolean).join(' · ')) + (i.mdns.types?.length ? `<br><span class="muted small">${esc(i.mdns.types.join(', '))}</span>` : '') : '')}
        ${row('UPnP', i.ssdp ? esc([i.ssdp.name, i.ssdp.maker, i.ssdp.model, i.ssdp.type].filter(Boolean).join(' · ')) + (i.ssdp.server ? `<br><span class="muted small">${esc(i.ssdp.server)}</span>` : '') : '')}
        ${row(L('Webpagina'), i.http ? `${esc(i.http.title || '–')} <span class="muted small">(${L('poort {p}', { p: i.http.port })}${i.http.server ? ' · ' + esc(i.http.server) : ''})</span>` : '')}
        ${row(L('Open poorten'), x.ports.length ? x.ports.map((p) => `<span class="port-tag ${x.risky.includes(p) ? 'bad' : ''}">${p}</span>`).join(' ') : (x.deep_at ? L('geen gevonden') : L('nog niet gescand')))}
        ${row(L('In RzSense'), x.host ? `✔ ${esc(x.host.name)}` : L('nee'))}
        ${row(L('Gezien'), `${esc(fmtDateTime(x.first_seen))} – ${esc(ago(x.last_seen))}`)}
      </table>
      ${x.risky.length ? `<div class="callout bad-callout"><b>⚠️ ${L('Riskante poorten')}</b><ul>${x.risky.map((p) => `<li><b>${p}</b>: ${esc(netData.risky_reasons[p] || '')}</li>`).join('')}</ul>
        <p class="small" style="margin:0">${L('Heb je deze dienst niet nodig, zet hem dan uit in de instellingen van het apparaat. Anders: zorg voor een sterk wachtwoord en laat de poort nooit van internet bereikbaar zijn.')}</p></div>` : ''}
      ${x.blocked ? `<div class="callout bad-callout"><b>⛔ ${L('Geweerd')}</b>: ${esc(netBlockedText(x))}</div>` : ''}
      ${netData.traffic_state?.on ? `<details class="notify-own" id="net-tr" open><summary>📊 ${L('Verkeer')}</summary><div id="net-tr-body" class="small"><p class="muted">${L('laden…')}</p></div></details>` : ''}
      ${netData.traffic_state?.on ? `<details class="notify-own" id="net-dpi"><summary>🧩 ${L('Diensten (UniFi DPI)')}</summary><div id="net-dpi-body" class="small"></div></details>` : ''}
      ${netData.links.adguard ? `<details class="notify-own" id="net-dom"><summary>🌐 ${L('Met welke domeinen praat dit apparaat? (AdGuard)')}</summary><div id="net-dom-body" class="small"></div></details>` : ''}
      ${admin ? `<label>${L('Eigen naam')}<input name="name" value="${esc(x.name || '')}" maxlength="100" placeholder="${esc(x.label)}"></label>
      <label>${L('Soort apparaat')}<select name="kind_user"><option value="">${L('vanzelf: {k}', { k: (NET_KIND[x.kind] || NET_KIND.unknown)[1]() })}</option>
        ${Object.entries(NET_KIND).map(([k, [ki, kl]]) => `<option value="${k}" ${x.kind_user === k ? 'selected' : ''}>${ki} ${esc(kl())}</option>`).join('')}</select></label>
      <label>${L('Notitie')} <span class="hint">${L('(optioneel)')}</span><input name="notes" value="${esc(x.notes || '')}" maxlength="500"></label>
      <label>${L('Status')}<select name="status">${[['new', '🆕 ' + L('Nieuw (nog niet beoordeeld)')], ['known', '✔ ' + L('Bekend')], ['ignored', '🙈 ' + L('Negeren')]]
        .map(([k, l]) => `<option value="${k}" ${x.status === k ? 'selected' : ''}>${l}</option>`).join('')}</select></label>` : ''}`,
    buttons: admin ? [
      { label: '🗑 ' + L('Vergeten'), cls: 'danger', style: 'margin-right:auto', onClick: async () => {
        if (!confirm(L('Dit apparaat vergeten? Bij de volgende scan komt het terug als nieuw, als het er nog is.'))) return;
        try { await api('net_forget', { id: +x.id }); $('#modal').close(); loadNet(); refresh(); } catch (ex) { toast(ex.message, 'err'); }
      } },
      ...(!x.host ? [{ label: '＋ ' + L('Toevoegen aan RzSense'), onClick: () => { $('#modal').close(); netAddHost(x); } }] : []),
      x.blocked ? { label: '✅ ' + L('Weer toelaten'), onClick: () => netUnblock(x) } : { label: '⛔ ' + L('Weren'), cls: 'danger', onClick: () => netBlockDialog(x) },
      { label: L('Opslaan'), cls: 'primary', submit: true },
    ] : [{ label: L('Sluiten'), onClick: () => $('#modal').close() }],
    onSubmit: async (f) => { await api('net_device_save', { id: +x.id, name: f.name, kind_user: f.kind_user, notes: f.notes, status: f.status }); toast(L('Opgeslagen')); loadNet(); },
  });
  if ($('#net-tr-body')) netTrafficBox(x, $('#net-tr-body'));   // 1.186.0
  const dpi = $('#net-dpi');
  if (dpi) dpi.ontoggle = () => { if (dpi.open && !dpi.dataset.loaded) { dpi.dataset.loaded = '1'; netDpiBox(x, $('#net-dpi-body')); } };   // 1.187.0
  const dom = $('#net-dom');
  if (dom) dom.ontoggle = () => { if (dom.open && !dom.dataset.loaded) { dom.dataset.loaded = '1'; netDomains(x, $('#net-dom-body')); } };
}

function netBlockedText(x) {
  const b = x.blocked || {};
  const via = { unifi: L('UniFi (wifi)'), adguard: L('AdGuard (DNS)'), rzmon: L('RzSense en je servers') };
  return [L('via {via}', { via: (b.via || []).map((v) => via[v] || v).join(', ') }), b.until ? L('tot {t}', { t: fmtDateTime(b.until) }) : L('tot je het weer toelaat'),
    L('door {by}', { by: b.by || '?' }), b.reason || ''].filter(Boolean).join(' · ');
}

/** Domeinen uit de query-log van AdGuard Home (1.104.0) */
async function netDomains(x, box) {
  box.innerHTML = `<span class="muted">⏳ ${L('Query-log van AdGuard Home doorzoeken…')}</span>`;
  try {
    const d = await api('net_domains', null, { id: x.id });
    if (!d.total) { box.innerHTML = `<p class="muted">${L('Geen DNS-verzoeken van {ip} in de query-log.', { ip: esc(x.ip) })}</p>` + (d.errors || []).map((e) => `<p class="bad">${esc(e)}</p>`).join(''); return; }
    box.innerHTML = `<p class="muted" style="margin:.3rem 0">${L('{n} verzoeken naar {u} domeinen, waarvan {b} geblokkeerd', { n: d.total, u: d.unique, b: d.blocked })}${d.since ? ' · ' + L('sinds {t}', { t: esc(fmtDateTime(d.since.slice(0, 19).replace('T', ' '))) }) : ''}</p>
      <div class="table-scroll"><table class="vuln-table"><thead><tr><th>${L('Domein')}</th><th>${L('Aantal')}</th><th>${L('Laatst')}</th></tr></thead><tbody>
      ${d.domains.map((r) => `<tr><td class="mono">${r.blocked ? '⛔ ' : ''}${esc(r.domain)}</td><td>${r.n}</td><td>${esc(ago(r.last.slice(0, 19).replace('T', ' ')))}</td></tr>`).join('')}</tbody></table></div>`
      + (d.errors || []).map((e) => `<p class="bad">${esc(e)}</p>`).join('');
  } catch (ex) { box.innerHTML = `<p class="bad">${esc(ex.message)}</p>`; }
}

/** Weren (1.104.0): van het wifi (UniFi), geen DNS (AdGuard) en geen toegang tot RzSense en je servers */
function netBlockDialog(x) {
  const lk = netData.links || {};
  const canU = lk.unifi_block && x.mac, canA = lk.adguard;
  const opt = (k, on, can, lbl, why) => `<label class="switch"><input type="checkbox" name="${k}" ${on && can ? 'checked' : ''} ${can ? '' : 'disabled'}><span></span> <span>${lbl}${can ? '' : ` <span class="muted small">(${why})</span>`}</span></label>`;
  modal({
    title: '⛔ ' + L('{name} weren', { name: x.label }),
    body: `<p style="margin-top:0"><span class="mono">${esc(x.ip)}</span>${x.mac ? ` · <span class="mono">${esc(x.mac.toUpperCase())}</span>` : ''}${+x.random_mac ? ' · 🎭 ' + L('privé-adres: het apparaat kan een nieuw MAC-adres nemen') : ''}</p>
      ${opt('unifi', true, canU, '📶 ' + L('<b>UniFi</b>: niet meer op het wifi'), !lk.unifi_block ? L('UniFi niet ingesteld of alleen een API-sleutel') : L('geen MAC-adres bekend'))}
      ${opt('adguard', true, canA, '🌐 ' + L('<b>AdGuard</b>: geen DNS meer (geen internet via namen)'), L('AdGuard Home niet ingesteld'))}
      ${opt('rzmon', true, true, '🛡️ ' + L('<b>RzSense en je servers</b>: geen toegang tot RzSense, en geblokkeerd op je servers met agent'), '')}
      <div class="row2"><label>${L('Hoe lang')}<select name="days"><option value="1">${L('1 dag')}</option><option value="7">${L('7 dagen')}</option><option value="0">${L('Tot ik het weer toelaat')}</option></select></label>
        <label>${L('Reden')} <span class="hint">${L('(optioneel)')}</span><input name="reason" maxlength="200"></label></div>
      ${xpHtml(L('Weren werkt niet voor elk apparaat.'), L('<b>Bedraad:</b> een bedraad apparaat haal je niet van het netwerk via UniFi-wifi; daarvoor zet je de poort op de switch uit. <b>Eigen DNS of vast IP:</b> zo\'n apparaat komt langs AdGuard.'))}
      ${confirmField('WEREN')}`,
    buttons: [{ label: L('Annuleren'), onClick: () => $('#modal').close() }, { label: '⛔ ' + L('Weren'), cls: 'danger', submit: true }],
    onSubmit: async (d) => {
      const r = await api('net_block', { id: +x.id, unifi: !!d.unifi, adguard: !!d.adguard, rzmon: !!d.rzmon, days: +d.days, reason: d.reason, confirm: d.confirm });
      toast(L('Geweerd via {via}', { via: r.done.map((v) => ({ unifi: 'UniFi', adguard: 'AdGuard', rzmon: 'RzSense' }[v] || v)).join(', ') }) + (r.errors.length ? ' · ⚠️ ' + r.errors.join(' · ') : ''), r.errors.length ? 'err' : undefined);
      loadNet();
    },
  });
}

async function netUnblock(x) {
  if (!confirm(L('{name} weer toelaten? Alles wat bij het weren gedaan is, wordt teruggedraaid.', { name: x.label }))) return;
  try {
    const r = await api('net_unblock', { id: +x.id });
    toast(r.ok ? L('Weer toegelaten') : '⚠️ ' + (r.errors || []).join(' · '), r.ok ? undefined : 'err');
    $('#modal').close(); loadNet();
  } catch (ex) { toast(ex.message, 'err'); }
}

/** Instellingen → Netwerkscan: welke netwerken gescand worden */
async function loadNetscanSettings() {
  const box = $('#netscan-nets');
  if (!box) return;
  try {
    const d = await api('net_devices');
    const n = d.networks;
    box.innerHTML = `<p>${n.scan.length ? L('Wordt gescand: {list}', { list: n.scan.map((x) => `<code>${esc(x)}</code>`).join(', ') }) : `<b class="warn-txt">${L('Er is geen netwerk om te scannen.')}</b>`}
      ${n.skip.length ? `<br><span class="muted">${L('Overgeslagen: {list}', { list: n.skip.map((x) => `<code>${esc(x.net)}</code> (${esc(x.why)})`).join(', ') })}</span>` : ''}
      <br><span class="muted">${L('Aanpassen bij <a href="#settings/access" data-goto="settings/access">Toegang → Lokale netwerken</a>.')} ${d.vendors ? L('Fabrikantenlijst: {n} fabrikanten.', { n: d.vendors.toLocaleString(LOCALE) }) : ''}</span></p>`;
  } catch (ex) { box.textContent = ex.message; }
}

// ---------------------------------------------------------------- Kwetsbaarheden
const VULN_SEV = [['⚪', L('onbekend')], ['🔵', 'low'], ['🟡', 'medium'], ['🟠', 'high'], ['🔴', 'critical']];
let vulnData = null;
let vulnFilter = 'all';
let vulnSharedErr = new Set();   // scanfouten die als één melding bovenaan staan
// Open of dicht (1.93.0): standaard dicht; wat je open- of dichtklapt, onthoudt RzSense per account (h: servers, e: e-mailadressen).
// Met zoeken of een filter gaan de blokken met treffers tijdelijk open (vulnTmp); daarna weer jouw stand.
const vulnTmp = { h: new Map(), e: new Map() };
const vulnSaved = (kind, id) => ((PREFS.vuln_open || {})[kind] || []).map(String).includes(String(id));
function vulnOpenSave(kind, list) {   // list: [[id, open], …]
  const v = PREFS.vuln_open || {};
  const s = new Set((v[kind] || []).map(String));
  list.forEach(([id, open]) => (open ? s.add(String(id)) : s.delete(String(id))));
  savePref('vuln_open', { h: v.h || [], e: v.e || [], [kind]: kind === 'h' ? [...s].map(Number) : [...s] });
}

function initVulns() {
  $('#vuln-search').oninput = () => renderVulns();
  $('#vuln-sev').onchange = () => renderVulns();
  $('#vuln-filter').onclick = (e) => {
    const b = e.target.closest('[data-vf]');
    if (b) { vulnFilter = b.dataset.vf; renderVulns(); }
  };
  // Tellers: critical/high/medium = ernst vanaf, actief misbruikt = dat filter
  $('#vuln-counts').onclick = (e) => {
    const b = e.target.closest('[data-vsev], [data-vf]');
    if (!b) return;
    if (b.dataset.vf) vulnFilter = vulnFilter === 'kev' ? 'all' : 'kev';
    else { const v = b.dataset.vsev; $('#vuln-sev').value = $('#vuln-sev').value === v ? '0' : v; }
    renderVulns();
  };
  $('#vuln-banner').onclick = (e) => { if (e.target.closest('[data-vscan]')) vulnScan(e.target.closest('[data-vscan]')); };
  $('#vuln-scan').onclick = (e) => vulnScan(e.currentTarget);
  $('#vuln-toggle').onclick = () => {
    const cards = $$('#vuln-hosts details.vuln-host');
    const all = cards.length && cards.every((c) => c.open);
    cards.forEach((c) => { c.open = !all; vulnTmp.h.set(+c.dataset.host, !all); });
    vulnOpenSave('h', cards.map((c) => [+c.dataset.host, !all]));
  };
  $('#vuln-hosts').addEventListener('click', vulnClick);
}

async function loadVulns() {
  try {
    vulnData = await api('vulns');
    keepOpen($('#vuln-hosts'), renderVulns);
  } catch (ex) { $('#vuln-hosts').innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; }
}

// ---------------------------------------------------------------- Datalekken (Have I Been Pwned, 1.69.0)
let leakData = null;
let leakFilter = 'open';
let vulnTab = (() => { try { return localStorage.getItem('rzmon-vuln-tab') || 'cve'; } catch (e) { return 'cve'; } })();
const LEAK_SRC = { user: () => '👤 ' + L('gebruiker'), list: () => '📋 ' + L('eigen lijst'), domain: () => '🌐 ' + L('domein') };

function showVulnTab() {
  if (!$('#vuln-tabs')) return;
  const have = $$('#vuln-tabs .seg-btn').map((x) => x.dataset.vt);
  if (!have.includes(vulnTab)) vulnTab = have[0] || 'cve';
  if (vulnTab === 'eol') loadEol();   // 1.227.0
  if (vulnTab === 'patch') loadPatch();   // 1.230.0
  $$('#vuln-tabs .seg-btn').forEach((x) => x.classList.toggle('active', x.dataset.vt === vulnTab));
  $$('#tab-vulns .vuln-pane').forEach((x) => { x.hidden = x.dataset.vpane !== vulnTab; });
  crumbs();   // 1.199.0
}

/** De tabbladen Kwetsbaarheden / Verouderd / Datalekken (1.227.0: los, want Datalekken kan uit staan) */
function initVulnTabs() {
  if ($('#vuln-tabs') && !$('#vuln-tabs').dataset.init) {
    $('#vuln-tabs').dataset.init = '1';
    $('#vuln-tabs').onclick = (e) => {
      const b = e.target.closest('[data-vt]');
      if (!b) return;
      vulnTab = b.dataset.vt;
      try { localStorage.setItem('rzmon-vuln-tab', vulnTab); } catch (ex) { /* alleen voor nu */ }
      showVulnTab();
      fxSyncHash();
    };
    showVulnTab();
  }
}
function initLeaks() {
  initVulnTabs();
  $('#leak-search').oninput = () => renderLeaks();
  $('#leak-toggle').onclick = () => {
    const cards = $$('#leak-list details.leak-card');
    const all = cards.length && cards.every((c) => c.open);
    cards.forEach((c) => { c.open = !all; vulnTmp.e.set(c.dataset.email, !all); });
    vulnOpenSave('e', cards.map((c) => [c.dataset.email, !all]));
  };
  $('#leak-filter').onclick = (e) => { const b = e.target.closest('[data-lf]'); if (b) { leakFilter = b.dataset.lf; renderLeaks(); } };
  $('#leak-counts').onclick = (e) => { const b = e.target.closest('[data-lf]'); if (b) { leakFilter = leakFilter === b.dataset.lf ? 'all' : b.dataset.lf; renderLeaks(); } };
  $('#leak-run').onclick = async (e) => {
    const b = e.currentTarget;
    b.disabled = true;
    try {
      const r = await api('hibp_run', {});
      toast(r.left > 0 ? L('Controle gestart: nog {n} adres(sen) te gaan, de rest volgt binnen een paar minuten', { n: r.left }) : L('Controle klaar'));
      loadLeaks();
    } catch (ex) { toast(ex.message, 'err'); }
    b.disabled = false;
  };
  $('#leak-list').addEventListener('click', async (e) => {
    const det = e.target.closest('details.leak-card');
    if (e.target.closest('summary') && det && $(':scope > summary', det).contains(e.target)) {   // open/dicht onthouden (per account)
      setTimeout(() => { vulnTmp.e.set(det.dataset.email, det.open); vulnOpenSave('e', [[det.dataset.email, det.open]]); }, 0);
      return;
    }
    const b = e.target.closest('[data-lhandle]');
    if (!b) return;
    try { await api('hibp_handle', { email: b.dataset.email, name: b.dataset.lhandle, handled: b.dataset.done === '1' }); loadLeaks(); }
    catch (ex) { toast(ex.message, 'err'); }
  });
}

async function loadLeaks() {
  try {
    leakData = await api('hibp_overview');
    keepOpen($('#leak-list'), renderLeaks);
  } catch (ex) { $('#leak-list').innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; }
}

function leakVisible(e) {
  const q = $('#leak-search').value.trim().toLowerCase();
  if (!e.breaches.length && !fxPass('leaks', { email: e.email, source: e.source, none: 1 })) return null;
  const bs = e.breaches.filter((b) => fxPass('leaks', { ...b, email: e.email, source: e.source })
    && (leakFilter === 'handled' ? b.handled_at : leakFilter === 'all' || leakFilter === 'none' ? true : !b.handled_at)
    && (leakFilter !== 'pw' || b.passwords)
    && (!q || e.email.includes(q) || (b.title || b.name).toLowerCase().includes(q) || (b.domain || '').toLowerCase().includes(q)));
  if (leakFilter === 'none') return e.breaches.length ? null : bs;
  if ((leakFilter !== 'all' || fxActive('leaks')) && !bs.length && e.breaches.length) return null;
  if (leakFilter === 'all' && q && !bs.length && !e.email.includes(q)) return null;
  return bs;
}

function renderLeaks() {
  if (!leakData) return;
  const d = leakData;
  const all = d.emails.flatMap((e) => e.breaches.map((b) => ({ ...b, email: e.email })));
  const open = all.filter((b) => !b.handled_at);
  const pw = open.filter((b) => b.passwords);
  const hit = new Set(open.map((b) => b.email));
  const pwUsers = d.users.filter((u) => +u.hibp && +u.pw_pwned > 0);
  const handled = all.length - open.length;
  // Tellers
  $('#leak-counts').innerHTML = [
    ['open', open.length, L('Open lekken'), 's2'], ['pw', pw.length, L('Met wachtwoorden'), 's2'], ['', hit.size, L('Adressen getroffen'), 's1'],
    ['', pwUsers.length, L('Gelekte wachtwoorden'), 's2'], ['handled', handled, L('Afgehandeld'), 's0'],
  ].map(([k, n, w, c]) => `<button type="button" class="hc ${c} ${n ? '' : 'zero'} ${k && leakFilter === k ? 'on' : ''}" ${k ? `data-lf="${k}"` : ''}><span class="hc-dot"></span><b data-flash>${n}</b> <span class="hc-w">${w}</span></button>`).join('');
  $('#leak-info').textContent = d.check_at ? L('laatste controle {t}', { t: ago(d.check_at) }) + ' · ' + L('dagelijks') : '';
  if ($('#vt-n-leak')) $('#vt-n-leak').textContent = open.length || '';
  // Meldingen bovenaan: geen sleutel, fouten
  $('#leak-banner').innerHTML = [
    !d.has_key ? `<div class="v-banner info">ℹ️ <span>${L('Geen API-sleutel: alleen de wachtwoorden van RzSense-accounts worden gecontroleerd. Een sleutel vul je in bij Instellingen → Beveiliging → Datalekken.')}</span></div>` : '',
    d.last_error ? `<div class="v-banner">⚠️ <span><b>HIBP:</b> ${esc(d.last_error)}</span></div>` : '',
    d.domain_error ? `<div class="v-banner">⚠️ <span><b>${L('Domein')}:</b> ${esc(d.domain_error)}</span></div>` : '',
  ].join('');
  const newest = open.slice().sort((a, b) => String(b.added_date || '').localeCompare(String(a.added_date || '')))[0];
  const checked = d.emails.filter((e) => e.checked_at).length;
  $('#leak-kpis').innerHTML = `
    <div class="kpi kpi-main ${d.emails.some((e) => e.error) ? 'warn' : ''}"><div class="kpi-txt"><div class="kpi-lbl">${L('Adressen gecontroleerd')}</div>
      <div class="kpi-val">${checked}<small>/${d.emails.length}</small></div>
      <div class="kpi-sub">${d.domain ? L('incl. domein {d}', { d: esc(d.domain) }) : L('gebruikers en eigen lijst')}</div></div></div>
    <div class="kpi ${open.length ? 'bad' : ''}"><div class="kpi-lbl">${L('Open lekken')}</div><div class="kpi-val">${open.length}</div>
      <div class="kpi-sub">${L('op {n} adressen', { n: hit.size })}</div></div>
    <div class="kpi ${pw.length ? 'bad' : ''}"><div class="kpi-lbl">${L('Met wachtwoorden')}</div><div class="kpi-val">${pw.length}</div>
      <div class="kpi-sub">${pw.length ? L('wijzig die wachtwoorden') : L('geen')}</div></div>
    <div class="kpi ${pwUsers.length ? 'bad' : ''}"><div class="kpi-lbl">${L('Gelekte wachtwoorden in RzSense')}</div><div class="kpi-val">${pwUsers.length}</div>
      <div class="kpi-sub">${pwUsers.length ? esc(pwUsers.map((u) => u.username).join(', ')) : L('geen bekend')}</div></div>
    <div class="kpi"><div class="kpi-lbl">${L('Nieuwste lek')}</div><div class="kpi-val kpi-val-txt">${newest ? esc(newest.title || newest.name) : '–'}</div>
      <div class="kpi-sub">${newest && newest.breach_date ? esc(fmtDay(newest.breach_date)) : ''}</div></div>`;
  const cnt = { all: all.length, open: open.length, pw: pw.length, handled, none: d.emails.filter((e) => !e.breaches.length).length };
  $('#leak-filter').innerHTML = [['open', L('Open')], ['pw', '🔑 ' + L('Met wachtwoorden')], ['handled', L('Afgehandeld')], ['none', L('Zonder lekken')], ['all', L('Alles')]]
    .map(([k, l]) => `<button type="button" class="dchip ${leakFilter === k ? 'on' : ''}" data-lf="${k}">${l} <b>${cnt[k]}</b></button>`).join('');
  // Accounts met een gelekt wachtwoord
  $('#leak-users').innerHTML = pwUsers.length ? `<div class="v-banner">🔓 <span><b>${L('Wachtwoord in een datalek')}:</b> ${pwUsers.map((u) => esc(u.username)).join(', ')}.
    ${L('Bij de volgende keer inloggen moet eerst een nieuw wachtwoord worden gekozen.')}</span></div>` : '';
  fxRender('leaks');
  // Per adres
  const cards = d.emails.map((e) => [e, leakVisible(e)]).filter(([, bs]) => bs !== null)
    .sort(([a, x], [b, y]) => y.filter((z) => z.passwords && !z.handled_at).length - x.filter((z) => z.passwords && !z.handled_at).length || y.length - x.length || a.email.localeCompare(b.email));
  $('#leak-list').innerHTML = cards.length ? cards.map(([e, bs]) => leakCard(e, bs)).join('')
    : `<div class="card"><p class="muted" style="margin:0">${d.emails.length ? (leakFilter === 'open' ? '✔ ' + L('Geen open lekken.') : L('Niets gevonden.'))
      : L('Nog geen e-mailadressen: vul een API-sleutel in, en e-mailadressen bij de gebruikers of in de eigen lijst.')}</p></div>`;
}

function leakCard(e, bs) {
  const openN = e.breaches.filter((b) => !b.handled_at).length;
  const pwN = e.breaches.filter((b) => !b.handled_at && b.passwords).length;
  const narrowed = !!$('#leak-search').value.trim() || fxActive('leaks');
  if (!narrowed) vulnTmp.e.clear();
  const isOpen = narrowed ? vulnTmp.e.get(e.email) ?? bs.length > 0 : vulnSaved('e', e.email);
  return `<details class="card vuln-host leak-card ${pwN ? 'vh-w4' : openN ? 'vh-w2' : 'vh-w-1'}" data-email="${esc(e.email)}" ${isOpen ? 'open' : ''}>
    <summary><span class="host-ic" aria-hidden="true">✉️</span>
      <span class="vh-name"><b>${esc(e.email)}</b><span class="muted small">${(LEAK_SRC[e.source] || LEAK_SRC.list)()}${e.checked_at ? ' · ' + L('gecontroleerd {t}', { t: ago(e.checked_at) }) : ' · ' + L('nog niet gecontroleerd')}</span></span>
      <span class="vh-counts">${e.error ? `<span class="warn-txt small" title="${esc(e.error)}">⚠️ ${esc(e.error)}</span>` : ''}
        ${pwN ? `<span class="vpill sev4" title="${L('met wachtwoorden')}">🔑 ${pwN}</span>` : ''}${openN - pwN ? `<span class="vpill sev2" title="${L('open lekken')}">${openN - pwN}</span>` : ''}
        ${!e.breaches.length && e.checked_at ? `<span class="good-txt">✔ ${L('in geen enkel bekend lek')}</span>` : ''}${e.breaches.length && !openN ? `<span class="muted small">✔ ${L('alles afgehandeld')}</span>` : ''}</span></summary>
    ${bs.length ? `<div class="leak-rows">${bs.map((b) => `
      <div class="leak-row ${b.handled_at ? 'done' : ''} ${b.passwords ? 'pw' : ''}">
        <div class="leak-main"><div><b>${esc(b.title || b.name)}</b> <span class="muted small">${b.domain ? esc(b.domain) + ' · ' : ''}${b.breach_date ? esc(fmtDay(b.breach_date)) : '?'}${+b.pwn_count ? ' · ' + L('{n} accounts', { n: (+b.pwn_count).toLocaleString(LOCALE) }) : ''}${+b.verified ? '' : ' · ' + L('niet geverifieerd')}</span></div>
          <div class="leak-classes">${(b.data_classes_l || []).map((c, i) => `<span class="lc ${b.data_classes[i] === 'Passwords' ? 'pw' : ''}">${esc(c)}</span>`).join('')}</div>
          ${b.description ? `<details class="small leak-desc"><summary>${L('Wat is er gebeurd?')}</summary><p>${esc(b.description)}</p></details>` : ''}
          ${b.handled_at ? `<div class="muted small">✔ ${L('Afgehandeld {t} door {by}', { t: ago(b.handled_at), by: esc(b.handled_by || '?') })}</div>` : ''}</div>
        <button type="button" class="btn small-btn" data-lhandle="${esc(b.name)}" data-email="${esc(e.email)}" data-done="${b.handled_at ? '0' : '1'}">${b.handled_at ? '↺ ' + L('Heropenen') : '✔ ' + L('Afgehandeld')}</button>
      </div>`).join('')}</div>` : (e.breaches.length ? `<p class="muted small" style="margin:.4rem 0 0">${L('Geen lekken in deze selectie.')}</p>` : '')}
  </details>`;
}

async function vulnScan(btn) {
  btn.disabled = true;
  try {
    const r = await api('vuln_scan', {});
    toast(r.message || (r.pending ? L('Scan gestart: nog {n} server(s) te gaan, de rest volgt binnen een paar minuten', { n: r.pending }) : L('Scan klaar')));
    loadVulns();
  } catch (ex) { toast(ex.message, 'err'); }
  btn.disabled = false;
}

/** Bevindingen die nu zichtbaar zijn (zoeken, filter, ernst; minimum uit de instellingen) */
function vulnVisible() {
  const q = $('#vuln-search').value.trim().toLowerCase();
  const sev = Math.max(+$('#vuln-sev').value || 0, vulnData.min_severity || 0);
  const hostName = Object.fromEntries(vulnData.hosts.map((h) => [h.id, h.name.toLowerCase()]));
  const exposed = Object.fromEntries(vulnData.hosts.map((h) => [h.id, h.exposed || {}]));
  return vulnData.findings.filter((f) => {
    if (!fxPass('vulns', f)) return false;
    if (vulnFilter === 'ignored' ? !f.ignored : f.ignored && !fxHas('vulns', 'ign')) return false;
    if (f.severity < sev && !(sev && f.kev)) return false;
    if (vulnFilter === 'exposed' && !exposed[f.host_id][f.package]) return false;
    if (vulnFilter === 'fix' && !f.fixed) return false;
    if (vulnFilter === 'kev' && !f.kev) return false;
    if (vulnFilter === 'risk' && f.risk < 70) return false;
    if (vulnFilter === 'buzz') { const b = vulnBuzz(f.cve); if (!b || b.score === null || b.score < (vulnData.buzz_min || 60)) return false; }   // 1.179.0
    return !q || f.package.toLowerCase().includes(q) || f.cve.toLowerCase().includes(q) || f.vuln_id.toLowerCase().includes(q)
      || (f.binaries || '').toLowerCase().includes(q) || hostName[f.host_id].includes(q) || (f.summary || '').toLowerCase().includes(q);
  });
}

/** 1.179.0: rugbaarheid van een CVE (of null), en het oordeel van de AI */
const vulnBuzz = (cve) => (vulnData && vulnData.buzz ? vulnData.buzz[cve] || null : null);
const VULN_AI = { now: ['bad', () => L('eerst doen')], later: ['warn', () => L('kan wachten')], na: ['ok', () => L('niet van toepassing')] };
function vulnChip(f) {
  const [icon] = VULN_SEV[f.severity] || VULN_SEV[0];
  const b = vulnBuzz(f.cve);
  const hot = b && b.score !== null && b.score >= (vulnData.buzz_min || 60);
  const ai = b && VULN_AI[b.ai];
  return `<button type="button" class="cve-chip sev${f.severity}${f.kev ? ' kev' : ''}${hot ? ' hot' : ''}" data-cve="${esc(f.cve)}"
    title="${esc((f.summary || f.vuln_id) + ` · ${L('risico')} ${f.risk}` + (f.cvss ? ` · CVSS ${f.cvss}` : '') + (f.kev ? ' · ' + L('actief misbruikt') : '')
      + (b && b.score !== null ? ' · ' + L('rugbaarheid {s}', { s: b.score }) : '') + (ai ? ' · AI: ' + ai[1]() : ''))}">${icon} ${esc(f.cve)}${f.kev ? ' ⚠️' : ''}${hot ? ` <span class="cve-hot">🔥${b.score}</span>` : ''}${ai ? ` <span class="cve-ai ${ai[0]}" aria-hidden="true">🤖</span>` : ''}</button>`;
}

/** 1.141.0: risicoscore 0–100 als pil (hoog ≥ 70, midden ≥ 40) */
function riskPill(r) {
  const lvl = r >= 70 ? 'high' : r >= 40 ? 'mid' : 'low';
  return `<span class="risk-pill risk-${lvl}" title="${esc(L('Risico {r} van 100: ernst (CVSS), actief misbruikt, kans op misbruik (EPSS) en of het pakket op het netwerk luistert', { r }))}">${r}</span>`;
}

function renderVulns() {
  if (!vulnData) return;
  try { ccVulnCharts(); } catch (e) { /* idem */ }
  const d = vulnData;
  const list = vulnVisible();
  // Tellers per ernst (unieke CVE's per server), zonder geaccepteerde
  const live = d.findings.filter((f) => !f.ignored);
  const uniq = (fs) => new Set(fs.map((f) => f.host_id + '|' + f.cve));
  const n = [0, 1, 2, 3, 4].map((s) => uniq(live.filter((f) => f.severity === s)).size);
  const kev = uniq(live.filter((f) => f.kev)).size;
  const sevSel = $('#vuln-sev').value;
  const WORD = { 4: 'Critical', 3: 'High', 2: 'Medium', 1: 'Low', 0: L('Onbekend') };
  $('#vuln-counts').innerHTML = [4, 3, 2, 1, 0].filter((sv) => n[sv] || sv >= 1)
    .map((sv) => `<button type="button" class="hc vsev${sv} ${n[sv] ? '' : 'zero'} ${sv >= 2 && sevSel === String(sv) ? 'on' : ''}" ${sv >= 2 ? `data-vsev="${sv}" title="${esc(L('Klik: vanaf deze ernst'))}"` : ''}><span class="hc-dot"></span><b>${n[sv]}</b> <span class="hc-w">${WORD[sv]}</span></button>`).join('')
    + `<button type="button" class="hc vkev ${kev ? '' : 'zero'} ${vulnFilter === 'kev' ? 'on' : ''}" data-vf="kev" title="${esc(L('Actief misbruikt (CISA KEV)'))}"><span class="hc-dot"></span><b>${kev}</b> <span class="hc-w">⚠️ ${L('Actief misbruikt')}</span></button>`;
  const scanned = d.hosts.filter((h) => h.scanned_at && !h.error);
  const failedH = d.hosts.filter((h) => h.error);
  $('#vuln-info').textContent = d.hosts.length ? (d.last_scan ? L('laatste scan {t}', { t: ago(d.last_scan) }) + ' · ' : '') + L('dagelijks om {t}', { t: d.scan_time }) : '';
  // Dezelfde scanfout op meerdere servers: één melding bovenaan
  const errs = {};
  failedH.forEach((h) => (errs[h.error] ||= []).push(h.name));
  const shared = Object.entries(errs).filter(([, hs]) => hs.length > 1);
  vulnSharedErr = new Set(shared.map(([e]) => e));
  $('#vuln-banner').innerHTML = shared.map(([e, hs]) => `<div class="v-banner">⚠️ <span><b>${L('Scan mislukt op {n} servers', { n: hs.length })}</b> (${esc(hs.join(', '))}): ${esc(e)}</span>
    <button type="button" class="btn need-admin" data-vscan>🔍 ${L('Opnieuw scannen')}</button></div>`).join('');
  // Kerncijfers
  const pk = new Set(live.map((f) => f.host_id + '|' + f.package));
  const fixPk = new Set(live.filter((f) => f.fixed).map((f) => f.host_id + '|' + f.package));
  const kevF = live.find((f) => f.kev);
  const noList = d.hosts.filter((h) => !h.packages).length;
  const [hh, mm] = String(d.scan_time || '03:30').split(':').map(Number);
  const next = new Date(); next.setHours(hh, mm, 0, 0); if (next <= new Date()) next.setDate(next.getDate() + 1);
  const left = Math.round((next - new Date()) / 60000);
  $('#vuln-kpis').innerHTML = `
    <div class="kpi kpi-main ${failedH.length ? 'warn' : ''}"><div class="kpi-txt"><div class="kpi-lbl">${L('Servers gescand')}</div>
      <div class="kpi-val">${scanned.length}<small>/${d.hosts.length}</small></div>
      <div class="kpi-sub">${[failedH.length ? L('{n} met een fout', { n: failedH.length }) : '', noList ? L('{n} zonder softwarelijst', { n: noList }) : ''].filter(Boolean).join(' · ') || L('allemaal gelukt')}</div></div></div>
    <div class="kpi ${pk.size ? 'bad' : ''}"><div class="kpi-lbl">${L('Kwetsbare pakketten')}</div><div class="kpi-val">${pk.size}</div>
      <div class="kpi-sub">${L('{n} kwetsbaarheden', { n: uniq(live).size })}</div></div>
    <div class="kpi"><div class="kpi-lbl">${L('Met oplossing')}</div><div class="kpi-val ${fixPk.size ? 'good-txt' : ''}">${fixPk.size}</div>
      <div class="kpi-sub">${fixPk.size ? L('bij te werken met ⬆') : L('niets bij te werken')}</div></div>
    <div class="kpi ${kev ? 'bad' : ''}"><div class="kpi-lbl">${L('Actief misbruikt')}</div><div class="kpi-val">${kev}</div>
      <div class="kpi-sub">${kevF ? esc(kevF.cve + ' · ' + kevF.package) : L('geen (CISA KEV)')}</div></div>
    <div class="kpi"><div class="kpi-lbl">${L('Opgelost (30 dagen)')}</div><div class="kpi-val ${d.resolved ? 'good-txt' : ''}">${d.resolved || 0}</div>
      <div class="kpi-sub">${L('volgende scan om {t} (over {l})', { t: esc(d.scan_time), l: left >= 60 ? `${Math.floor(left / 60)} ${L('u')} ${left % 60} min` : `${left} min` })}</div></div>`;
  // Chips met aantallen
  const cntF = (k) => new Set(d.findings.filter((f) => (k === 'ignored' ? f.ignored : !f.ignored)
    && (k !== 'exposed' || (d.hosts.find((h) => +h.id === +f.host_id)?.exposed || {})[f.package]) && (k !== 'fix' || f.fixed) && (k !== 'kev' || f.kev) && (k !== 'risk' || f.risk >= 70) && (k !== 'buzz' || ((vulnBuzz(f.cve) || {}).score ?? -1) >= (d.buzz_min || 60))).map((f) => f.host_id + '|' + f.cve)).size;
  $('#vuln-filter').innerHTML = [['all', L('Alles')], ['risk', '⚡ ' + L('Hoog risico')], ...(d.buzz ? [['buzz', '🔥 ' + L('Veel aandacht')]] : []), ['exposed', '🌐 ' + L('Bereikbaar')], ['fix', L('Met oplossing')], ['kev', '⚠️ ' + L('Actief misbruikt')], ['ignored', L('Geaccepteerd')]]
    .map(([k, l]) => `<button type="button" class="dchip ${vulnFilter === k ? 'on' : ''}" data-vf="${k}">${l} <b>${cntF(k)}</b></button>`).join('');
  $('#vuln-oneup').innerHTML = vulnOneUp(live);
  $('#vuln-badge').hidden = !(n[4] + kev);
  $('#vuln-badge').textContent = n[4] + kev || '';
  if (!d.hosts.length) {
    $('#vuln-hosts').innerHTML = `<div class="card"><p class="muted">${L('Nog geen softwarelijsten. Werk de agents bij naar {v} of nieuwer: dan sturen ze hun pakketten mee.', { v: '1.47.0' })}</p></div>`;
    return;
  }
  const byHost = {};
  list.forEach((f) => (byHost[f.host_id] ||= []).push(f));
  fxRender('vulns');
  // Met een filter alleen de servers met treffers
  const hostsShown = fxActive('vulns') ? d.hosts.filter((h) => (byHost[h.id] || []).length) : d.hosts;
  $('#vuln-hosts').innerHTML = hostsShown.length ? hostsShown.map((h) => vulnHostCard(h, byHost[h.id] || [])).join('')
    : `<div class="card"><p class="muted" style="margin:0">${L('Niets gevonden.')}</p></div>`;
}

/**
 * 1.179.0: "Eén update, veel opgelost": per pakket hoeveel kwetsbaarheden een update oplost, op hoeveel servers,
 * gesorteerd op het risico dat verdwijnt (som van het risico per server en CVE). Alleen wat een oplossing heeft.
 */
function vulnOneUp(live) {
  const by = {};
  live.filter((f) => f.fixed).forEach((f) => {
    const p = (by[f.package] ||= { name: f.package, hosts: {}, cves: new Set(), kev: new Set(), hot: new Set(), sum: 0, seen: new Set(), max: 0 });
    const k = f.host_id + '|' + f.cve;
    if (!p.seen.has(k)) { p.seen.add(k); p.sum += f.risk || 0; }
    p.cves.add(f.cve);
    if (f.kev) p.kev.add(f.cve);
    const b = vulnBuzz(f.cve);
    if (b && b.score !== null && b.score >= (vulnData.buzz_min || 60)) p.hot.add(f.cve);
    p.max = Math.max(p.max, f.risk || 0);
    const hh = (p.hosts[f.host_id] ||= { id: f.host_id, fixed: f.fixed, n: 0 });
    hh.n++;
    if (String(f.fixed) > String(hh.fixed)) hh.fixed = f.fixed;
  });
  const list = Object.values(by).filter((p) => p.cves.size >= 2 || p.kev.size || p.max >= 70).sort((a, b) => b.sum - a.sum).slice(0, 6);
  if (!list.length) return '';
  const name = (id) => (vulnData.hosts.find((h) => h.id === +id) || {}).name || '#' + id;
  return `<div class="card vou"><div class="vou-h"><h3>🎯 ${L('Eén update, veel opgelost')}</h3><span class="muted small">${L('de updates die het meeste risico wegnemen')}</span></div>
    <div class="vou-list">${list.map((p, i) => {
      const hs = Object.values(p.hosts);
      const fixed = [...new Set(hs.map((x) => x.fixed))];
      return `<div class="vou-row"><span class="vou-rank" aria-hidden="true">${i + 1}</span>
        <span class="vou-main"><b>${esc(p.name)}</b> <span class="muted small mono">→ ${esc(fixed.length === 1 ? fixed[0] : L('{n} versies', { n: fixed.length }))}</span>
          <small>${p.cves.size === 1 ? L('1 kwetsbaarheid opgelost') : L('{n} kwetsbaarheden opgelost', { n: p.cves.size })} · ${hs.length === 1 ? esc(name(hs[0].id)) : L('op {n} servers', { n: hs.length })}${p.kev.size ? ` · <b class="bad">⚠️ ${L('{n} actief misbruikt', { n: p.kev.size })}</b>` : ''}${p.hot.size ? ` · 🔥 ${L('{n} met veel aandacht', { n: p.hot.size })}` : ''}</small></span>
        <span class="vou-bar" title="${esc(L('Risico dat verdwijnt: {n}', { n: p.sum }))}"><i style="width:${Math.min(100, Math.round(p.sum / list[0].sum * 100))}%"></i></span>
        <button type="button" class="btn small-btn need-admin" data-vou="${esc(p.name)}">⬆ ${L('Bijwerken')}</button></div>`;
    }).join('')}</div></div>`;
}
/** Bijwerken vanuit "Eén update": één server meteen, meer servers eerst kiezen */
function vulnOneUpDo(pkg) {
  const hosts = [...new Set(vulnData.findings.filter((f) => f.package === pkg && f.fixed && !f.ignored).map((f) => f.host_id))]
    .map((id) => vulnData.hosts.find((h) => h.id === id)).filter(Boolean);
  if (hosts.length === 1) return vulnUpgrade(hosts[0], [pkg]);
  modal({
    title: L('{p} bijwerken', { p: pkg }),
    body: `<div style="padding:1rem 1.2rem"><p class="muted small">${L('Kies de server; bijwerken gaat per server via de agent (of met het commando).')}</p>
      ${hosts.map((h) => `<div class="am-row"><div class="am-rt"><b>${esc(h.name)}</b><small>${esc(h.os || '')}</small></div><div class="am-rr"><button type="button" class="btn small-btn" data-vou-h="${h.id}">⬆ ${L('Bijwerken')}</button></div></div>`).join('')}</div>`,
    buttons: [{ label: L('Sluiten'), cls: 'primary', submit: true }],
  });
  $$('[data-vou-h]', $('#modal')).forEach((b) => (b.onclick = () => vulnUpgrade(hosts.find((h) => h.id === +b.dataset.vouH), [pkg])));
}

function vulnHostCard(h, fs) {
  const sharedErr = h.error && vulnSharedErr.has(h.error);   // staat al bovenaan als één melding
  // Per pakket: alle CVE's, ernstigste eerst; pakketten met de ergste en bereikbare bovenaan
  const pk = {};
  fs.forEach((f) => (pk[f.package] ||= { name: f.package, version: f.version, fixed: f.fixed, binaries: f.binaries, list: [] }).list.push(f));
  const rank = (p) => Math.max(...p.list.map((f) => f.risk || 0));   // 1.141.0: hoogste risicoscore bovenaan
  const pkgs = Object.values(pk).sort((a, b) => rank(b) - rank(a) || a.name.localeCompare(b.name));
  pkgs.forEach((p) => {
    p.risk = rank(p);
    p.list.sort((a, b) => (b.risk - a.risk) || (b.kev - a.kev) || (b.severity - a.severity));
    p.fixed = p.list.map((f) => f.fixed).filter(Boolean).sort().pop() || null;
  });
  const cnt = [4, 3, 2, 1, 0].map((s) => [s, new Set(fs.filter((f) => f.severity === s).map((f) => f.cve)).size]).filter(([, c]) => c);
  // Dicht, tenzij je hem open had (per account); met zoeken of een filter tijdelijk open als er treffers zijn
  const narrowed = !!$('#vuln-search').value.trim() || fxActive('vulns');
  if (!narrowed) vulnTmp.h.clear();
  const open = narrowed ? vulnTmp.h.get(+h.id) ?? fs.length > 0 : vulnSaved('h', h.id);
  const up = h.upgrade;
  const upTxt = !up ? '' : up.state === 'queued' || up.state === 'running'
    ? `<a href="#" data-vact="progress" data-host="${h.id}" title="${L('Voortgang tonen')}">⏳ ${up.state === 'queued' ? L('Bijwerken gevraagd; de agent pakt het op bij zijn volgende rapport')
      : L('Bezig met bijwerken') + (up.pct ? ` ${up.pct}%` : '')}</a>`
    : up.state === 'ok' ? `<span class="good-txt">✔ ${L('Bijgewerkt {t}', { t: ago(up.at) })}: ${esc((up.pkgs || []).join(' '))}</span>`
      + (!up.verified ? ` · <span class="muted">${L('controle volgt na de volgende scan')}</span>`
        : ` · <span class="${Object.keys(up.verified.still || {}).length ? 'warn-txt' : 'good-txt'}">🔎 ${L('gecontroleerd: {n} kwetsbaarheden opgelost', { n: up.verified.fixed })}${Object.keys(up.verified.still || {}).length
          ? ', ' + L('nog open in {p}', { p: esc(Object.keys(up.verified.still).join(', ')) }) : ''}</span>`)
    : `<span class="bad">✘ ${L('Bijwerken mislukt {t}', { t: ago(up.at) })}</span>`;
  const notes = [
    h.error && !sharedErr ? `<span class="warn-txt">⚠️ ${esc(h.error)}</span>` : '',   // ook in de kop; hier volledig
    h.agent_old ? `<span class="warn-txt">⬆ ${L('Agent {v} of nieuwer nodig voor de softwarelijst', { v: '1.47.0' })}</span>` : '',
    h.reboot ? `<span class="warn-txt" title="${esc(L('Draait: {a} · geïnstalleerd: {b}', { a: h.kernel, b: h.reboot }))}">↻ ${L('Herstart nodig voor de nieuwe kernel')}</span>` : '',
    h.restart && h.restart.length ? `<span class="warn-txt" title="${esc(h.restart.join(', '))}">↻ ${L('{n} service(s) draaien nog met oude bestanden', { n: h.restart.length })}</span>` : '',
    upTxt,
    h.resolved ? `<span class="good-txt" title="${esc(L('Verdwenen bij een nieuwe scan (bijgewerkt of het advies is aangepast); laatste {t}', { t: fmtDateTime(h.resolved.last) }))}">✔ ${L('{n} opgelost in 30 dagen', { n: h.resolved.n })}</span>` : '',
  ].filter(Boolean).join(' · ');
  const fixable = pkgs.filter((p) => p.fixed).map((p) => p.name);
  const total = cnt.reduce((a, [, c]) => a + c, 0);
  const worst = cnt.length ? cnt[0][0] : -1;
  const hh = state && state.hosts ? findHost(h.id) : null;
  return `<details class="card vuln-host vh-w${worst} ${h.error ? 'vh-err' : ''}" data-host="${h.id}" ${open ? 'open' : ''}>
    <summary><span class="host-ic" aria-hidden="true">${hh ? hostIcon(hh) : '🖥️'}</span>
      <span class="vh-name"><b>${esc(h.name)}</b><span class="muted small">${esc(h.os || '')}${h.packages ? ' · ' + L('{n} pakketten', { n: h.packages }) : ''}${h.scanned_at ? ' · ' + L('gescand {t}', { t: ago(h.scanned_at) }) : ''}</span></span>
      <span class="vh-counts">${h.error ? `<span class="warn-txt small" title="${esc(h.error)}">⚠️ ${sharedErr ? L('scan mislukt (zie boven)') : esc(h.error.length > 70 ? h.error.slice(0, 70) + '…' : h.error)}</span>` : ''}${cnt.length ? cnt.map(([s, c]) => `<span class="vpill sev${s}" title="${c} ${VULN_SEV[s][1]}">${c}</span>`).join('') : (h.scanned_at && !h.error ? `<span class="good-txt">✔ ${L('geen bekende kwetsbaarheden')}</span>` : '')}</span>
      ${total ? `<span class="sevbar">${cnt.map(([s, c]) => `<i class="sev${s}" style="width:${(c / total * 100).toFixed(1)}%"></i>`).join('')}</span>` : ''}</summary>
    ${notes ? `<p class="small vh-notes">${notes}${up && up.log ? ` <details class="small"><summary>${L('Uitvoer')}</summary><pre class="code">${esc(up.log)}</pre></details>` : ''}</p>` : ''}
    <div class="vh-actions">
      ${fixable.length ? `<button type="button" class="btn need-admin" data-vact="upgrade-all" data-host="${h.id}">⬆ ${L('Alle beveiligingsupdates installeren ({n})', { n: fixable.length })}</button>` : ''}
      ${h.packages ? `<button type="button" class="btn" data-vact="software" data-host="${h.id}">📦 ${L('Alle software')}</button>
        <a class="btn" href="api.php?${new URLSearchParams({ action: 'vuln_sbom', host_id: h.id })}" title="${esc(L('Softwarelijst met kwetsbaarheden als CycloneDX-bestand (SBOM), voor andere scanners of Dependency-Track'))}">⤓ SBOM</a>` : ''}
    </div>
    ${pkgs.length ? `<div class="table-scroll"><table class="vuln-table">
      <thead><tr><th>${L('Risico')}</th><th>${L('Pakket')}</th><th>${L('Geïnstalleerd')}</th><th>${L('Opgelost in')}</th><th>CVE's</th><th></th></tr></thead>
      <tbody>${pkgs.map((p) => `<tr>
        <td>${riskPill(p.risk)}</td>
        <td><b>${esc(p.name)}</b>${h.exposed[p.name] ? ` <span class="exp-tag" title="${esc(L('Luistert op het netwerk: {p}', { p: h.exposed[p.name].join(', ') }))}">🌐 ${esc(h.exposed[p.name].join(', '))}</span>` : ''}
          ${p.binaries && p.binaries !== p.name ? `<div class="muted small" title="${esc(p.binaries)}">${esc(p.binaries.length > 60 ? p.binaries.slice(0, 60) + '…' : p.binaries)}</div>` : ''}</td>
        <td class="mono small">${esc(p.version)}</td>
        <td class="mono small">${p.fixed ? esc(p.fixed) : `<span class="muted">${L('nog geen oplossing')}</span>`}</td>
        <td class="cve-cell">${p.list.slice(0, 6).map(vulnChip).join(' ')}${p.list.length > 6 ? ` <button type="button" class="cve-more" data-vact="more" data-host="${h.id}" data-pkg="${esc(p.name)}">+${p.list.length - 6}</button>` : ''}</td>
        <td>${p.fixed ? `<button type="button" class="icon-btn need-admin" title="${esc(L('Bijwerken'))}" data-vact="upgrade" data-host="${h.id}" data-pkg="${esc(p.name)}">⬆</button>` : ''}</td>
      </tr>`).join('')}</tbody></table></div>` : (h.scanned_at ? `<p class="muted small">${vulnFilter === 'all' && !$('#vuln-search').value ? L('Geen kwetsbaarheden gevonden.') : L('Niets met dit filter.')}</p>` : `<p class="muted small">${L('Nog niet gescand.')}</p>`)}
  </details>`;
}

function vulnClick(e) {
  const vou = e.target.closest('[data-vou]');
  if (vou) return vulnOneUpDo(vou.dataset.vou);
  const det = e.target.closest('details.vuln-host');
  if (det && $(':scope > summary', det).contains(e.target)) {   // open/dicht onthouden (per account)
    setTimeout(() => { vulnTmp.h.set(+det.dataset.host, det.open); vulnOpenSave('h', [[+det.dataset.host, det.open]]); }, 0);
    return;
  }
  const chip = e.target.closest('[data-cve]');
  if (chip) return vulnDetail(chip.dataset.cve);
  const b = e.target.closest('[data-vact]');
  if (!b) return;
  const h = vulnData.hosts.find((x) => x.id === +b.dataset.host);
  if (b.dataset.vact === 'upgrade') return vulnUpgrade(h, [b.dataset.pkg]);
  if (b.dataset.vact === 'upgrade-all') return vulnUpgrade(h, null);
  if (b.dataset.vact === 'software') return vulnSoftware(h);
  if (b.dataset.vact === 'progress') return vulnUpgradeDialog(h, true);
  if (b.dataset.vact === 'more') {
    const fs = vulnVisible().filter((f) => f.host_id === h.id && f.package === b.dataset.pkg);
    b.parentElement.innerHTML = fs.map(vulnChip).join(' ');
  }
}

/** 1.179.0: blok Rugbaarheid (meter, bronnen, verloop) en Raakt dit jou echt? (AI) in de popup van een kwetsbaarheid */
function vulnBuzzHtml(d) {
  const b = d.buzz;
  if (!b) return '';
  const x = b.data || {};
  const lvl = b.score >= b.threshold ? 'hot' : b.score >= 30 ? 'mid' : 'low';
  const ssvc = x.ssvc ? ({ active: L('actief misbruikt'), poc: L('er is een proof-of-concept'), none: L('geen misbruik bekend') }[x.ssvc.e] || '?')
    + (x.ssvc.a === 'yes' ? ' · ' + L('automatiseerbaar') : '') + (x.ssvc.t === 'total' ? ' · ' + L('volledige overname') : '') : L('nog geen oordeel');
  const yes = (v) => (v ? `<b class="bad">${L('ja')}</b>` : L('nee'));
  const cnt = (n) => (+n ? `<b>${(+n).toLocaleString(LOCALE)}</b>` : '0');
  const hist = (b.history || []).slice(-14);
  const max = Math.max(10, ...hist.map((h) => +h[1]));
  const spark = hist.length > 1 ? `<svg class="vbz-spark" viewBox="0 0 ${(hist.length - 1) * 10} 30" preserveAspectRatio="none" aria-hidden="true"><polyline points="${hist.map((h, i) => `${i * 10},${(30 - (h[1] / max) * 28).toFixed(1)}`).join(' ')}"/></svg>` : '';
  const ai = VULN_AI[b.ai];
  const tag = (u) => `${esc(b.mastodon)}/tags/${u}`;
  const m = /^CVE-(\d{4})-(\d+)$/.exec(d.cve);
  return `<section class="vbz vbz-${lvl}" id="vbz">
    <div class="vbz-top">
      <div class="vbz-ring" style="--p:${b.score}"><div><b>${b.checked_at ? b.score : '–'}</b><small>${L('rugbaarheid')}</small></div></div>
      <div class="vbz-txt"><h3>🔥 ${L('Rugbaarheid')} ${b.checked_at && b.trend ? `<span class="vbz-trend ${b.trend > 0 ? 'up' : 'down'}">${b.trend > 0 ? '↑ +' : '↓ '}${b.trend} ${L('in 7 dagen')}</span>` : ''}</h3>
        <p class="muted small">${b.checked_at ? L('Exploits {e}/60 · praat {t}/40 · bijgewerkt {w}', { e: b.exploit, t: b.talk, w: ago(b.checked_at) }) : b.on ? L('Nog niet bijgewerkt; dat gebeurt bij de volgende scan.') : L('Staat uit (Instellingen → Kwetsbaarheden → Rugbaarheid).')}</p>
        ${spark}
        ${b.on ? `<button type="button" class="btn small-btn" data-vbuzz-now>↻ ${L('Nu bijwerken')}</button>` : ''}</div>
    </div>
    ${b.checked_at ? `<div class="vbz-src">
      <span>⚠️ ${L('Actief misbruikt (CISA KEV)')}</span><span>${yes(d.kev)}</span>
      <span>🏛️ ${L('Oordeel van CISA (SSVC)')}</span><span>${esc(ssvc)}</span>
      <span>💥 <a href="https://github.com/search?type=repositories&q=${encodeURIComponent('"' + d.cve + '"')}" target="_blank" rel="noopener noreferrer">${L("Openbare PoC's op GitHub")}</a></span><span>${cnt(x.gh)}</span>
      <span>🗡️ ${L('Exploit op Exploit-DB')}</span><span>${yes(x.edb)}</span>
      <span>🎯 ${L('Nuclei-template (scanners zoeken ernaar)')}</span><span>${yes(x.nuclei)}</span>
      <span>🟠 <a href="https://hn.algolia.com/?query=${encodeURIComponent('"' + d.cve + '"')}" target="_blank" rel="noopener noreferrer">Hacker News</a> <span class="muted small">${L('7 dagen · totaal')}</span></span><span>${cnt(x.hn7)} · ${cnt(x.hn)}</span>
      <span>🐘 ${m ? `<a href="${tag('CVE' + m[1] + m[2])}" target="_blank" rel="noopener noreferrer">Mastodon</a>` : 'Mastodon'} <span class="muted small">${L('7 dagen')}</span></span><span>${cnt(x.md7)}</span>
    </div>` : ''}
    ${aiOn() ? `<div class="vbz-ai"><div><b>🤖 ${L('Raakt dit jou echt?')}</b>${ai ? ` <span class="ai-verdict ${ai[0]}">${esc(ai[1]())}</span>` : ''}
        <p class="muted small">${L('De AI kijkt naar je servers: staat het pakket open naar het netwerk, is er al misbruik, is er een oplossing. Je krijgt een oordeel en wat je moet doen.')}</p></div>
      ${aiBtn('cve', b.id, true)}</div>` : ''}
  </section>`;
}

/** CVSS-vector in gewone woorden: hoe is hij te misbruiken? */
function cvssWords(v) {
  if (!v) return '';
  const m = Object.fromEntries(v.split('/').map((p) => p.split(':')));
  return [
    { N: L('via het netwerk'), A: L('vanaf het lokale netwerk'), L: L('alleen lokaal op de server'), P: L('alleen met fysieke toegang') }[m.AV],
    { N: L('zonder in te loggen'), L: L('met een gewoon account'), H: L('met beheerdersrechten') }[m.PR],
    { N: L('zonder dat een gebruiker iets doet'), R: L('een gebruiker moet iets doen (bv. een link openen)'), P: L('een gebruiker moet iets doen') }[m.UI],
    m.AC === 'H' ? L('moeilijk uit te voeren') : null,
  ].filter(Boolean).join(' · ');
}

async function vulnDetail(cve) {
  let d;
  try { d = await api('vuln_detail', null, { cve }); } catch (ex) { return toast(ex.message, 'err'); }
  const [icon, word] = VULN_SEV[d.severity] || VULN_SEV[0];
  const rows = [
    [L('Ernst'), `${icon} <b>${esc(word)}</b>${d.cvss !== null ? ` · CVSS <b>${dec(d.cvss)}</b>` : ''}${d.vector ? `<div class="muted small">${esc(cvssWords(d.vector))}</div><div class="mono small muted">${esc(d.vector)}</div>` : ''}`],
    [L('Actief misbruikt'), d.kev ? `<b class="bad">⚠️ ${L('ja')}</b>${d.kev_added ? ' · ' + L('op de lijst van CISA sinds {t}', { t: esc(d.kev_added) }) : ''}` : L('niet bekend')],
    [L('Kans op misbruik'), d.epss !== null ? L('{p} in de komende 30 dagen (EPSS)', { p: dec((d.epss * 100).toFixed(d.epss < 0.01 ? 2 : 1)) + '%' }) : '–'],
    ...(d.accepted.length ? [[L('Geaccepteerd'), d.accepted.map((a) => `<div class="vd-acc">${a.expired ? `<span class="warn-txt">${L('verlopen')}</span>` : '✔'}
      ${esc(a.host ? `${a.host}${a.package ? ' · ' + a.package : ''}` : L('alle servers'))} · ${a.until ? (a.expired ? L('was tot {d}', { d: esc(a.until) }) : L('tot {d}', { d: esc(a.until) })) : L('voor altijd')}
      <div class="muted small">${esc(a.reason || '–')} · ${esc(a.by)}, ${esc(fmtDateTime(a.at))}</div>
      <button type="button" class="btn small-btn need-user" data-vd-unign="${a.id}">${L('Opheffen')}</button></div>`).join('')]] : []),
    [L('Gepubliceerd'), d.published ? esc(fmtDateTime(d.published.slice(0, 19).replace('T', ' '))) : '–'],
    ...(d.aliases.length ? [[L('Ook bekend als'), d.aliases.map(esc).join(', ')]] : []),
  ];
  const hostRows = d.hosts.map((x, i) => `<div class="vd-host">
      <div><b>${esc(x.host)}</b> · <span class="mono small">${esc(x.package)} ${esc(x.version)}</span> → ${x.fixed ? `<span class="mono small good-txt">${esc(x.fixed)}</span>` : `<span class="muted">${L('nog geen oplossing')}</span>`}
        ${x.ignored ? ` · <span class="muted">${L('geaccepteerd')}</span>` : ''}</div>
      ${x.command ? copyBox('vd-cmd-' + i, x.command) : ''}
      ${x.fixed ? (x.upgrade_blocked ? `<p class="muted small">${L('Bijwerken via de agent kan hier niet: {why}. Voer het commando hierboven zelf uit op de server.', { why: esc(x.upgrade_blocked) })}</p>`
        : `<button type="button" class="btn need-admin" data-vd-up="${i}">⬆ ${L('Bijwerken via de agent')}</button>`) : ''}
    </div>`).join('');
  const { form } = modal({
    title: `${icon} ${cve}`, wide: true,
    body: `<div style="padding:1rem 1.2rem">
      ${d.summary ? `<p><b>${esc(d.summary)}</b></p>` : ''}
      ${d.details ? `<details class="vd-details" ${d.details.length < 600 ? 'open' : ''}><summary>${L('Omschrijving')}</summary><p class="small" style="white-space:pre-wrap">${esc(d.details)}</p></details>` : ''}
      <table class="kv">${rows.map(([k, v]) => `<tr><th>${k}</th><td>${v}</td></tr>`).join('')}</table>
      ${vulnBuzzHtml(d)}
      <h3>${L('Zo los je het op')}</h3>
      ${xpHtml(L('Installeer de oplossing uit de pakketbron van je distributie.'), L('Installeer de nieuwe versie uit de eigen pakketbron van de distributie (zoals hieronder); een download bij de maker is niet nodig. <b>Goed om te weten:</b> bij de kernel of een bibliotheek is daarna een herstart van de server of van de services nodig.'))}
      ${hostRows}
      <h3>${L('Meer informatie en adviezen')}</h3>
      <ul class="vd-links">${d.links.map((l) => `<li><a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.label)}</a> <span class="muted small">${esc(l.url.replace(/^https?:\/\//, '').slice(0, 70))}</span></li>`).join('')}</ul>
    </div>`,
    buttons: [
      { label: '✔ ' + L('Risico accepteren…'), cls: 'need-user', style: 'margin-right:auto', onClick: () => vulnIgnore(d) },
      { label: L('Sluiten'), cls: 'primary', submit: true },
    ],
  });
  wireCopy(form);
  const bn = $('[data-vbuzz-now]', form);
  if (bn) bn.onclick = async () => {
    bn.disabled = true;
    bn.textContent = L('Bezig…');
    try { const r = await api('vuln_buzz_now', { cve }); d.buzz = r.buzz; $('#vbz', form).outerHTML = vulnBuzzHtml(d); if (vulnData && vulnData.buzz) vulnData.buzz[cve] = { ...(vulnData.buzz[cve] || {}), id: r.buzz.id, score: r.buzz.score, trend: r.buzz.trend }; }
    catch (ex) { toast(ex.message, 'err'); bn.disabled = false; }
  };
  $$('[data-vd-unign]', form).forEach((b) => (b.onclick = async () => {
    try { await api('vuln_unignore', { id: +b.dataset.vdUnign }); toast(L('Telt weer mee')); $('#modal').close(); loadVulns(); vulnDetail(cve); }
    catch (ex) { toast(ex.message, 'err'); }
  }));
  $$('[data-vd-up]', form).forEach((b) => (b.onclick = () => {
    const x = d.hosts[+b.dataset.vdUp];
    vulnUpgrade(vulnData.hosts.find((h) => h.id === x.host_id) || { id: x.host_id, name: x.host }, [x.package]);
  }));
}

function vulnIgnore(d) {
  modal({
    title: L('Risico accepteren: {cve}', { cve: d.cve }),
    body: `<div style="padding:1rem 1.2rem">
      <p class="muted small">${L('Een geaccepteerde kwetsbaarheid telt niet meer mee en geeft geen melding. Je ziet hem terug onder het filter Geaccepteerd.')}</p>
      <label>${L('Waarvoor')}<select name="scope">
        <option value="all">${L('Alle servers')}</option>
        ${d.hosts.map((x, i) => `<option value="${i}">${esc(x.host)} · ${esc(x.package)}</option>`).join('')}
      </select></label>
      <label>${L('Reden')} <span class="hint">${L('(bv. niet bereikbaar van buitenaf)')}</span><input name="reason" maxlength="300" required></label>
      <label>${L('Hoe lang')}<select name="until">
        <option value="30">${L('30 dagen')}</option><option value="90" selected>${L('90 dagen')}</option><option value="180">${L('180 dagen')}</option>
        <option value="365">${L('1 jaar')}</option><option value="">${L('voor altijd')}</option>
      </select></label>
      <p class="hint">${L('Daarna telt hij weer mee, zodat je er opnieuw naar kijkt. Is er dan nog niets veranderd, accepteer hem dan opnieuw.')}</p>
    </div>`,
    buttons: [{ label: L('Annuleren'), onClick: () => $('#modal').close() }, { label: '✔ ' + L('Accepteren'), cls: 'primary', submit: true }],
    onSubmit: async (v) => {
      const x = v.scope === 'all' ? null : d.hosts[+v.scope];
      const until = v.until ? new Date(Date.now() + +v.until * 86400000).toISOString().slice(0, 10) : '';
      await api('vuln_ignore', { cve: d.cve, reason: v.reason, until, host_id: x ? x.host_id : null, package: x ? x.package : null });
      toast(L('Geaccepteerd'));
      loadVulns();
    },
  });
}

/** Bijwerken via de agent (beheerders); kan dat niet, dan het commando om zelf uit te voeren */
function vulnUpgrade(h, pkgs) {
  const all = pkgs === null;
  modal({
    title: all ? L('Alle beveiligingsupdates installeren op {name}', { name: h.name }) : L('Bijwerken op {name}', { name: h.name }),
    body: `<div style="padding:1rem 1.2rem">
      <p>${all ? L('De agent installeert de nieuwe versie van alle pakketten waarvoor een oplossing is.') : L('De agent installeert de nieuwe versie van: {p}', { p: `<b>${esc(pkgs.join(' '))}</b>` })}</p>
      ${xpHtml(L('Bijwerken gebeurt bij het volgende rapport van de agent.'), L('Dit gebeurt bij het volgende rapport van de agent, met de pakketbeheerder van de server (dnf of apt), en komt in het logboek. Er wordt niets herstart; is dat nodig, dan zie je ↻ bij de server.'))}
      ${h.upgrade_blocked ? `<p class="warn-txt">${L('Bijwerken via de agent kan hier niet: {why}.', { why: esc(h.upgrade_blocked) })}</p>` : confirmField('BIJWERKEN')}
      <div id="vu-cmd"></div>
    </div>`,
    buttons: h.upgrade_blocked ? [{ label: L('Commando tonen'), cls: 'primary', submit: true }] : [{ label: L('Annuleren'), onClick: () => $('#modal').close() }, { label: '⬆ ' + L('Bijwerken'), cls: 'primary', submit: true }],
    onSubmit: async (v, form) => {
      try {
        const res = await api('vuln_upgrade', { host_id: h.id, all, packages: pkgs || [], confirm: v.confirm });
        // In hetzelfde venster meteen de voortgang tonen (eerst "wachten op de agent"), niet eerst sluiten
        vulnUpgradeDialog(h, true, { state: 'queued', pkgs: res.packages || pkgs || [] });
        loadVulns();
        return 'keep';
      } catch (ex) {
        // Kan het niet via de agent? Dan het commando tonen om zelf uit te voeren
        if (ex.data && ex.data.command) {
          $('#vu-cmd', form).innerHTML = `<p class="muted small">${L('Voer dit zelf uit op de server:')}</p>${copyBox('vu-cmd-line', ex.data.command)}`;
          wireCopy(form);
          throw new Error(ex.message);
        }
        throw ex;
      }
    },
  });
}

// ---------------------------------------------------------------- Bijwerken via de agent: voortgang
// Agent 1.48.0+ meldt elke paar seconden de stap, het percentage en het pakket; oudere agents alleen het begin en de uitkomst.
const VULN_UP_STEPS = [['queued', L('Wachten op de agent')], ['update', L('Pakketlijst ophalen')], ['download', L('Downloaden')], ['install', L('Installeren')], ['done', L('Klaar')]];
let vulnUpPoll = null;
const vulnUpShown = () => $('#modal').open && !!$('#modal-body .vu-dlg');

/** Venster met de voortgang van het bijwerken op server h; force = openen, ook als er een ander venster openstaat. */
async function vulnUpgradeDialog(h, force, first) {
  clearTimeout(vulnUpPoll);
  let r;
  if (first) r = { status: first, live: true };   // meteen iets tonen; de echte stand volgt hieronder
  else {
    try { r = await api('vuln_upgrade_status', null, { host_id: h.id }); }
    catch (ex) {
      // Even geen antwoord: het venster blijft staan en vraagt het zo opnieuw
      if (force && !vulnUpShown()) r = { status: { state: 'queued', pkgs: [] }, live: true };
      else { if (vulnUpShown()) vulnUpPoll = setTimeout(() => vulnUpgradeDialog(h), 3000); return; }
    }
  }
  if (!force && !vulnUpShown()) return;   // venster gesloten: stoppen
  const st = r.status || { state: 'queued', pkgs: [] };
  const busy = ['queued', 'running'].includes(st.state);
  const step = st.state === 'queued' ? 'queued' : st.state === 'ok' || st.state === 'error' ? 'done'
    : st.stage === 'verify' ? 'install' : st.stage || 'update';
  const cur = VULN_UP_STEPS.findIndex(([k]) => k === step);
  // Zonder tussenstand (oude agent, of nog niets gehoord): een bewegende balk zonder percentage
  const known = st.state === 'ok' || st.state === 'error' || typeof st.pct === 'number';
  const pct = st.state === 'ok' ? 100 : st.state === 'queued' ? 2 : known ? st.pct : 100;
  const since = st.sent ? ' · ' + L('gestart {t}', { t: ago(st.sent) }) : '';
  const rescanned = st.state === 'ok' && r.scanned_at && r.scanned_at >= st.at;
  const label = VULN_UP_STEPS[cur][1];
  const now = st.state === 'queued' ? '⏳ ' + L('Wachten op de agent: hij pakt de opdracht op bij zijn volgende rapport.')
    : st.state === 'ok' ? '✔ ' + L('Bijgewerkt: {p}', { p: esc((st.pkgs || []).join(' ')) })
    : st.state === 'error' ? '✘ ' + L('Bijwerken mislukt')
    : known ? `⏳ ${st.stage === 'verify' ? L('Controleren') : label}${st.detail ? `: <b>${esc(st.detail)}</b>` : ''}${st.count ? ` <span class="muted">(${esc(st.count)})</span>` : ''}`
    : '⏳ ' + L('Bezig met bijwerken') + since;
  const after = st.state !== 'ok' ? ''
    : rescanned ? `<p class="good-txt small">🔍 ${L('Opnieuw gescand: de lijst met kwetsbaarheden is bijgewerkt.')}</p>`
    : `<p class="muted small">🔍 ${L('RzSense scant opnieuw zodra de agent de nieuwe softwarelijst stuurt (meestal binnen een paar minuten).')}</p>`;
  const pk = st.pkgs || [];
  let nowTxt = now.replace(/^[⏳✔✘] /, '');
  if (nowTxt.startsWith(label + ': ')) nowTxt = nowTxt.slice(label.length + 2);   // de stap staat er al boven
  if (vulnUpShown()) updKeepScroll(); else { updKept.log = null; updKept.scroll = null; }
  modal({
    title: L('Bijwerken op {name}', { name: h.name }),
    body: `<div class="upd-dlg vu-dlg ${st.state === 'ok' ? 'ok' : st.state === 'error' ? 'error' : ''}">
      ${updHead(L('Bijwerken op {name}', { name: esc(h.name) }), [updChip(pk.length === 1 ? pk[0] : L('{n} pakketten', { n: pk.length }), true)], UPD_SRV)}
      <div class="upd-body">
        <div class="upd-prog">${updRing(known || st.state === 'queued' ? pct : null, st.state === 'ok' ? L('klaar') : st.state === 'error' ? L('gestopt') : since.replace(' · ', ''))}${updSteps(VULN_UP_STEPS, cur, st.state === 'queued' ? 'running' : st.state, nowTxt)}</div>
        ${busy && st.state === 'running' && !r.live ? `<p class="muted small">${L('Deze agent meldt geen tussenstand. Werk hem bij naar {v} voor een voortgangsbalk.', { v: '1.48.0' })}</p>` : ''}
        ${after}
        <p class="muted small">${L('Pakketten')}: <span class="mono">${esc(pk.join(' '))}</span></p>
        ${updLog(st.log, st.state === 'error', 8)}
      </div></div>`,
    buttons: busy ? [{ label: L('Op de achtergrond'), onClick: () => { $('#modal').close(); loadVulns(); } }]
      : [{ label: L('Sluiten'), cls: 'primary', onClick: () => { $('#modal').close(); loadVulns(); } }],
  });
  $('#modal').classList.add('upd-modal');
  updLogScroll();
  // Doorvragen tot klaar, en daarna tot de nieuwe scan er is (hooguit 15 minuten)
  if (busy || (st.state === 'ok' && !rescanned && Date.now() - new Date(st.at.replace(' ', 'T')) < 900000)) {
    vulnUpPoll = setTimeout(() => vulnUpgradeDialog(h), busy ? 2000 : 5000);
  } else if (!$('#tab-vulns').hidden) loadVulns();
}

async function vulnSoftware(h) {
  let r;
  try { r = await api('vuln_packages', null, { host_id: h.id }); } catch (ex) { return toast(ex.message, 'err'); }
  const { form } = modal({
    title: L('Alle software op {name}', { name: h.name }), wide: true,
    body: `<div style="padding:1rem 1.2rem">
      <p class="muted small">${esc(h.os || '')} · ${L('{n} pakketten', { n: r.packages.length })}</p>
      <input type="search" id="vs-search" placeholder="${L('Zoek pakket…')}" autocomplete="off">
      <div class="table-scroll" style="max-height:55vh"><table class="vuln-table" id="vs-table"></table></div>
    </div>`,
    buttons: [{ label: L('Sluiten'), cls: 'primary', submit: true }],
  });
  const draw = () => {
    const q = $('#vs-search', form).value.trim().toLowerCase();
    const list = r.packages.filter((p) => !q || p.name.toLowerCase().includes(q) || p.source.toLowerCase().includes(q)).slice(0, 2000);
    $('#vs-table', form).innerHTML = `<thead><tr><th>${L('Pakket')}</th><th>${L('Versie')}</th><th>${L('Architectuur')}</th><th>${L('Bron')}</th><th></th></tr></thead><tbody>
      ${list.map((p) => `<tr><td>${esc(p.name)}</td><td class="mono small">${esc(p.version)}</td><td class="small">${esc(p.arch)}</td><td class="small muted">${p.source !== p.name ? esc(p.source) : ''}</td>
        <td>${p.vulns ? `<span class="vc sev3">🐞 ${p.vulns}</span>` : ''}</td></tr>`).join('')}</tbody>`;
  };
  $('#vs-search', form).oninput = draw;
  draw();
}

/** Instellingen: welke servers niet gescand worden (vinkjes → verborgen veld vuln_exclude) */
function vulnExcludeEditor() {
  const f = $('#settings-form');
  const el = $('#vuln-exclude-list');
  if (!f || !el || !f.vuln_exclude) return;
  const ex = new Set(String(f.vuln_exclude.value || '').split(',').filter(Boolean).map(Number));
  const hosts = state.hosts.filter((h) => h.mode !== 'remote');
  el.innerHTML = hosts.length ? hosts.map((h) => `<label class="chk-inline"><input type="checkbox" data-vex="${h.id}" ${ex.has(+h.id) ? 'checked' : ''}> ${esc(h.name)}</label>`).join(' ')
    : `<span class="muted small">${L('geen servers met een agent')}</span>`;
  $$('[data-vex]', el).forEach((c) => (c.onchange = () => {
    f.vuln_exclude.value = $$('[data-vex]', el).filter((x) => x.checked).map((x) => x.dataset.vex).join(',');
    markSettingsDirty(true, c);
  }));
}

// ---------------------------------------------------------------- ⏳ Verouderd: end-of-life (1.227.0)
let eolData = null;
let eolFilter = 'bad';
const EOL_LV = { crit: ['⛔', () => L('Buiten ondersteuning')], warn: ['⏳', () => L('Binnenkort')], info: ['ℹ️', () => L('Ter info')], ok: ['✔', () => L('Ondersteund')] };
async function loadEol() {
  const box = $('#eol-list');
  if (!box) return;
  try { eolData = await api('eol'); } catch (ex) { box.innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  renderEol();
}
function renderEol() {
  const d = eolData, box = $('#eol-list');
  if (!d || !box) return;
  const c = d.counts || {};
  const bad = (c.crit || 0) + (c.warn || 0);
  if ($('#vt-n-eol')) $('#vt-n-eol').textContent = bad ? String(bad) : '';
  $('#eol-counts').innerHTML = ['crit', 'warn', 'info', 'ok'].map((k) => `<span class="hc hc-${k === 'crit' ? 'crit' : k === 'warn' ? 'warn' : k === 'ok' ? 'ok' : 'unknown'}"><b>${c[k] || 0}</b> ${EOL_LV[k][0]} ${esc(EOL_LV[k][1]())}</span>`).join('');
  const st = d.state || {};
  $('#eol-info').textContent = st.ok ? L('Bijgewerkt {t}', { t: new Date(st.ok * 1000).toLocaleString(LOCALE, { dateStyle: 'short', timeStyle: 'short' }) }) + (st.error ? ' · ⚠ ' + st.error : '') : (st.error || L('Nog niet opgezocht: dat gebeurt eens per dag'));
  const chips = [['bad', L('Aandacht')], ['all', L('Alles')]];
  $('#eol-filter').innerHTML = chips.map(([k, l]) => `<button type="button" class="dchip ${eolFilter === k ? 'on' : ''}" data-eol-f="${k}">${l}</button>`).join('');
  const q = ($('#eol-search').value || '').toLowerCase();
  const rows = d.rows.filter((r) => (eolFilter === 'all' || ['crit', 'warn'].includes(r.level)) && (!q || `${r.host} ${r.label} ${r.cycle}`.toLowerCase().includes(q)));
  if (!d.rows.length) { box.innerHTML = `<p class="muted">${L('Nog geen softwarelijsten van de agents. Die komen met het volgende rapport (agent 1.47.0 of nieuwer).')}</p>`; return; }
  box.innerHTML = rows.length ? `<div class="table-scroll"><table class="vuln-table eol-tbl"><thead><tr><th>${L('Server')}</th><th>${L('Software')}</th><th>${L('Versie')}</th><th>${L('Updates tot')}</th><th>${L('Opvolger')}</th></tr></thead><tbody>${rows.map((r) => {
    const lv = EOL_LV[r.level] || EOL_LV.ok;
    const until = !r.known ? `<span class="muted">${L('onbekend bij endoflife.date')}</span>` : r.eol ? `${esc(new Date(r.eol + 'T12:00').toLocaleDateString(LOCALE, { dateStyle: 'medium' }))} <span class="muted small">${r.days < 0 ? L('{n} dagen geleden', { n: -r.days }) : L('over {n} dagen', { n: r.days })}</span>` : r.state === 'eol' ? L('al voorbij') : L('geen einddatum bekend');
    return `<tr class="eol-${r.level}"><td>${esc(r.host)}</td><td>${lv[0]} <b>${esc(r.label)} ${esc(r.cycle)}</b>${r.kind === 'os' ? ` <span class="pill">${L('systeem')}</span>` : ''}${r.lts ? ' <span class="pill">LTS</span>' : ''}${r.level === 'info' ? `<div class="muted small">${L('uit de pakketbron van je distributie: die levert vaak nog beveiligingsupdates')}</div>` : ''}</td>
      <td class="mono small">${esc(r.version)}</td><td>${until}</td><td>${r.successor ? esc(r.label + ' ' + r.successor) : '–'}</td></tr>`;
  }).join('')}</tbody></table></div>` : `<p class="muted">✔ ${L('Niets wat aandacht vraagt.')}</p>`;
}
function initEol() {
  initVulnTabs();
  if (!$('#eol-list')) return;
  $('#eol-search').oninput = renderEol;
  $('#eol-filter').onclick = (e) => { const b = e.target.closest('[data-eol-f]'); if (b) { eolFilter = b.dataset.eolF; renderEol(); } };
  $('#eol-refresh').onclick = async (e) => {
    e.target.disabled = true;
    try { eolData = await api('eol_refresh', {}); renderEol(); toast(L('Opgezocht bij endoflife.date')); } catch (ex) { toast(ex.message, 'err'); }
    e.target.disabled = false;
  };
}
// ---------------------------------------------------------------- Dashboard (1.134.0)
// De startpagina: alles samen. Servers en checks komen uit `state` (live), de rest uit api('home') (hooguit eens per minuut).
const HM_PERIODS = [['7d', () => L('7 dagen')], ['30d', () => L('30 dagen')], ['90d', () => L('90 dagen')]];
let hmPeriod = uiGet('hm_period', 'rzmon-hm-period', '7d');
let hmData = null;
let hmAt = 0;
const HM_ST = { ok: () => L('In orde'), warn: () => L('Aandacht'), crit: () => L('Storing'), unk: () => L('Onbekend') };
// Vorm naast kleur: rondje = in orde, vierkant = aandacht, driehoek = storing (ook zonder kleur te lezen)
const hmShape = (st, size = 10) => `<svg class="hm-shape ${st}" width="${size}" height="${size}" viewBox="0 0 10 10" role="img" aria-label="${esc(HM_ST[st]())}">${
  st === 'ok' ? '<circle cx="5" cy="5" r="5"/>' : st === 'warn' ? '<rect width="10" height="10" rx="2"/>' : st === 'unk' ? '<circle cx="5" cy="5" r="3.8" fill="none" stroke-width="2.4"/>' : '<path d="M5 0L10 10H0Z"/>'}</svg>`;
const hmStOf = (s) => (s === 2 ? 'crit' : s === 1 ? 'warn' : 'ok');
const hmNum = (n) => Number(n || 0).toLocaleString(LOCALE);

async function loadHome(fresh = false) {
  const cc = dashMode() === 'cc';   // 1.154.0: het Command center heeft ook "Vandaag"
  const per = cc ? CC_PERIODS : HM_PERIODS, cur = cc ? ccPeriod : hmPeriod;
  $('#hm-period').innerHTML = per.map(([k, l]) => `<button type="button" class="seg-btn ${k === cur ? 'active' : ''}" data-hmp="${k}">${esc(l())}</button>`).join('');
  $$('[data-hmp]').forEach((b) => (b.onclick = () => {
    if (dashMode() === 'cc') { ccPeriod = b.dataset.hmp; uiSet('cc_period', 'rzmon-cc-period', ccPeriod); }
    else { hmPeriod = b.dataset.hmp; uiSet('hm_period', 'rzmon-hm-period', hmPeriod); }
    loadHome();
  }));
  if ($('#hm-tools')) $('#hm-tools').innerHTML = ccTools();
  if ($('#hm-live')) $('#hm-live').innerHTML = livePill();   // 1.157.3: rechtsboven op de pagina
  const q = { period: cc ? (['30d', '90d'].includes(ccPeriod) ? ccPeriod : '7d') : hmPeriod, ...(fresh ? { fresh: 1 } : {}) };
  if (cc) Object.assign(q, { cc: 1, ccp: ccPeriod, ...(ccSeenAt ? { seen: ccSeenAt } : {}) });
  try { hmData = await api('home', null, q); hmAt = Date.now(); } catch (ex) { $('#home').innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  $('#hm-period').hidden = !hmData.full && !cc;
  renderHome();
}

/** Dagreeks {datum: waarde} → [waarden] (zonder lege dagen) */
const hmVals = (series) => Object.values(series || {}).filter((v) => v !== null && v !== undefined).map(Number);

/** Klein lijntje onder een tegel */
function hmSpark(vals, cls) {
  if (vals.length < 2) return '<div class="hm-spark-empty"></div>';
  const W = 220, H = 40, mn = Math.min(...vals), mx = Math.max(...vals), r = mx - mn || 1;
  const pts = vals.map((v, i) => [i * W / (vals.length - 1), 4 + (H - 8) * (1 - (v - mn) / r)]);
  const line = pts.map((p, i) => `${i ? 'L' : 'M'}${p[0].toFixed(1)} ${p[1].toFixed(1)}`).join('');
  return `<svg class="hm-spark ${cls}" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true"><path class="a" d="${line}L${W} ${H}L0 ${H}Z"/><path class="l" d="${line}"/></svg>`;
}

/** Wat de servers en checks nu doen (uit state) */
function hmLive() {
  const checks = state.hosts.flatMap((h) => h.checks).filter((c) => +c.enabled && !c.maintenance);
  const n = [0, 0, 0, 0];
  checks.forEach((c) => n[Math.min(3, +c.status)]++);
  return { checks, n, total: checks.length };
}

function renderHome() {
  if (!hmData || !state || !state.hosts) return;
  if (dashMode() === 'cc') return hmData.cc ? renderCC() : loadHome();   // 1.154.0
  $('.hm-title').textContent = L('Zo staat het ervoor');
  const d = hmData, live = hmLive();
  $('#hm-sub').textContent = L('Monitoring, beveiliging, kwetsbaarheden en netwerk op één plek') + ' · '
    + L('bijgewerkt {t}', { t: new Date(hmAt).toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit' }) });
  const score = d.full ? d.score : (state.health ? state.health.score : 100);
  const todo = d.full ? d.todo : live.checks.filter((c) => +c.status === 2 || +c.status === 1).sort((a, b) => b.status - a.status)
    .map((c) => ({ sev: +c.status === 2 ? 2 : 1, text: `${c.name} – ${(state.hosts.find((h) => +h.id === +c.host_id) || {}).name || ''}`, go: 'check:' + c.id }));
  const open = todo.filter((t) => t.sev >= 1).length;
  const scoreCls = score >= 90 ? 'good' : score >= 60 ? 'warn' : 'bad';
  const prevAvail = d.full && d.avail.prev !== null ? d.avail.now - d.avail.prev : null;

  // Tegels (1.135.0, zoals het ontwerp): Hosts, Meldingen, Kritieke CVE en Agents; elk een groot getal, de status en een lijntje
  const tiles = [];
  const hl = state.health || {};
  const down = (hl.hosts_total || 0) - (hl.hosts_up || 0);
  tiles.push({ go: 'dashboard', label: L('Hosts'), st: down ? 'crit' : 'ok', big: hmNum(hl.hosts_up || 0), unit: L('/ {n} online', { n: hl.hosts_total || 0 }),
    sub: down ? L('{n} onbereikbaar', { n: down }) : L('alles bereikbaar'), spark: d.full ? hmSpark(hmVals(d.avail.series), 's1') : '' });
  const probs = live.n[1] + live.n[2];
  tiles.push({ go: 'alerts', label: L('Meldingen'), st: live.n[2] ? 'crit' : live.n[1] ? 'warn' : 'ok', big: hmNum(probs), unit: L('open problemen'),
    sub: probs ? [live.n[1] && L('{n} aandacht', { n: live.n[1] }), live.n[2] && L('{n} storing', { n: live.n[2] })].filter(Boolean).join(' · ') : L('/ {n} checks OK', { n: live.total }).replace(/^\/ /, ''),
    spark: d.full ? hmSpark(hmVals(d.ids.series.crit).map((v, i) => v + (hmVals(d.ids.series.warn)[i] || 0)), 's2') : '' });
  if (d.vulns) {
    const v = d.vulns;
    tiles.push({ go: 'vulns', label: L('Kritieke CVE'), st: v.sev[4] ? 'crit' : v.sev[3] ? 'warn' : 'ok', big: hmNum(v.sev[4]), unit: v.kev ? L('{n} in KEV', { n: v.kev }) : L('geen in KEV'),
      sub: L('{n} open · {f} met een update', { n: hmNum(v.total), f: hmNum(v.fix) }), spark: hmSpark(hmVals(v.series), 'crit') });
  }
  const agents = state.hosts.filter((h) => h.mode === 'agent' && +h.enabled !== 0);
  if (agents.length) {
    const now = Date.now() / 1000;
    const stil = agents.filter((h) => !h.contact || !h.contact.seen || now - h.contact.seen > h.contact.stale).length;
    const old = agents.filter((h) => h.agent_version && state.agent_latest && verCmp(h.agent_version, state.agent_latest) < 0).length;
    tiles.push({ go: isAdmin() ? 'settings/agents' : 'dashboard', label: L('Agents'), st: stil ? 'warn' : 'ok', big: `${agents.length - stil}<small>/${agents.length}</small>`, unit: L('rapporteren'),
      sub: [stil ? L('{n} stil', { n: stil }) : L('allemaal actief'), old && L('{n} op een oudere versie', { n: old })].filter(Boolean).join(' · '), spark: '' });
  }

  const html = [];
  // 1.144.0: eerst één zin hoe het ervoor staat, dan wat je nu moet doen (incidenten en aandachtspunten op urgentie)
  const now = d.full && d.now ? d.now : todo.map((t) => ({ kind: 'todo', sev: t.sev, text: t.text, urgency: t.sev === 2 ? 50 : t.sev === 1 ? 25 : 5, why: [], go: t.go }));
  const nowOpen = now.filter((t) => t.sev >= 1);
  const urgentN = now.filter((t) => t.urgency >= 60).length;
  const incN = now.filter((t) => t.kind === 'inc').length;
  const probHosts = hmProblemHosts(d);
  if ($('#inc-badge') && d.full && d.now) {   // teller op het tabblad Incidenten: open incidenten (nog zonder eigenaar)
    const nOpen = d.now.filter((t) => t.kind === 'inc' && t.status === 'open').length;
    $('#inc-badge').hidden = !nOpen;
    $('#inc-badge').textContent = nOpen || '';
  }
  const enabledHosts = state.hosts.filter((h) => +h.enabled !== 0).length;
  const sentence = !nowOpen.length && !probHosts.length
    ? L('Alles in orde: {h} servers en {c} checks zonder problemen.', { h: enabledHosts, c: live.total })
    : [nowOpen.length ? (nowOpen.length === 1 ? L('1 ding om nu te doen') : L('{n} dingen om nu te doen', { n: nowOpen.length })) + (urgentN ? ' (' + L('{n} dringend', { n: urgentN }) + ')' : '') : '',
      incN ? (incN === 1 ? L('1 open incident') : L('{n} open incidenten', { n: incN })) : '',
      probHosts.length ? (probHosts.length === 1 ? L('1 server vraagt aandacht') : L('{n} servers vragen aandacht', { n: probHosts.length })) : ''].filter(Boolean).join(' · ') + '.';
  html.push(`<section class="hm-status ${scoreCls}" aria-label="${esc(L('Zo staat het ervoor'))}">
    <span class="hm-status-score" title="${esc(L('Totaalscore'))}">${score}</span>
    <div><div class="hm-status-txt">${esc(sentence)}</div>
      ${prevAvail !== null && Math.abs(prevAvail) >= 0.01 ? `<div class="hm-score-sub">${esc(L('Bereikbaarheid {d} t.o.v. de vorige periode', { d: (prevAvail > 0 ? '↑ ' : '↓ ') + dec(Math.abs(prevAvail).toFixed(2)) + '%' }))}</div>` : ''}</div>
  </section>`);
  html.push(hmNow(now, d.full));
  if (probHosts.length) html.push(hmServers(probHosts, L('Servers die aandacht vragen'), d));

  // De rest, compacter
  html.push(`<section class="hm-sum hm-sum-tiles" aria-label="${esc(L('Samenvatting'))}">
    ${tiles.map((t) => `<button type="button" class="hm-tile" data-hm-go="${t.go}">
      <span class="hm-tile-top"><span class="hm-tile-lbl">${esc(t.label)}</span><span class="hm-st ${t.st}">${hmShape(t.st)} ${esc(HM_ST[t.st]())}</span></span>
      <span class="hm-tile-val"><b>${t.big}</b> <span>${esc(t.unit)}</span></span>
      <span class="hm-tile-sub">${esc(t.sub)}</span>${t.spark}</button>`).join('')}
  </section>`);

  // 1.135.0: resourcegebruik van 24 uur en de recente incidenten (zoals het ontwerp)
  html.push(`<div class="hm-row">${hmResChart(d.resources)}${hmIncidents(d)}</div>`);

  // Netwerkkaart en de servers zonder problemen, compact
  html.push(`<div class="hm-row">${hmMap()}${hmAttacks()}</div>`);   // 1.149.0: met de aanvallen van vandaag
  html.push(hmServers(hmAllHosts().filter((x) => !probHosts.some((p) => p.h.id === x.h.id)), L('Overige servers'), d, true));

  // Grafieken
  if (d.full) {
    html.push(`<div class="hm-charts">${hmAvailChart(d)}${hmIdsChart(d)}${d.vulns ? hmVulnCard(d.vulns) : ''}</div>`);
  }
  html.push(`<div class="hm-row">${d.net ? hmNetCard(d.net) : ''}${hmTimeline(d.events)}</div>`);
  $('#home').innerHTML = html.join('');
  if ($('#hm-atk')) hmAtkWire($('#hm-atk'));
  $$('[data-hm-risk]', $('#home')).forEach((b) => b.addEventListener('click', (e) => { e.stopPropagation(); e.preventDefault(); exposureDialog(+b.dataset.hmRisk); }));
  $$('[data-hm-go]', $('#home')).forEach((b) => (b.onclick = () => {
    const go = b.dataset.hmGo;
    if (go.startsWith('check:')) checkInfo(go.slice(6));
    else if (go.startsWith('incident:')) { showTab('incidents'); caseDialog(+go.slice(9)); }
    else showTab(go);
  }));
}

// ---------------------------------------------------------------- 1.154.0: tweede dashboard "Command center"
// Per gebruiker te kiezen (accountmenu of de knop bovenaan), in te delen (kaarten verbergen en verslepen) en met een
// TV-modus voor een scherm aan de muur. Volgt het thema (licht of donker), net als de Live Attack Flow.
const dashMode = () => (isCC() ? 'cc' : 'classic');   // 1.158.0: volgt de lay-out (CC = Command center, anders klassiek)
const CC_PERIODS = [['today', () => L('Vandaag')], ['7d', () => L('7 dagen')], ['30d', () => L('30 dagen')], ['90d', () => L('90 dagen')]];
let ccPeriod = (() => { const p = uiGet('cc_period', 'rzmon-cc-period', 'today'); return CC_PERIODS.some(([k]) => k === p) ? p : 'today'; })();
const ccSeenAt = PREFS.dash_seen || '';   // het vorige bezoek (bij het laden van de pagina), voor "sinds je laatste bezoek"
let ccSeenSaved = false, ccEdit = false, ccAtk = null, ccAtkAt = 0, ccDrag = null;
const ccNowStr = () => { const d = new Date(), p = (n) => String(n).padStart(2, '0'); return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`; };

/** De kaarten: sleutel, breedte (van 12), titel en of hij er is (alleen-lezen ziet geen analyse, CVE's of netwerk) */
const CC_W = [
  ['overview', 12, () => L('Overzicht')], ['security', 12, () => L('Beveiliging in één oogopslag')], ['toppers', 12, () => L('De toppers')],
  ['now', 4, () => L('Nu doen')], ['attacks', 4, () => L('Live aanvallen')], ['logins', 4, () => L('Wie logt er in')],
  ['monitoring', 12, () => L('Monitoring')], ['servers', 12, () => L('Servers')],
  ['idschart', 4, () => L('IDS-gebeurtenissen')], ['avail', 4, () => L('Beschikbaarheid')], ['net', 4, () => L('Netwerk')],
  ['resources', 6, () => L('Resourcegebruik · 24 uur')], ['vulns', 6, () => L('Kwetsbaarheden (CVE)')], ['timeline', 12, () => L('Laatste gebeurtenissen')],
];
function ccLayout() {
  const l = PREFS.dash_layout || {}, keys = CC_W.map((w) => w[0]);
  const order = (l.order || []).filter((k) => keys.includes(k));
  keys.forEach((k) => { if (!order.includes(k)) order.splice(keys.indexOf(k), 0, k); });   // nieuwe kaarten op hun standaardplek
  return { order, hide: (l.hide || []).filter((k) => keys.includes(k)) };
}
const ccSaveLayout = (lay) => savePref('dash_layout', lay);

/** Verschil met de vorige periode: "↑ 38%" (rood als meer slecht is, groen als meer goed is) */
function ccDelta(n, prev, moreIsBad = true) {
  if (!prev && !n) return '';
  if (!prev) return `<span class="cc-d ${moreIsBad ? 'up-bad' : 'up-good'}">${esc(L('nieuw'))}</span>`;
  const p = Math.round((n - prev) / prev * 100);
  if (!p) return `<span class="cc-d">= </span>`;
  const bad = (p > 0) === moreIsBad;
  return `<span class="cc-d ${bad ? 'up-bad' : 'up-good'}">${p > 0 ? '↑' : '↓'} ${Math.abs(p)}%</span>`;
}
const ccPrevLbl = () => (ccPeriod === 'today' ? L('t.o.v. gisteren') : L('t.o.v. de periode ervoor'));
const ccTime = (at) => { const t = new Date(String(at).replace(' ', 'T')); return t.toDateString() === new Date().toDateString()
  ? t.toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit' }) : t.toLocaleDateString(LOCALE, { day: 'numeric', month: 'short' }) + ' ' + t.toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit' }); };
const ccCard = (key, inner, cls = '') => `<section class="cc-card ${cls}" aria-label="${esc((CC_W.find((w) => w[0] === key) || [0, 0, () => key])[2]())}">${inner}</section>`;
const ccHead = (title, right = '') => `<div class="cc-h"><span class="cc-hl">${esc(title)}</span>${right}</div>`;
const ccGo = (go, label) => `<button type="button" class="cc-link" data-hm-go="${esc(go)}">${esc(label)} →</button>`;

/** 1.157.2: live-lampje zoals op Monitoring: ● Live · laatste check … (lampje grijs als de live-verbinding wegvalt) */
function livePill() {
  return `<span class="live-pill" title="${esc(L('Live: wijzigingen komen binnen een paar seconden binnen'))}"><span class="live-dot${document.querySelector('#live-dot.off') ? ' off' : ''}"></span> <b>${L('Live')}</b>${state.last_run ? ' · ' + esc(L('laatste check')) + ' ' + agoSpan(state.last_run) : ''}</span>`;
}
/** Kop van het dashboard: begroeting, sinds je laatste bezoek, periode, live, indeling, TV-modus en de keuze van het dashboard */
function ccTools() {
  const tv = document.body.classList.contains('tv');
  return `<div class="cc-tools">
    ${dashMode() === 'cc' ? `<button type="button" class="cc-tbtn ${ccEdit ? 'on' : ''}" data-cc-edit aria-pressed="${ccEdit}">✎ ${esc(ccEdit ? L('Klaar') : L('Indeling'))}</button>
      <button type="button" class="cc-tbtn ${tv ? 'on' : ''}" data-cc-tv aria-pressed="${tv}">▣ ${esc(L('TV-modus'))}</button>` : ''}</div>`;   // 1.168.1: de lay-out kies je alleen nog in het accountmenu en bij Mijn account
}
function ccSetDash(v) {
  if (v === dashMode()) return;
  return setLayout(v === 'cc' ? 'cc' : 'blox');   // 1.158.0: het dashboard volgt de lay-out
}
const markDash = () => $$('[data-dash-set]').forEach((b) => b.classList.toggle('active', b.dataset.dashSet === dashMode()));
/** TV-modus: schermvullend, zonder menu en kopbalk, grotere letters. Per apparaat onthouden; Esc of de knop zet hem uit. */
function ccTv(on) {
  document.body.classList.toggle('tv', on);
  try { on ? localStorage.setItem('rzmon-tv', '1') : localStorage.removeItem('rzmon-tv'); } catch (e) { /* alleen voor nu */ }
  if (on && document.documentElement.requestFullscreen && !document.fullscreenElement) document.documentElement.requestFullscreen().catch(() => {});
  if (!on && document.fullscreenElement && document.exitFullscreen) document.exitFullscreen().catch(() => {});
  if ($('#cc-tvexit')) $('#cc-tvexit').hidden = !on;
}

function renderCC() {
  const d = hmData, c = d.cc;
  if (!c) return;
  const name = ($('.acct-name') || {}).textContent || '';
  const hr = new Date().getHours();
  const hi = hr < 6 ? L('Goedenacht') : hr < 12 ? L('Goedemorgen') : hr < 18 ? L('Goedemiddag') : L('Goedenavond');
  $('.hm-title').textContent = 'Command center';
  const s = c.seen;
  const seenTxt = s ? (s.crit || s.alerts || s.blocks || s.logins
    ? L('Sinds je laatste bezoek ({t})', { t: ccTime(s.at) }) + ': ' + [s.crit ? L('{n} nieuwe kritieke meldingen', { n: s.crit }) : '', s.alerts ? L('{n} meldingen', { n: s.alerts }) : '',
      s.blocks ? L('{n} blokkades', { n: s.blocks }) : '', s.logins ? L('{n} SSH-logins', { n: s.logins }) : ''].filter(Boolean).join(' · ')
    : L('Niets nieuws sinds je laatste bezoek ({t})', { t: ccTime(s.at) })) : '';
  $('#hm-sub').innerHTML = `<b>${esc(hi)}${name && !/lokaal|local/i.test(name) ? ', ' + esc(name.trim()) : ''}</b>${seenTxt ? ' · ' + (s && s.crit ? `<span class="crit-txt">${esc(seenTxt)}</span>` : esc(seenTxt)) : ''}
    · <span class="muted">${esc(L('bijgewerkt {t}', { t: new Date(hmAt).toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit', second: '2-digit' }) }))}</span>`;
  if (!ccSeenSaved && !prefsLocal) { ccSeenSaved = true; setTimeout(() => savePref('dash_seen', ccNowStr()), 4000); }
  if (!ccSeenSaved && prefsLocal) { ccSeenSaved = true; savePref('dash_seen', ccNowStr()); }
  const lay = ccLayout(), m = afMotion({ live: { motion: c.motion ?? 2 } });
  const R = { overview: ccOverview, security: ccSecurity, toppers: ccToppers, now: ccNow, attacks: ccAttacks, logins: ccLogins, monitoring: ccMonitoring, servers: ccServers,
    idschart: () => (d.full ? hmIdsChart(d) : ''), avail: () => (d.full ? hmAvailChart(d) : ''), net: () => (d.net ? hmNetCard(d.net) : ''), resources: () => hmResChart(d.resources),
    vulns: () => (d.vulns ? hmVulnCard(d.vulns) : ''), timeline: () => hmTimeline(d.events) };
  const html = [];
  lay.order.forEach((k) => {
    const w = CC_W.find((x) => x[0] === k), hidden = lay.hide.includes(k);
    if (hidden && !ccEdit) return;
    let inner = '';
    try { inner = R[k](d, c); } catch (ex) { inner = `<p class="form-error">${esc(ex.message)}</p>`; }
    if (!inner) return;
    html.push(`<div class="cc-w s${w[1]} ${hidden ? 'cc-hidden' : ''}" data-ccw="${k}" ${ccEdit ? 'draggable="true"' : ''}>
      ${ccEdit ? `<div class="cc-edit"><span class="cc-grip" aria-hidden="true">⠿</span><b>${esc(w[2]())}</b>
        <button type="button" data-cc-move="-1" aria-label="${esc(L('Omhoog'))}">↑</button><button type="button" data-cc-move="1" aria-label="${esc(L('Omlaag'))}">↓</button>
        <button type="button" data-cc-hide>${hidden ? '👁 ' + esc(L('Tonen')) : '⦸ ' + esc(L('Verbergen'))}</button></div>` : ''}${inner}</div>`);
  });
  $('#home').innerHTML = `<div class="cc m${m} ${ccEdit ? 'editing' : ''}">
    ${ccEdit ? `<div class="cc-editbar">${esc(L('Sleep de kaarten of gebruik ↑ ↓ om de volgorde te kiezen; verberg wat je niet nodig hebt. Dit geldt voor jouw account.'))}
      <button type="button" class="btn small-btn" data-cc-reset>${esc(L('Standaardindeling'))}</button><button type="button" class="btn small-btn primary" data-cc-edit>${esc(L('Klaar'))}</button></div>` : ''}
    <div class="cc-grid">${html.join('')}</div></div>`;
  ccWire();
  if (lay.order.includes('attacks') && !lay.hide.includes('attacks')) ccAtkLoad();
}

function ccWire() {
  const box = $('#home');
  $$('[data-hm-go]', box).forEach((b) => (b.onclick = (e) => {
    e.stopPropagation();
    const go = b.dataset.hmGo;
    if (go.startsWith('check:')) checkInfo(go.slice(6));
    else if (go.startsWith('incident:')) { showTab('incidents'); caseDialog(+go.slice(9)); }
    else if (go.startsWith('ip:')) amDetail(go.slice(3));
    else if (go.startsWith('block:')) blockDialog(go.slice(6));
    else showTab(go);
  }));
  $$('[data-hm-risk]', box).forEach((b) => b.addEventListener('click', (e) => { e.stopPropagation(); e.preventDefault(); exposureDialog(+b.dataset.hmRisk); }));
  if (!box.dataset.ccWired) {   // de knopen en lijnen in "Live aanvallen" (die kaart wordt los bijgewerkt)
    box.dataset.ccWired = '1';
    box.addEventListener('click', (e) => { const t = e.target.closest('[data-cc-ip]'); if (t && dashMode() === 'cc') amDetail(t.getAttribute('data-cc-ip')); });
  }
  if (!ccEdit) return;
  const lay = ccLayout();
  const save = () => { ccSaveLayout(lay); renderCC(); };
  $$('.cc-w', box).forEach((w) => {
    const k = w.dataset.ccw;
    $$('[data-cc-move]', w).forEach((b) => (b.onclick = () => { const i = lay.order.indexOf(k), j = i + +b.dataset.ccMove; if (j < 0 || j >= lay.order.length) return; lay.order.splice(i, 1); lay.order.splice(j, 0, k); save(); }));
    $('[data-cc-hide]', w).onclick = () => { lay.hide = lay.hide.includes(k) ? lay.hide.filter((x) => x !== k) : [...lay.hide, k]; save(); };
    w.addEventListener('dragstart', (e) => { ccDrag = k; w.classList.add('dragging'); e.dataTransfer.effectAllowed = 'move'; try { e.dataTransfer.setData('text/plain', k); } catch (ex) { /* oude browsers */ } });
    w.addEventListener('dragend', () => { ccDrag = null; w.classList.remove('dragging'); $$('.cc-w.over', box).forEach((x) => x.classList.remove('over')); });
    w.addEventListener('dragover', (e) => { if (ccDrag && ccDrag !== k) { e.preventDefault(); w.classList.add('over'); } });
    w.addEventListener('dragleave', () => w.classList.remove('over'));
    w.addEventListener('drop', (e) => {
      e.preventDefault();
      if (!ccDrag || ccDrag === k) return;
      lay.order.splice(lay.order.indexOf(ccDrag), 1);
      lay.order.splice(lay.order.indexOf(k), 0, ccDrag);
      save();
    });
  });
}

/** Score en de vijf domeinen */
function ccOverview(d, c) {
  const live = hmLive(), hl = state.health || {};
  const score = d.full ? d.score : (hl.score ?? 100), cls = score >= 90 ? 'ok' : score >= 60 ? 'warn' : 'crit';
  const down = (hl.hosts_total || 0) - (hl.hosts_up || 0);
  const agents = state.hosts.filter((h) => h.mode === 'agent' && +h.enabled !== 0);
  const nowS = Date.now() / 1000;
  const stil = agents.filter((h) => !h.contact || !h.contact.seen || nowS - h.contact.seen > h.contact.stale).length;
  const old = agents.filter((h) => h.agent_version && state.agent_latest && verCmp(h.agent_version, state.agent_latest) < 0).length;
  const probs = live.n[1] + live.n[2];
  const atk = c.sec.ssh_fail.n + c.sec.web.n;
  const tiles = [
    ['dashboard', L('Monitoring'), `${hmNum(hl.hosts_up || 0)}<small>/${hmNum(hl.hosts_total || 0)}</small>`, down ? L('{n} onbereikbaar', { n: down }) : L('alles bereikbaar'), down ? 'crit' : 'ok', d.full ? hmSpark(hmVals(d.avail.series), 's1') : ''],
    ['alerts', L('Meldingen'), hmNum(probs), probs ? [live.n[2] && L('{n} storing', { n: live.n[2] }), live.n[1] && L('{n} aandacht', { n: live.n[1] })].filter(Boolean).join(' · ') : L('{n} checks OK', { n: live.total }), live.n[2] ? 'crit' : live.n[1] ? 'warn' : 'ok', ''],
    ['ids/inc', L('IDS'), hmNum(c.sec.ids_inc.n), [L('nieuwe incidenten'), c.sec.ids_inc.crit ? L('{n} kritiek', { n: c.sec.ids_inc.crit }) : '', atk ? L('{n} pogingen', { n: hmNum(atk) }) : ''].filter(Boolean).join(' · '), c.sec.ids_inc.crit ? 'crit' : c.sec.ids_inc.n ? 'warn' : 'ok', d.full ? hmSpark(hmVals(d.ids.series.blk), 's2') : ''],
  ];
  if (d.vulns) tiles.push(['vulns', L('Kwetsbaarheden'), hmNum(d.vulns.sev[4]), L('kritiek') + ' · ' + (d.vulns.kev ? L('{n} in KEV', { n: d.vulns.kev }) : L('geen in KEV')) + ' · ' + L('{n} hoog', { n: d.vulns.sev[3] || 0 }), d.vulns.sev[4] ? 'crit' : d.vulns.sev[3] ? 'warn' : 'ok', hmSpark(hmVals(d.vulns.series), 'crit')]);
  if (agents.length) tiles.push([isAdmin() ? 'settings/agents' : 'dashboard', L('Agents'), `${agents.length - stil}<small>/${agents.length}</small>`, [stil ? L('{n} stil', { n: stil }) : L('allemaal actief'), old ? L('{n} op een oudere versie', { n: old }) : ''].filter(Boolean).join(' · '), stil ? 'warn' : 'ok', '']);
  const r = 50, C = 2 * Math.PI * r, f = Math.max(0, Math.min(100, score)) / 100;
  const why = d.full && d.now && d.now[0] ? d.now[0].text : '';
  return `<div class="cc-ov">
    <div class="cc-card cc-score ${cls}"><svg width="124" height="124" viewBox="0 0 124 124" aria-hidden="true"><circle cx="62" cy="62" r="${r}" class="cc-ring-bg"/>
        <circle cx="62" cy="62" r="${r}" class="cc-ring" stroke-dasharray="${(C * f).toFixed(1)} ${C.toFixed(1)}" transform="rotate(-90 62 62)"/><circle cx="62" cy="62" r="38" class="cc-ring-spin"/>
        <text x="62" y="68" text-anchor="middle" class="cc-ring-n">${score}</text><text x="62" y="86" text-anchor="middle" class="cc-ring-s">${esc(L('van 100'))}</text></svg>
      <div><span class="cc-hl ${cls}">${esc(cls === 'ok' ? L('Alles in orde') : cls === 'warn' ? L('Aandacht nodig') : L('Actie nodig'))}</span>
        <div class="cc-score-t">${esc(live.n[2] ? L('{n} checks in storing', { n: live.n[2] }) : L('{n} checks OK', { n: live.total }))}${c.sec.ids_inc.crit ? ' · ' + esc(L('{n} kritiek', { n: c.sec.ids_inc.crit })) : ''}</div>
        ${why ? `<div class="cc-mu small">${esc(L('Eerst: {x}', { x: why }))}</div>` : ''}</div></div>
    ${tiles.map(([go, l, big, sub, st, sp]) => `<button type="button" class="cc-card cc-tile ${st}" data-hm-go="${esc(go)}"><span class="cc-hl">${esc(l)}</span><b class="cc-big">${big}</b>
      <span class="cc-mu small">${esc(sub)}</span>${sp}<span class="cc-st ${st}">${hmShape(st === 'crit' ? 'crit' : st, 8)} ${esc(HM_ST[st === 'crit' ? 'crit' : st]())}</span></button>`).join('')}</div>`;
}

/** Acht getallen over de beveiliging, elk klikbaar */
function ccSecurity(d, c) {
  const s = c.sec;
  const n = (go, lbl, val, sub, cls, delta) => `<button type="button" class="cc-num ${cls}" data-hm-go="${esc(go)}"><span class="cc-mu small">${esc(lbl)}</span><b>${hmNum(val)}</b>
    <span class="small">${delta}${sub ? ` <span class="cc-mu">${esc(sub)}</span>` : ''}</span></button>`;
  return ccCard('security', `${ccHead(L('Beveiliging in één oogopslag') + ' · ' + CC_PERIODS.find(([k]) => k === ccPeriod)[1](), `<span class="cc-mu small">${esc(ccPrevLbl())} · ${esc(L('klik op een getal voor de lijst'))}</span>`)}
    <div class="cc-nums">
      ${n('ids/acc?type=ssh&result=ok', L('SSH-logins'), s.ssh_login.n, [L('{n} gebruikers', { n: s.ssh_login.users }), s.ssh_login.new_ips ? L('{n} nieuw IP', { n: s.ssh_login.new_ips }) : ''].filter(Boolean).join(' · '), s.ssh_login.new_ips ? 'warn' : 'ok', ccDelta(s.ssh_login.n, s.ssh_login.prev, false))}
      ${n('ids/acc?type=ssh&result=fail', L('Mislukte SSH-logins'), s.ssh_fail.n, L('{n} IP-adressen', { n: s.ssh_fail.ips }), s.ssh_fail.n ? 'crit' : '', ccDelta(s.ssh_fail.n, s.ssh_fail.prev))}
      ${n('ids/blk', L('SSH-blokkades'), s.ssh_blk.n, L('{n} nog actief', { n: s.ssh_blk.active }), '', ccDelta(s.ssh_blk.n, s.ssh_blk.prev, false))}
      ${n('ids/blk', L('IDS-blokkades'), s.ids_blk.n, L('{n} actief op {h} servers', { n: s.ids_blk.active, h: s.ids_blk.hosts }), '', ccDelta(s.ids_blk.n, s.ids_blk.prev, false))}
      ${n('ids/blk', L('Tegengehouden'), s.stopped, L('pogingen door blokkades'), 'cy', '')}
      ${n('ids/acc?type=sudo', L('sudo en su'), s.sudo.n, [L('{n} gebruikers', { n: s.sudo.users }), s.sudo.fail ? L('{n} mislukt', { n: s.sudo.fail }) : L('niets mislukt')].join(' · '), s.sudo.fail ? 'warn' : '', ccDelta(s.sudo.n, s.sudo.prev))}
      ${n('ids/map', L('Webaanvallen'), s.web.n, L('{n} IP-adressen', { n: s.web.ips }), s.web.n ? 'warn' : '', ccDelta(s.web.n, s.web.prev))}
      ${n('ids/map', L('Verdacht uitgaand'), s.out.n, s.out.last ? s.out.last.slice(0, 40) : L('niets gezien'), s.out.n ? 'out' : '', ccDelta(s.out.n, s.out.prev))}
    </div>`);
}

/** De toppers: grootste SSH- en IDS-blokkade, grootste aanvaller, meest aangevallen server en land */
function ccToppers(d, c) {
  const t = c.top;
  const ip = (x) => `<button type="button" class="cc-ip" data-hm-go="ip:${esc(x.ip)}">${afCcBadge(x.cc, x.cc === 'LAN')}<span class="mono">${esc(x.ip)}</span></button>`;
  const blk = (x, title) => (x ? `<div class="cc-card cc-top crit">${ccHead(title)}${ip(x)}
      <span class="cc-mu small">${esc(L('{n} pogingen tegengehouden', { n: hmNum(x.hits) }))}${x.users.length ? ' · ' + esc(x.users.join(', ')) : x.reason ? ' · ' + esc(x.reason) : ''}</span>
      <span class="small"><span class="cc-ok">⛔ ${esc(L('geblokkeerd op {list} sinds {t}', { list: x.on.join(', '), t: ccTime(x.at) }))}</span>${x.not_on.length ? ` · <span class="cc-wa">${esc(L('nog niet op {list}', { list: x.not_on.join(', ') }))}</span>` : ''}</span>
      ${x.not_on.length && isAdmin() ? `<button type="button" class="cc-link" data-hm-go="block:${esc(x.ip)}">${esc(L('Overal blokkeren'))} →</button>` : ''}</div>`
    : `<div class="cc-card cc-top">${ccHead(title)}<span class="cc-mu small">${esc(L('Geen actieve blokkade'))}</span></div>`);
  const a = t.attacker, h = t.host, cs = t.countries || [];
  return `<div class="cc-tops">
    ${blk(t.ssh_block, L('Top SSH-blokkade'))}${blk(t.ids_block, L('Top IDS-blokkade'))}
    ${a ? `<div class="cc-card cc-top ${a.blocked ? '' : 'warn'}">${ccHead(L('Grootste aanvaller'))}${ip(a)}<span class="cc-mu small">${esc(a.title)}</span>
      <span class="small">${a.blocked ? `<span class="cc-ok">⛔ ${esc(L('geblokkeerd'))}</span>` : `<span class="cc-wa">● ${esc(L('nog niet geblokkeerd'))}</span>`} · ${esc(L('{n} pogingen', { n: hmNum(a.hits) }))}${a.hosts > 1 ? ' · ' + esc(L('{n} servers', { n: a.hosts })) : ''}</span>
      ${!a.blocked && isAdmin() && a.cc !== 'LAN' ? `<button type="button" class="cc-link" data-hm-go="block:${esc(a.ip)}">${esc(L('Blokkeren'))} →</button>` : ''}</div>`
      : `<div class="cc-card cc-top">${ccHead(L('Grootste aanvaller'))}<span class="cc-mu small">${esc(L('Geen aanvallen in deze periode.'))}</span></div>`}
    ${h ? `<button type="button" class="cc-card cc-top" data-hm-go="ids/map">${ccHead(L('Meest aangevallen'))}<b class="cc-name">${esc(h.name)}</b>
      <span class="cc-mu small">${esc(L('{n} pogingen · {i} bronnen', { n: hmNum(h.hits), i: h.ips }))}${h.svc.length ? ' · ' + esc(h.svc.slice(0, 3).join(', ')) : ''}</span>
      <span class="small">${h.blocks ? `<span class="cc-ok">${esc(L('{n} blokkades actief', { n: h.blocks }))}</span>` : `<span class="cc-wa">${esc(L('geen blokkades'))}</span>`}</span></button>`
      : `<div class="cc-card cc-top">${ccHead(L('Meest aangevallen'))}<span class="cc-mu small">–</span></div>`}
    <div class="cc-card cc-top">${ccHead(L('Top land'))}${cs.length ? `<b class="cc-name">${afCcBadge(cs[0].cc, cs[0].cc === 'LAN')} ${esc(amCcName(cs[0].cc))}</b>
      <span class="cc-mu small">${esc(L('{p}% van alle pogingen · {n} IP-adressen', { p: cs[0].pct, n: cs[0].ips }))}</span>
      <span class="cc-chips">${cs.slice(1).map((x) => `<span class="cc-chip">${esc(x.cc === 'LAN' ? L('eigen netwerk') : x.cc)} ${x.pct}%</span>`).join('')}</span>` : `<span class="cc-mu small">–</span>`}</div>
  </div>`;
}

/** Nu doen: dezelfde lijst als op het klassieke dashboard, compacter */
function ccNow(d) {
  const live = hmLive();
  const list = d.full && d.now ? d.now : live.checks.filter((c) => +c.status === 2 || +c.status === 1).sort((a, b) => b.status - a.status)
    .map((c) => ({ kind: 'todo', sev: +c.status === 2 ? 2 : 1, text: `${c.name} – ${(state.hosts.find((h) => +h.id === +c.host_id) || {}).name || ''}`, urgency: +c.status === 2 ? 50 : 25, why: [], go: 'check:' + c.id }));
  const shown = list.slice(0, 6);
  return ccCard('now', `${ccHead(L('Nu doen'), `<span class="cc-mu small">${esc(L('{n} open', { n: list.length }))}</span>`)}
    ${shown.length ? `<ul class="cc-list">${shown.map((t) => `<li><button type="button" class="cc-row" data-hm-go="${esc(t.go)}"><i class="cc-bar ${t.urgency >= 60 ? 'crit' : t.urgency >= 30 ? 'warn' : 'cy'}"></i>
      <span><b>${t.kind === 'inc' ? '⚠ ' : t.icon ? esc(t.icon) + ' ' : ''}${esc(t.text)}</b><small class="cc-mu">${esc((t.why || []).slice(1, 3).join(' · '))}${t.owner ? ' · 👤 ' + esc(t.owner) : ''}</small></span>${urgPill(t.urgency, t.why)}</button></li>`).join('')}</ul>`
      : `<p class="cc-mu">${esc(L('Niets te doen. Mooi zo.'))}</p>`}
    ${d.full ? ccGo('analytics', L('Alles bekijken')) : ''}`);
}

/** Wie logt er in: SSH, console, sudo en su */
function ccLogins(d, c) {
  const ic = { ssh: '🔑', console: '🖥️', sudo: '⚡', su: '⇄' };
  const meth = { publickey: L('sleutel'), password: L('wachtwoord'), 'keyboard-interactive/pam': L('wachtwoord') };
  return ccCard('logins', `${ccHead(L('Wie logt er in'), ccGo('ids/acc', L('Toegang')))}
    ${c.logins.length ? `<ul class="cc-list">${c.logins.map((x) => `<li class="cc-lg"><span class="mono cc-mu">${esc(ccTime(x.at).slice(-5))}</span>
      <span><b>${esc(x.user)}</b> ${x.type === 'ssh' || x.type === 'console' ? '→' : ''} ${esc(x.type === 'sudo' || x.type === 'su' ? L('{t} op {host}', { t: x.type + (x.as && x.as !== 'root' ? ' ' + x.as : '') + (x.cmd ? ' ' + x.cmd : ''), host: x.host }) : x.host)}
        <small class="cc-mu">${[x.type === 'ssh' ? 'SSH' : x.type === 'console' ? L('console') : '', meth[x.m] || x.m, x.ip, x.cc && x.cc !== 'LAN' ? x.cc : ''].filter(Boolean).map(esc).join(' · ')}</small></span>
      <span class="cc-tag ${x.new ? 'warn' : x.type === 'sudo' || x.type === 'su' ? '' : 'ok'}">${x.new ? esc(L('nieuw IP')) : ic[x.type] || ''}</span></li>`).join('')}</ul>`
      : `<p class="cc-mu">${esc(L('Nog niemand ingelogd in deze periode.'))}</p>`}`);
}

/** Live aanvallen: een kleine Attack Flow van de laatste 15 minuten (eigen gegevens, hooguit eens per 20 seconden) */
async function ccAtkLoad() {
  if (Date.now() - ccAtkAt < 20000 && ccAtk) return ccAtkPaint();
  ccAtkAt = Date.now();
  try { ccAtk = await api('ids_attack_flow', null, { days: 1, mins: 15, top: 6 }); } catch (ex) { ccAtk = { error: ex.message }; }
  ccAtkPaint();
}
function ccAttacks() {
  return ccCard('attacks', `${ccHead(L('Live aanvallen · laatste 15 min'), ccGo('ids/map', 'Attack Flow'))}<div id="cc-atk">${ccAtk ? ccAtkSvg(ccAtk) : `<p class="cc-mu">${esc(L('Laden…'))}</p>`}</div>`, 'cc-atkcard');
}
function ccAtkPaint() { const el = $('#cc-atk'); if (el && ccAtk) el.innerHTML = ccAtkSvg(ccAtk); }
function ccAtkSvg(a) {
  if (a.error) return `<p class="form-error">${esc(a.error)}</p>`;
  const lv = a.live || {}, lines = (a.lines || []).slice(0, 6);
  if (!lines.length) return `<div class="cc-calm">${amSvg('shield', 'am-ic big cc-okc')}<span>${esc(L('Rustig: geen aanvallen in de laatste 15 minuten.'))}</span></div>`;
  const srcs = [...new Set(lines.map((l) => l.ip))].slice(0, 5), tgts = [...new Set(lines.map((l) => l.host_id))].slice(0, 4);
  const W = 340, rowS = 40, H = Math.max(srcs.length, tgts.length) * rowS + 8;
  const ys = (i, n) => (H - n * rowS) / 2 + i * rowS + rowS / 2;
  const names = Object.fromEntries((a.targets || []).map((t) => [t.id, t.name]));
  const now = performance.now() / 1000, hit = new Set(lv.hit || []);
  const parts = [`<defs><filter id="ccGlow" x="-20%" y="-60%" width="140%" height="220%"><feGaussianBlur stdDeviation="2.2" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>`];
  lines.forEach((l, idx) => {
    const si = srcs.indexOf(l.ip), ti = tgts.indexOf(l.host_id);
    if (si < 0 || ti < 0) return;
    const y1 = ys(si, srcs.length), y2 = ys(ti, tgts.length), x1 = 118, x2 = 232, xs = 212, mid = (x1 + x2) / 2;
    const cls = l.dir === 'o' ? 'out' : l.sev >= 2 ? 'crit' : 'warn';
    const blocked = (l.outcome || {}).k === 'blocked' && l.dir !== 'o';
    const curve = `M${x1} ${y1.toFixed(1)} C${mid} ${y1.toFixed(1)} ${mid} ${y2.toFixed(1)} ${xs} ${y2.toFixed(1)}`;
    const ll = (lv.lines || [])[a.lines.indexOf(l)] || {};
    const rate = +ll.rate || 0, dur = rate >= 6 ? 0.5 : rate >= 2 ? 0.85 : rate > 0 ? 1.4 : 2.6;
    parts.push(`<g class="af-l ${cls}"><path class="af-base" d="${curve} H${x2}" stroke-width="6"/>${l.obs && ll.recent
      ? `<path class="af-p" d="${l.dir === 'o' ? `M${x2} ${y2.toFixed(1)} H${xs} C${mid} ${y2.toFixed(1)} ${mid} ${y1.toFixed(1)} ${x1} ${y1.toFixed(1)}` : blocked ? curve : curve + ' H' + x2}" stroke-width="4" style="animation-duration:${dur}s;animation-delay:-${(now % dur).toFixed(2)}s"/>`
      : `<path class="af-core${l.obs ? '' : ' inf'}" d="${curve} H${x2}" stroke-width="2"/>`}
      ${blocked ? `<g class="af-shield" transform="translate(${xs + 12} ${y2.toFixed(1)})"><circle class="af-bu" r="6"/><circle class="af-sh" r="8"/><path d="M-3 -3 l6 6 M3 -3 l-6 6"/></g>` : ''}
      <path class="am-hit" d="${curve} H${x2}" data-cc-ip="${esc(l.ip)}"><title>${esc(`${l.ip} → ${names[l.host_id] || '?'} · ${amSvc(l)} · ${amN(l.hits)}×`)}</title></path></g>`);
    void idx;
  });
  srcs.forEach((ip, i) => {
    const s = (a.sources || []).find((x) => x.ip === ip) || { ip, cc: '??' }, y = ys(i, srcs.length);
    parts.push(`<g class="cc-fn" data-cc-ip="${esc(ip)}"><rect x="1" y="${(y - 15).toFixed(1)}" width="117" height="30" rx="8"/><text x="8" y="${(y + 3.5).toFixed(1)}" class="cc-fn-cc">${esc(s.internal ? 'LAN' : s.cc)}</text>
      <text x="32" y="${(y + 3.5).toFixed(1)}" class="cc-fn-ip">${esc(ip)}</text></g>`);
  });
  tgts.forEach((id, i) => {
    const y = ys(i, tgts.length);
    parts.push(`<g class="cc-fn r ${hit.has(+id) ? 'hit' : ''}"><rect x="232" y="${(y - 15).toFixed(1)}" width="107" height="30" rx="8"/><text x="240" y="${(y + 3.5).toFixed(1)}" class="cc-fn-h">${esc((names[id] || '?').slice(0, 14))}</text></g>`);
  });
  const b = lv.busy || {};
  return `<svg class="cc-atk-svg" viewBox="0 0 ${W} ${H}" aria-hidden="true">${parts.join('')}</svg>
    <div class="cc-mu small cc-atk-sum"><span><b>${hmNum(b.active || 0)}</b> ${esc(L('aanvallers actief'))}</span><span><b>${esc(dec(b.per_min || 0))}</b> ${esc(L('pogingen/min'))}</span>
      ${(lv.hit || []).length ? `<span class="cc-cr">${esc(L('{n} server(s) nu geraakt', { n: lv.hit.length }))}</span>` : ''}</div>`;
}

/** Monitoring: hoeveel checks, hoe vaak ze liepen, wat het vaakst fout ging en de meeste meldingen gaf */
function ccMonitoring(d, c) {
  const m = c.mon;
  const series = m.series || [], mx = Math.max(1, ...series.map((x) => x.n)), mf = Math.max(1, ...series.map((x) => x.f));
  const W = 460, H = 120, bw = series.length ? Math.max(2, W / series.length - 3) : 0;
  const chart = series.length > 1 ? `<svg class="cc-mchart" viewBox="0 0 ${W} ${H + 16}" preserveAspectRatio="none" role="img" aria-label="${esc(L('Checks per {p}: uitgevoerd en fout', { p: ccPeriod === 'today' ? L('uur') : L('dag') }))}">
      ${series.map((x, i) => `<rect class="cc-mb" x="${(i * W / series.length).toFixed(1)}" y="${(H - x.n / mx * (H - 10)).toFixed(1)}" width="${bw.toFixed(1)}" height="${(x.n / mx * (H - 10)).toFixed(1)}" rx="2"><title>${esc(x.k)}: ${esc(L('{n} uitgevoerd, {f} fout', { n: hmNum(x.n), f: hmNum(x.f) }))}</title></rect>`).join('')}
      <path class="cc-mf" d="${series.map((x, i) => `${i ? 'L' : 'M'}${(i * W / series.length + bw / 2).toFixed(1)} ${(H - x.f / mf * (H - 14) - 2).toFixed(1)}`).join('')}"/>
      <text x="0" y="${H + 13}" class="cc-axt">${esc(series[0].k.slice(ccPeriod === 'today' ? 11 : 5))}</text><text x="${W}" y="${H + 13}" text-anchor="end" class="cc-axt">${esc(series[series.length - 1].k.slice(ccPeriod === 'today' ? 11 : 5))}</text></svg>
      <div class="cc-mu small cc-leg"><span><i class="sw cc-sw-n"></i>${esc(L('uitgevoerd'))}</span><span><i class="sw cc-sw-f"></i>${esc(L('fout (warning of critical)'))}</span></div>`
    : `<p class="cc-mu small">${esc(L('Nog geen uurtotalen in deze periode; die komen elk uur bij.'))}</p>`;
  const row = (x, val, sub, cls) => `<li><button type="button" class="cc-row" data-hm-go="check:${x.id}"><span><b>${esc(x.name)}</b><small class="cc-mu">${esc(x.host)}${sub ? ' · ' + esc(sub) : ''}</small></span>
    <span class="cc-val ${cls}">${val}</span></button></li>`;
  const mr = m.most_run;
  return ccCard('monitoring', `${ccHead(L('Monitoring') + ' · ' + CC_PERIODS.find(([k]) => k === ccPeriod)[1](), `<span class="cc-mu small">${esc(ccPrevLbl())}</span>`)}
    <div class="cc-mon">
      <div class="cc-nums cc-nums-5">
        <button type="button" class="cc-num" data-hm-go="settings/allchecks"><span class="cc-mu small">${esc(L('Actieve checks'))}</span><b>${hmNum(m.active)}</b>
          <span class="small cc-mu">${esc(m.types.slice(0, 3).map((t) => `${t.n} ${t.type}`).join(' · '))}</span></button>
        <div class="cc-num"><span class="cc-mu small">${esc(L('Uitgevoerd'))}</span><b>${hmNum(m.runs.n)}</b><span class="small">${ccDelta(m.runs.n, m.runs.prev, false)} <span class="cc-mu">${esc(L('{n} checks liepen', { n: m.checks_ran }))}</span></span></div>
        <div class="cc-num ${m.fails.n ? 'warn' : 'ok'}"><span class="cc-mu small">${esc(L('Fout gegaan'))}</span><b>${hmNum(m.fails.n)}</b><span class="small">${ccDelta(m.fails.n, m.fails.prev)} <span class="cc-mu">${esc(L('warning of critical'))}</span></span></div>
        <div class="cc-num ${m.ok_pct !== null && m.ok_pct < 95 ? 'warn' : 'ok'}"><span class="cc-mu small">${esc(L('Gelukt'))}</span><b>${m.ok_pct === null ? '–' : esc(dec(m.ok_pct)) + '<small>%</small>'}</b><span class="small cc-mu">${esc(L('van alle uitvoeringen'))}</span></div>
        <button type="button" class="cc-num ${m.alerts.n ? 'warn' : ''}" data-hm-go="alerts"><span class="cc-mu small">${esc(L('Meldingen verstuurd'))}</span><b>${hmNum(m.alerts.n)}</b><span class="small">${ccDelta(m.alerts.n, m.alerts.prev)} <span class="cc-mu">${esc(L('naar je kanalen'))}</span></span></button>
      </div>
      <div class="cc-mgrid">
        <div>${chart}${mr ? `<p class="small cc-mu" style="margin:.4rem 0 0">${esc(L('Vaakst uitgevoerd'))}: <button type="button" class="cc-link" data-hm-go="check:${mr.id}">${esc(mr.name)} · ${esc(mr.host)}</button> (${esc(L('{n}×', { n: hmNum(mr.n) }))})</p>` : ''}</div>
        <div><span class="cc-sub">${esc(L('Vaakst fout gegaan'))}</span>${m.most_failed.length ? `<ul class="cc-list">${m.most_failed.map((x) => row(x, `${hmNum(x.fail)}<small>×</small>`, L('{p}% van {n} keer', { p: dec(x.pct), n: hmNum(x.n) }) + (x.crit ? ' · ' + L('{n} critical', { n: hmNum(x.crit) }) : ''), x.crit ? 'crit' : 'warn')).join('')}</ul>` : `<p class="cc-mu small">${esc(L('Niets fout gegaan.'))}</p>`}</div>
        <div><span class="cc-sub">${esc(L('Meeste meldingen'))}</span>${m.fired.length ? `<ul class="cc-list">${m.fired.map((x) => row(x, `${hmNum(x.n)}<small>×</small>`, (x.crit ? L('{n} critical', { n: x.crit }) + ' · ' : '') + L('laatste {t}', { t: ccTime(x.last) }), x.crit ? 'crit' : 'warn')).join('')}</ul>` : `<p class="cc-mu small">${esc(L('Geen meldingen verstuurd.'))}</p>`}</div>
      </div></div>`);
}

/** Servers als tegels met drie ringen (CPU, RAM, de volste disk); de rand gloeit in de kleur van de status */
function ccServers(d) {
  const risk = (d && d.risk) || {}, rank = { crit: 0, warn: 1, unk: 2, ok: 3 };
  const all = hmAllHosts().sort((a, b) => rank[a.st] - rank[b.st] || a.h.name.localeCompare(b.h.name));
  if (!all.length) return '';
  const ring = (v, lbl, x) => {
    const r = 17, C = 2 * Math.PI * r, f = v === null ? 0 : Math.min(100, v) / 100, cls = v === null ? 'na' : v >= 90 ? 'crit' : v >= 75 ? 'warn' : 'ok';
    return `<g transform="translate(${x} 24)"><circle r="${r}" class="cc-ring-bg"/>${v === null ? '' : `<circle r="${r}" class="cc-sring ${cls}" stroke-dasharray="${(C * f).toFixed(1)} ${C.toFixed(1)}" transform="rotate(-90)"/>`}
      <text y="4" text-anchor="middle" class="cc-sring-n">${v === null ? '–' : v}</text><text y="33" text-anchor="middle" class="cc-sring-l">${esc(lbl)}</text></g>`;
  };
  const why = (h) => { const p = h.checks.filter((c) => +c.enabled && !c.maintenance && +c.status >= 1 && +c.status <= 2).sort((a, b) => b.status - a.status); return p.length ? (p.length > 1 ? L('{n} problemen', { n: p.length }) : p[0].name) : ''; };
  return ccCard('servers', `${ccHead(L('Servers'), `<span class="cc-mu small">${esc(L('ringen = CPU · RAM · disk · de rand = status · klik voor de server'))}</span>`)}
    <div class="cc-srv">${all.map(({ h, st, cpu, ram, disk }) => `<button type="button" class="cc-s ${st}" data-hm-go="dashboard?server=${encodeURIComponent(h.name)}">
      <span class="cc-s-top"><b>${esc(h.name)}</b>${risk[h.id] && risk[h.id].score >= 40 ? urgPill(risk[h.id].score, risk[h.id].reasons, true) : ''}</span>
      <span class="cc-mu small">${esc(kindLabel(hostKind(h)))} · ${esc(st === 'ok' ? HM_ST.ok() : why(h) || HM_ST[st]())}</span>
      ${cpu === null && ram === null && disk === null ? `<span class="cc-mu small cc-s-none">${esc(L('geen CPU-, RAM- of diskcheck'))}</span>`
        : `<svg viewBox="0 0 156 64" class="cc-s-rings" aria-label="${esc(`CPU ${cpu ?? '–'}% · RAM ${ram ?? '–'}% · ${L('Disk')} ${disk ?? '–'}%`)}" role="img">${ring(cpu, 'CPU', 26)}${ring(ram, 'RAM', 78)}${ring(disk, L('Disk'), 130)}</svg>`}
    </button>`).join('')}</div>`);
}

/** 1.146.0: aanvalspad en impact van één server: van buiten → open poorten (met pakket en ergste kwetsbaarheid) → server → wie ervan afhangt */
async function exposureDialog(hostId) {
  let x;
  try { x = await api('host_exposure', null, { id: hostId }); } catch (ex) { return toast(ex.message, 'err'); }
  const ports = x.ports || [];
  const vulnPorts = ports.filter((p) => p.vuln);
  modal({
    title: `🎯 ${L('Aanvalspad en impact')}: ${x.host.name}`, wide: true,
    body: `<div style="padding:1rem 1.2rem">
      <p class="small">${urgPill(x.risk.score, x.risk.reasons, true)} <b>${L('Risico {u}', { u: x.risk.score })}</b>${x.risk.reasons.length ? ': ' + esc(x.risk.reasons.join(' · ')) : ''}</p>
      <div class="exp-path">
        <div class="exp-col"><b>🌐 ${L('Van buiten / netwerk')}</b></div><i aria-hidden="true">→</i>
        <div class="exp-col"><b>${L('{n} open poort(en)', { n: ports.length })}</b>${vulnPorts.length ? `<span class="crit-txt small">${L('{n} met een kwetsbaarheid', { n: vulnPorts.length })}</span>` : ''}</div><i aria-hidden="true">→</i>
        <div class="exp-col"><b>🖥️ ${esc(x.host.name)}</b>${x.incidents.length ? `<span class="warn-txt small">${L('{n} open incident(en)', { n: x.incidents.length })}</span>` : ''}</div><i aria-hidden="true">→</i>
        <div class="exp-col"><b>${L('{n} afhankelijke server(s)', { n: x.dependents.length })}</b><span class="muted small">${esc(x.dependents.slice(0, 6).join(', ')) || L('geen')}</span></div>
      </div>
      <h3>${L('Open poorten')}</h3>
      ${ports.length ? `<div class="table-scroll"><table class="vuln-table"><thead><tr><th>${L('Poort')}</th><th>${L('Programma')}</th><th>${L('Pakket')}</th><th>${L('Ergste kwetsbaarheid')}</th></tr></thead><tbody>
        ${ports.map((p) => `<tr><td class="mono">${p.port}<span class="muted small"> ${esc(p.addr)}</span></td><td>${esc(p.proc || '–')}</td><td>${esc(p.pkg || '–')}</td>
          <td>${p.vuln ? `${urgPill(p.vuln.risk, [], true)} <button type="button" class="linkbtn" data-exp-cve="${esc(p.vuln.cve)}">${esc(p.vuln.cve)}</button>${p.vuln.kev ? ' ⚠️' : ''}${p.vuln.fixed ? ` <span class="muted small">→ ${esc(p.vuln.fixed)}</span>` : ''}` : '<span class="muted">–</span>'}</td></tr>`).join('')}
      </tbody></table></div>` : `<p class="muted small">${x.host.mode === 'agent' ? L('Geen poorten buiten localhost (of de agent stuurde ze nog niet).') : L('Alleen bekend voor servers met een agent.')}</p>`}
      ${x.incidents.length ? `<h3>${L('Open incidenten')}</h3><ul>${x.incidents.map((i) => `<li><button type="button" class="linkbtn" data-exp-inc="${i.id}">${esc(i.title)}</button></li>`).join('')}</ul>` : ''}
      <p class="muted small">${L('Een schatting: RzSense kent je firewall niet. Een poort die op alle adressen luistert, kan van buiten toch dicht zijn.')}</p>
    </div>`,
    buttons: [{ label: L('Sluiten'), cls: 'primary', onClick: () => $('#modal').close() }],
  });
  $$('[data-exp-cve]', $('#modal')).forEach((b) => (b.onclick = () => { $('#modal').close(); vulnDetail(b.dataset.expCve); }));
  $$('[data-exp-inc]', $('#modal')).forEach((b) => (b.onclick = () => { $('#modal').close(); showTab('incidents'); caseDialog(+b.dataset.expInc); }));
}

/** 1.144.0: urgentie 0–100 als pil (zelfde kleuren als het risico) */
function urgPill(u, why, risk = false) {
  const lvl = u >= 70 ? 'high' : u >= 40 ? 'mid' : 'low';
  return `<span class="risk-pill risk-${lvl}" title="${esc((risk ? L('Risico {u} van 100', { u }) : L('Urgentie {u} van 100', { u })) + (why && why.length ? ': ' + why.join(', ') : ''))}">${u}</span>`;
}

/** 1.144.0: "Nu doen": open incidenten en aandachtspunten samen, op urgentie */
function hmNow(list, full) {
  const shown = list.slice(0, 8);
  return `<section class="hm-card hm-now" aria-labelledby="hm-h-now">
    <div class="hm-card-head"><h2 id="hm-h-now">${esc(L('Nu doen'))}</h2>
      <span>${$('#tab-incidents') ? `<button type="button" class="link-btn" data-hm-go="incidents">${esc(L('Incidenten'))}</button>` : ''}${full ? ` · <button type="button" class="link-btn" data-hm-go="analytics">${esc(L('Alles bekijken'))}</button>` : ''}</span></div>
    ${shown.length ? `<ul>${shown.map((t) => `<li>${urgPill(t.urgency, t.why)}
      <span class="hm-attn-txt">${t.kind === 'inc' ? '⚠ ' : t.icon ? esc(t.icon) + ' ' : ''}${esc(t.text)}
        <small>${esc((t.why || []).slice(1).join(' · '))}${t.kind === 'inc' ? ` <span class="inc-st inc-st-${t.status}">${esc(INC_ST[t.status]())}</span>${t.owner ? ' 👤 ' + esc(t.owner) : ''}${t.parts > 1 ? ' · ' + esc(L('{n} stappen', { n: t.parts })) : ''}` : ''}</small></span>
      <button type="button" class="btn small-btn" data-hm-go="${esc(t.go)}">${esc(L('Openen'))}</button></li>`).join('')}</ul>
      ${list.length > shown.length ? `<p class="muted small">${esc(L('en nog {n}', { n: list.length - shown.length }))}</p>` : ''}`
      : `<p class="hm-empty">${hmShape('ok', 14)} ${esc(L('Niets dat nu aandacht nodig heeft'))}</p>`}
  </section>`;
}

/** Servers met hun CPU, RAM, disk, status en (1.144.0) risico */
function hmAllHosts() {
  const val = (h, t) => { const v = h.checks.filter((c) => c.type === t && +c.enabled && c.last_value !== null).map((c) => +c.last_value); return v.length ? Math.round(Math.max(...v)) : null; };
  return state.hosts.filter((h) => +h.enabled !== 0)
    .map((h) => { const s = hostStatus(h); return { h, st: s === 2 ? 'crit' : s === 1 ? 'warn' : s === 0 ? 'ok' : 'unk', cpu: val(h, 'cpu'), ram: val(h, 'ram'), disk: val(h, 'disk') }; });
}

/** Probleemservers: niet OK, of een risico van 40 of meer; ergste eerst */
function hmProblemHosts(d) {
  const risk = (d && d.risk) || {};
  const rank = { crit: 0, warn: 1, unk: 2, ok: 3 };
  return hmAllHosts().filter((x) => x.st === 'crit' || x.st === 'warn' || ((risk[x.h.id] || {}).score || 0) >= 40)
    .sort((a, b) => rank[a.st] - rank[b.st] || ((risk[b.h.id] || {}).score || 0) - ((risk[a.h.id] || {}).score || 0) || a.h.name.localeCompare(b.h.name));
}

/** Netwerk in één oogopslag: internet → netwerkapparaten → per soort de apparaten met hun status */
function hmMap() {
  const hosts = state.hosts.filter((h) => +h.enabled !== 0);
  const st = (h) => { const s = hostStatus(h); return s === 2 ? 'crit' : s === 1 ? 'warn' : s === 0 ? 'ok' : 'unk'; };   // geen gegevens is nooit groen
  const chip = (h) => `<button type="button" class="hm-host ${st(h)}" data-hm-go="dashboard?server=${encodeURIComponent(h.name)}" title="${esc(h.name)}">${hmShape(st(h))}<span>${esc(h.name)}</span></button>`;
  const net = hosts.filter((h) => hostGroup(h) === 'network');
  const groups = ['server', 'storage', 'smarthome', 'camera', 'power', 'other'].map((g) => [g, hosts.filter((h) => hostGroup(h) === g)]).filter(([, l]) => l.length);
  const worst = (l) => ['crit', 'warn', 'unk'].find((x) => l.map(st).includes(x)) || 'ok';
  return `<section class="hm-card hm-map" aria-labelledby="hm-h-map">
    <div class="hm-card-head"><h2 id="hm-h-map">${esc(L('Netwerk in één oogopslag'))}</h2>
      <span class="hm-legend">${['ok', 'warn', 'crit', 'unk'].map((s) => `<span>${hmShape(s)} ${esc(HM_ST[s]())}</span>`).join('')}</span></div>
    <div class="hm-tree">
      <div class="hm-inet"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a14 14 0 0 1 0 18M12 3a14 14 0 0 0 0 18"/></svg>${esc(L('Internet'))}</div>
      <div class="hm-vline"></div>
      <div class="hm-netrow">${net.length ? net.map(chip).join('') : `<span class="muted small">${esc(L('Router, switches en access points: geef apparaten de soort Router, Switch of Access point'))}</span>`}</div>
      <div class="hm-vline"></div>
      <div class="hm-groups">${groups.map(([g, l]) => `<div class="hm-group">
        <div class="hm-group-head"><b>${GROUP_INFO[g][0]} ${esc(GROUP_INFO[g][1]())}</b><span class="hm-st ${worst(l)}">${hmShape(worst(l))} ${l.length}</span></div>
        <div class="hm-hosts">${l.map(chip).join('')}</div></div>`).join('')}</div>
    </div></section>`;
}

/** Servers: CPU, RAM en de volste disk nu, uit de checks van die server; met (1.144.0) het risico en, compact, zonder balken */
function hmServers(all, title, d, compact = false) {
  const risk = (d && d.risk) || {};
  const list = compact ? all.filter((x) => x.cpu !== null || x.ram !== null || x.disk !== null).sort((a, b) => a.h.name.localeCompare(b.h.name)) : all;
  if (!list.length) return '';
  if (compact) {
    return `<section class="hm-card" aria-labelledby="hm-h-srv2"><div class="hm-card-head"><h2 id="hm-h-srv2">${esc(title)}</h2><span class="muted small">${esc(L('{n} servers', { n: list.length }))}</span></div>
      <div class="hm-srv-compact">${list.map(({ h, st, cpu, ram, disk }) => `<button type="button" class="hm-srv-mini ${st}" data-hm-go="dashboard?server=${encodeURIComponent(h.name)}">
        ${hmShape(st, 10)} <b>${esc(h.name)}</b><span class="muted small">${[cpu !== null ? 'CPU ' + cpu + '%' : '', ram !== null ? 'RAM ' + ram + '%' : '', disk !== null ? L('Disk') + ' ' + disk + '%' : ''].filter(Boolean).join(' · ')}</span>
        ${risk[h.id] && risk[h.id].score ? urgPill(risk[h.id].score, risk[h.id].reasons, true) : ''}</button>`).join('')}</div></section>`;
  }
  const bar = (k, v) => (v === null ? '' : `<div class="hm-bar"><span>${esc(k)}</span><div><i class="${v >= 90 ? 'crit' : v >= 75 ? 'warn' : ''}" style="width:${Math.min(100, v)}%"></i></div><b>${v}%</b></div>`);
  const why = (h) => { const p = h.checks.filter((c) => +c.enabled && !c.maintenance && +c.status >= 1 && +c.status <= 2).sort((a, b) => b.status - a.status)[0]; return p ? p.name : ''; };
  return `<section class="hm-card" aria-labelledby="hm-h-srv">
    <div class="hm-card-head"><h2 id="hm-h-srv">${esc(title)}</h2><span class="muted small">${esc(L('{n} servers · CPU, RAM en disk nu', { n: list.length }))}</span></div>
    <div class="hm-srv-grid">${list.map(({ h, st, cpu, ram, disk }) => {
      const up = stats.uptime[h.id];
      const rk = risk[h.id];
      return `<button type="button" class="hm-srv ${st}" data-hm-go="dashboard?server=${encodeURIComponent(h.name)}">
        <span class="hm-srv-top"><b>${esc(h.name)}</b><span class="hm-st ${st}">${hmShape(st)} ${esc(st === 'ok' ? HM_ST.ok() : why(h) || HM_ST[st]())}</span></span>
        <span class="hm-srv-sub">${esc(kindLabel(hostKind(h)))}${up && up.d7 !== null ? ' · ' + esc(L('{p} bereikbaar (7 d)', { p: pct(up.d7) })) : ''}</span>
        ${rk && rk.score ? `<span class="hm-srv-risk" data-hm-risk="${h.id}" title="${esc(L('Aanvalspad en impact'))}">${urgPill(rk.score, rk.reasons, true)} <span class="small">${esc(L('risico'))}: ${esc(rk.reasons.join(' · '))}</span></span>` : ''}
        ${bar('CPU', cpu)}${bar('RAM', ram)}${bar(L('Disk'), disk)}</button>`;
    }).join('')}</div></section>`;
}

const hmDays = (series) => Object.keys(series || {});
const hmDayLbl = (day, n) => new Date(day + 'T12:00:00').toLocaleDateString(LOCALE, n <= 7 ? { weekday: 'short' } : { day: 'numeric', month: 'numeric' });

/** Beschikbaarheid per dag: lijn met punten, één as in procenten */
function hmAvailChart(d) {
  const days = hmDays(d.avail.series), vals = days.map((k) => d.avail.series[k]);
  const have = vals.filter((v) => v !== null);
  const W = 320, H = 150, x0 = 40, x1 = 312, y0 = 10, y1 = 120;
  let body;
  if (have.length < 1) body = `<p class="hm-empty">${esc(L('Nog geen gegevens in deze periode'))}</p>`;
  else {
    const lo = Math.min(99, Math.floor(Math.min(...have))), hi = 100;
    const X = (i) => x0 + (days.length > 1 ? i * (x1 - x0) / (days.length - 1) : (x1 - x0) / 2);
    const Y = (v) => y0 + (hi - v) / (hi - lo || 1) * (y1 - y0);
    let path = ''; vals.forEach((v, i) => { if (v !== null) path += `${path ? 'L' : 'M'}${X(i).toFixed(1)} ${Y(v).toFixed(1)}`; });
    const step = Math.ceil(days.length / 8);
    body = `<svg viewBox="0 0 ${W} ${H}" class="hm-chart" role="img" aria-label="${esc(L('Beschikbaarheid per dag'))}">
      <g class="ax">${[hi, (hi + lo) / 2, lo].map((v) => `<text x="0" y="${(Y(v) + 4).toFixed(1)}">${dec(+v.toFixed(1))}%</text><path d="M${x0} ${Y(v).toFixed(1)}H${x1}"/>`).join('')}</g>
      <path class="ln s1" d="${path}"/>
      ${vals.map((v, i) => (v === null ? '' : `<circle class="dot s1" cx="${X(i).toFixed(1)}" cy="${Y(v).toFixed(1)}" r="4"><title>${esc(hmDayLbl(days[i], 99))}: ${pct(v)}</title></circle>`)).join('')}
      <g class="ax lbl">${days.map((k, i) => (i % step ? '' : `<text x="${X(i).toFixed(1)}" y="${H - 6}" text-anchor="middle">${esc(hmDayLbl(k, days.length))}</text>`)).join('')}</g></svg>`;
  }
  return `<section class="hm-card" aria-labelledby="hm-h-up"><h2 id="hm-h-up">${esc(L('Beschikbaarheid'))}</h2>
    <p class="hm-card-sub">${esc(L('Alle servers · deze periode'))}${d.avail.now !== null ? ` · <b>${pct(d.avail.now)}</b>` : ''}</p>${body}</section>`;
}

/** IDS per dag: gestapelde staven, geblokkeerd en gemeld */
function hmIdsChart(d) {
  const s = d.ids.series, days = hmDays(s.blk);
  const rep = days.map((k) => (+s.warn[k] || 0) + (+s.crit[k] || 0)), blk = days.map((k) => +s.blk[k] || 0);
  const max = Math.max(1, ...days.map((k, i) => rep[i] + blk[i]));
  const W = 320, H = 150, x0 = 8, x1 = 312, base = 120, gap = 2;
  const bw = Math.max(3, Math.min(26, (x1 - x0) / Math.max(1, days.length) - 6));
  const X = (i) => x0 + (i + 0.5) * (x1 - x0) / Math.max(1, days.length) - bw / 2;
  const step = Math.ceil(days.length / 8);
  return `<section class="hm-card" aria-labelledby="hm-h-ids"><h2 id="hm-h-ids">${esc(L('IDS-gebeurtenissen'))}</h2>
    <p class="hm-card-sub hm-legend"><span><i class="sw s1"></i>${esc(L('Geblokkeerd'))}</span><span><i class="sw s2"></i>${esc(L('Gemeld'))}</span></p>
    ${days.length ? `<svg viewBox="0 0 ${W} ${H}" class="hm-chart" role="img" aria-label="${esc(L('IDS-gebeurtenissen per dag: geblokkeerd en gemeld'))}">
      <g class="ax"><path d="M${x0} ${base}H${x1}"/></g>
      ${days.map((k, i) => { const hb = blk[i] / max * 108, hr = rep[i] / max * 108;
        return `<g><title>${esc(hmDayLbl(k, 99))}: ${esc(L('{b} geblokkeerd, {r} gemeld', { b: blk[i], r: rep[i] }))}</title>
          ${hb ? `<rect class="s1" x="${X(i).toFixed(1)}" y="${(base - hb).toFixed(1)}" width="${bw.toFixed(1)}" height="${hb.toFixed(1)}" rx="3"/>` : ''}
          ${hr ? `<rect class="s2" x="${X(i).toFixed(1)}" y="${(base - hb - (hb ? gap : 0) - hr).toFixed(1)}" width="${bw.toFixed(1)}" height="${hr.toFixed(1)}" rx="3"/>` : ''}
          ${i % step ? '' : `<text class="axt" x="${(X(i) + bw / 2).toFixed(1)}" y="${H - 6}" text-anchor="middle">${esc(hmDayLbl(k, days.length))}</text>`}</g>`; }).join('')}</svg>`
      : `<p class="hm-empty">${esc(L('Nog geen gegevens in deze periode'))}</p>`}</section>`;
}

/** Open CVE's per ernst */
function hmVulnCard(v) {
  const rows = [[4, L('Kritiek'), 'crit'], [3, L('Hoog'), 's2'], [2, L('Middel'), 's4'], [1, L('Laag'), 'mut']].map(([k, l, c]) => ({ n: v.sev[k] || 0, l, c }));
  return `<section class="hm-card" aria-labelledby="hm-h-cve"><h2 id="hm-h-cve">${esc(L('Kwetsbaarheden (CVE)'))}</h2>
    <p class="hm-card-sub"><b>${esc(L('{n} open', { n: hmNum(v.total) }))}</b> · ${esc(L('{n} op te lossen met een update', { n: hmNum(v.fix) }))}${v.kev ? ' · ' + esc(L('{n} in KEV (actief misbruikt)', { n: v.kev })) : ''}</p>
    ${v.total ? `<div class="hm-stack" role="img" aria-label="${esc(rows.map((r) => `${r.n} ${r.l}`).join(', '))}">${rows.filter((r) => r.n).map((r) => `<i class="${r.c}" style="flex:${r.n}"></i>`).join('')}</div>` : ''}
    <div class="hm-sevs">${rows.map((r) => `<button type="button" class="hm-sevbox" data-hm-go="vulns"><i class="sw ${r.c}"></i><span>${esc(r.l)}</span><b>${hmNum(r.n)}</b></button>`).join('')}</div>
    ${v.hosts.length ? `<p class="hm-card-sub">${esc(L('Meeste open'))}: ${v.hosts.map((h) => `<b>${esc(h.name)}</b> (${h.n})`).join(', ')}</p>` : ''}</section>`;
}

function hmNetCard(n) {
  const tiles = [[L('Apparaten online'), hmNum(n.online), L('{n} bekend · {m} nieuw', { n: hmNum(n.total), m: n.new })],
    n.adguard ? [L('DNS geblokkeerd'), dec((n.adguard.blocked / n.adguard.queries * 100).toFixed(1)) + '%', L('{b} van {q} vragen', { b: hmNum(n.adguard.blocked), q: hmNum(n.adguard.queries) })] : null,
    n.aps ? [L('Wifi-clients'), hmNum(n.wifi), L('{n} access points', { n: n.aps })] : null,
    [L('Geblokkeerd'), hmNum(n.blocked), n.risky ? L('{n} met een riskante poort', { n: n.risky }) : L('geen riskante poorten')]].filter(Boolean);
  const vals = hmVals(n.series);
  return `<section class="hm-card hm-grow" aria-labelledby="hm-h-net"><div class="hm-card-head"><h2 id="hm-h-net">${esc(L('Netwerk'))}</h2><button type="button" class="link-btn" data-hm-go="net">${esc(L('Naar Netwerk'))}</button></div>
    <div class="hm-mini">${tiles.map(([l, v, s]) => `<div><span>${esc(l)}</span><b>${v}</b><small>${esc(s)}</small></div>`).join('')}</div>
    ${vals.length > 1 ? `<p class="hm-card-sub">${esc(L('Apparaten op het netwerk per dag'))}</p>${hmSpark(vals, 's3 wide')}` : ''}</section>`;
}

function hmTimeline(evs) {
  const st = (e) => (e.kind === 'info' ? 'info' : e.kind === 'notify' ? hmStOf(e.status) : e.status >= 2 ? 'crit' : 'warn');
  const time = (at) => { const t = new Date(at.replace(' ', 'T')); return t.toDateString() === new Date().toDateString()
    ? t.toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit' }) : t.toLocaleDateString(LOCALE, { day: 'numeric', month: 'short' }); };
  return `<section class="hm-card hm-grow" aria-labelledby="hm-h-tl"><div class="hm-card-head"><h2 id="hm-h-tl">${esc(L('Laatste gebeurtenissen'))}</h2><button type="button" class="link-btn" data-hm-go="alerts">${esc(L('Alle meldingen'))}</button></div>
    ${evs.length ? `<ol class="hm-tl">${evs.map((e) => { const s = st(e); return `<li><time>${esc(time(e.at))}</time>${s === 'info'
      ? `<svg class="hm-shape info" width="10" height="10" viewBox="0 0 10 10" role="img" aria-label="${esc(L('Info'))}"><circle cx="5" cy="5" r="4" fill="none" stroke-width="2"/></svg>` : hmShape(s)}
      <span><b>${esc(e.title)}</b>${e.host ? `<small>${esc(e.host)}</small>` : ''}</span></li>`; }).join('')}</ol>` : `<p class="hm-empty">${esc(L('Nog niets gebeurd'))}</p>`}</section>`;
}

/** 1.135.0: CPU en RAM over alle servers, gemiddeld per uur (24 uur), twee lijnen op één as in procenten */
function hmResChart(r) {
  const W = 640, H = 250, x0 = 34, x1 = 630, y0 = 10, y1 = 220;
  const have = (r.cpu || []).concat(r.ram || []).some((v) => v !== null);
  const X = (i) => x0 + i * (x1 - x0) / 23, Y = (v) => y1 - v / 100 * (y1 - y0);
  const path = (vals) => { let p = '', pen = false; vals.forEach((v, i) => { if (v === null) { pen = false; return; } p += `${pen ? 'L' : 'M'}${X(i).toFixed(1)} ${Y(v).toFixed(1)}`; pen = true; }); return p; };
  const hour = (i) => new Date((r.start + i * 3600) * 1000).toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit' });
  const last = (vals) => { for (let i = vals.length - 1; i >= 0; i--) if (vals[i] !== null) return vals[i]; return null; };
  const now = { cpu: last(r.cpu || []), ram: last(r.ram || []) };
  return `<section class="hm-card hm-res" aria-labelledby="hm-h-res"><div class="hm-card-head"><h2 id="hm-h-res">${esc(L('Resourcegebruik · 24 uur'))}</h2>
    <span class="hm-legend"><span><i class="sw s1"></i>CPU${now.cpu !== null ? ` <b>${dec(now.cpu.toFixed(0))}%</b>` : ''}</span><span><i class="sw s3"></i>RAM${now.ram !== null ? ` <b>${dec(now.ram.toFixed(0))}%</b>` : ''}</span></span></div>
    <p class="hm-card-sub">${esc(L('Gemiddeld over {n} servers met een CPU- of RAM-check, per uur', { n: r.hosts }))}</p>
    ${have ? `<svg viewBox="0 0 ${W} ${H}" class="hm-chart" role="img" aria-label="${esc(L('CPU en RAM per uur over de laatste 24 uur'))}">
      <g class="ax">${[0, 50, 100].map((v) => `<text x="0" y="${(Y(v) + 4).toFixed(1)}">${v}%</text><path d="M${x0} ${Y(v).toFixed(1)}H${x1}"/>`).join('')}</g>
      <path class="ln s3" d="${path(r.ram)}"/><path class="ln s1" d="${path(r.cpu)}"/>
      ${(r.cpu || []).map((v, i) => `<rect class="hit" x="${(X(i) - 12).toFixed(1)}" y="${y0}" width="24" height="${y1 - y0}"><title>${esc(hour(i))} · CPU ${v === null ? '–' : dec(v.toFixed(1)) + '%'} · RAM ${r.ram[i] === null ? '–' : dec(r.ram[i].toFixed(1)) + '%'}</title></rect>`).join('')}
      <g class="ax lbl">${[0, 6, 12, 18, 23].map((i) => `<text x="${X(i).toFixed(1)}" y="${H - 8}" text-anchor="middle">${esc(hour(i))}</text>`).join('')}</g></svg>`
      : `<p class="hm-empty">${esc(L('Nog geen CPU- of RAM-metingen: voeg die checks toe bij je servers'))}</p>`}</section>`;
}

/** 1.135.0: recente incidenten (IDS), open eerst, met de ernst als woord en vorm */
function hmIncidents(d) {
  const list = d.incidents || [];
  const sev = (i) => (i.sev >= 2 ? ['crit', L('Kritiek')] : ['warn', L('Hoog')]);
  return `<section class="hm-card hm-inc" aria-labelledby="hm-h-inc"><div class="hm-card-head"><h2 id="hm-h-inc">${esc(L('Recente incidenten'))}</h2>
    <button type="button" class="link-btn" data-hm-go="ids">${esc(d.ids.open_total ? L('{n} open', { n: d.ids.open_total }) : L('Naar IDS'))}</button></div>
    ${list.length ? `<ul>${list.slice(0, 5).map((i) => { const [c, l] = sev(i); return `<li class="${i.open ? '' : 'done'}">${hmShape(i.open ? c : 'ok', 11)}
      <span><small class="hm-sevlbl ${i.open ? c : 'ok'}">${esc(i.open ? l : L('Afgehandeld'))}</small><b>${esc(i.title)}</b><small>${esc(i.host)} · ${esc(fmtUntil(i.at))}${i.hits > 1 ? ' · ' + esc(L('{n}×', { n: i.hits })) : ''}</small></span></li>`; }).join('')}</ul>`
      : `<p class="hm-empty">${hmShape('ok', 14)} ${esc(L('Geen incidenten de laatste 14 dagen'))}</p>`}</section>`;
}

// ---------------------------------------------------------------- ⚠ Incidenten (1.142.0)
// Eén lijst uit monitoring (critical ≥ 5 min), IDS (critical) en kwetsbaarheden (actief misbruikt), met status, eigenaar en tijdlijn
let incData = null;
let incFilter = 'active';
const INC_ST = { open: () => L('open'), ack: () => L('in behandeling'), resolved: () => L('opgelost') };
const INC_SRC = { check: ['📈', () => L('Monitoring')], ids: ['🛡️', () => 'IDS'], vuln: ['🐞', () => L('Kwetsbaarheden')] };

async function loadIncidents() {
  if (!$('#inc-list')) return;
  try { incData = await api('incidents'); } catch (ex) { $('#inc-list').innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  renderIncidents();
}

function incVisible() {
  const q = ($('#inc-search').value || '').trim().toLowerCase();
  return incData.incidents.filter((i) => (incFilter === 'all' || (incFilter === 'active' ? i.status !== 'resolved' : i.status === incFilter))
    && (!q || [i.title, i.host || '', i.owner || '', i.detail].join(' ').toLowerCase().includes(q)));
}

function renderIncidents() {
  if (!incData) return;
  try { ccIncCharts(); } catch (e) { /* grafiek mag de lijst nooit tegenhouden */ }
  const c = incData.counts;
  $('#inc-badge').hidden = !c.open;
  $('#inc-badge').textContent = c.open || '';
  $('#inc-kpis').innerHTML = `
    <div class="kpi ${c.open ? 'bad' : ''}"><div class="kpi-lbl">${L('Open')}</div><div class="kpi-val">${c.open}</div><div class="kpi-sub">${L('nog niemand mee bezig')}</div></div>
    <div class="kpi"><div class="kpi-lbl">${L('In behandeling')}</div><div class="kpi-val">${c.ack}</div><div class="kpi-sub">${L('met een eigenaar')}</div></div>
    <div class="kpi"><div class="kpi-lbl">${L('Opgelost (30 dagen)')}</div><div class="kpi-val ${c.resolved ? 'good-txt' : ''}">${c.resolved}</div><div class="kpi-sub">${L('vanzelf of door iemand')}</div></div>
    <div class="kpi"><div class="kpi-lbl">${L('Gemiddeld opgelost na')}</div><div class="kpi-val kpi-val-txt">${c.mttr !== null ? fmtDur(c.mttr) : '–'}</div><div class="kpi-sub">${L('laatste 30 dagen')}</div></div>`;
  const n = (f) => incData.incidents.filter((i) => (f === 'all' ? true : f === 'active' ? i.status !== 'resolved' : i.status === f)).length;
  $('#inc-filter').innerHTML = [['active', L('Nog bezig')], ['open', L('Open')], ['ack', L('In behandeling')], ['resolved', L('Opgelost')], ['all', L('Alles')]]
    .map(([k, l]) => `<button type="button" class="dchip ${incFilter === k ? 'on' : ''}" data-incf="${k}">${l} <b>${n(k)}</b></button>`).join('');
  const list = incVisible();
  $('#inc-list').innerHTML = list.length ? `<div class="card inc-card"><table class="inc-table"><thead><tr><th title="${esc(L('Urgentie: ernst, duur, bereikbaar, afhankelijke servers en beveiliging'))}">${L('Urgentie')}</th><th></th><th>${L('Incident')}</th><th>${L('Status')}</th><th>${L('Eigenaar')}</th><th>${L('Geopend')}</th><th class="num">${L('Duur')}</th></tr></thead><tbody>
    ${list.map((i) => {
      const [ic, src] = INC_SRC[i.source] || ['•', () => i.source];
      const end = i.resolved_at ? new Date(i.resolved_at.replace(' ', 'T')) : new Date();
      const dur = Math.max(0, (end - new Date(i.opened_at.replace(' ', 'T'))) / 1000);
      return `<tr class="inc-row inc-${i.status}" data-inc="${i.id}" tabindex="0">
        <td>${i.status === 'resolved' ? '<span class="muted small">–</span>' : urgPill(i.urgency, i.why)}</td>
        <td title="${esc(src())}">${ic}</td>
        <td><b>${esc(i.title)}</b>${i.status !== 'resolved' ? ' ' + aiBtn('incident', i.id) : ''}${i.parts > 1 ? ` <span class="muted small">· ${esc(L('{n} stappen', { n: i.parts }))}</span>` : ''}${i.detail ? `<div class="muted small">${esc(i.detail.length > 120 ? i.detail.slice(0, 120) + '…' : i.detail)}</div>` : ''}</td>
        <td><span class="inc-st inc-st-${i.status}">${INC_ST[i.status]()}</span>${i.notes ? ` <span class="muted small" title="${esc(L('notities'))}">💬 ${i.notes}</span>` : ''}</td>
        <td>${i.owner ? esc(i.owner) : '<span class="muted">–</span>'}</td>
        <td class="small">${agoSpan(i.opened_at)}</td>
        <td class="num small">${fmtDur(dur)}</td></tr>`;
    }).join('')}</tbody></table></div>`
    : `<div class="card"><p class="muted" style="margin:0">${incFilter === 'active' && !$('#inc-search').value ? '✔ ' + L('Geen open incidenten.') : L('Niets gevonden.')}</p></div>`;
}

/** 1.152.1: een zaak op het tabblad Incidenten (tabel incidents). Heette eerst ook incidentDialog en overschreef zo
 * het venster van een IDS-incident: dat gaf "Incident niet gevonden". */
async function caseDialog(id) {
  let i;
  try { i = await api('incident_info', null, { id }); } catch (ex) { return toast(ex.message, 'err'); }
  const [ic, src] = INC_SRC[i.source] || ['•', () => i.source];
  const users = (incData && incData.users) || [];
  const KIND = { system: '⚙️', status: '🔁', owner: '👤', note: '💬' };
  const go = i.source === 'check' ? ['dashboard', L('Naar Monitoring')] : i.source === 'ids' ? ['ids', L('Naar IDS')] : ['vulns', L('Naar Kwetsbaarheden')];
  const { form } = modal({
    title: `${ic} ${i.title}`, wide: true,
    body: `<div style="padding:1rem 1.2rem">
      <p class="muted small">${esc(src())}${i.host ? ' · ' + esc(i.host) : ''} · ${L('geopend {t}', { t: esc(fmtDateTime(i.opened_at)) })}${i.resolved_at ? ' · ' + L('opgelost {t}', { t: esc(fmtDateTime(i.resolved_at)) }) : ''}</p>
      ${i.detail ? `<p>${esc(i.detail)}</p>` : ''}
      ${aiOn() ? `<div class="btn-row">${aiBtn('incident', +id, true)}${i.status === 'resolved' && state.ai.report && state.ai.ask ? `<button type="button" class="btn small-btn ai-btn" data-ai-kind="report" data-ai-ref="${+id}">📝 ${L('AI-verslag')}</button>` : ''}</div>` : ''}
      ${i.status !== 'resolved' ? `<p class="small">${urgPill(i.urgency, i.why)} <b>${L('Urgentie {u}', { u: i.urgency })}</b>: ${esc(i.why.join(' · '))}</p>` : ''}
      ${i.path && i.path.length ? `<div class="inc-path" aria-label="${esc(L('Pad'))}">${i.path.map((p) => `<span>${esc(p)}</span>`).join('<i aria-hidden="true">→</i>')}</div>` : ''}
      ${i.steps && i.steps.length ? `<h3>${L('Stappen')}</h3><ol class="inc-steps">${i.steps.map((s) => `<li class="${s.severity >= 2 ? 'crit' : 'warn'}"><b>${esc(s.title)}</b>
        <span class="muted small">${esc(fmtDateTime(s.at))}${s.ip ? ' · ' + esc(s.ip) : ''}</span></li>`).join('')}</ol>` : ''}
      <div class="row2">
        <label>${L('Status')}<select name="status" class="need-user">${Object.keys(INC_ST).map((k) => `<option value="${k}" ${i.status === k ? 'selected' : ''}>${INC_ST[k]()}</option>`).join('')}</select></label>
        <label>${L('Eigenaar')}<select name="owner" class="need-user"><option value="">–</option>${users.map((u) => `<option ${i.owner === u ? 'selected' : ''}>${esc(u)}</option>`).join('')}</select></label>
      </div>
      <label>${L('Notitie')} <span class="hint">${L('(wat je gedaan of gevonden hebt)')}</span><textarea name="note" rows="3" maxlength="2000"></textarea></label>
      <h3>${L('Tijdlijn')}</h3>
      <ul class="inc-timeline">${i.notes.slice().reverse().map((n) => `<li class="k-${esc(n.kind)}"><span class="ic">${KIND[n.kind] || '•'}</span>
        <div><div>${esc(n.text).replace(/\n/g, '<br>')}</div><div class="muted small">${esc(n.by_user)} · ${esc(fmtDateTime(n.created_at))}</div></div></li>`).join('')}</ul>
    </div>`,
    buttons: [
      { label: go[1] + ' →', style: 'margin-right:auto', onClick: () => { $('#modal').close(); showTab(go[0]); } },
      ...(i.host_id ? [{ label: '🎯 ' + L('Aanvalspad'), onClick: () => exposureDialog(+i.host_id) }] : []),
      { label: L('Sluiten'), onClick: () => $('#modal').close() },
      { label: '✔ ' + L('Opslaan'), cls: 'primary need-user', submit: true },
    ],
    onSubmit: async (v) => {
      await api('incident_set', { id: i.id, status: v.status, owner: v.owner, note: v.note });
      toast(L('Opgeslagen'));
      loadIncidents();
    },
  });
  return form;
}

(function incWire() {
  if (!$('#inc-list')) return;
  $('#inc-filter').addEventListener('click', (e) => { const b = e.target.closest('[data-incf]'); if (b) { incFilter = b.dataset.incf; renderIncidents(); } });
  $('#inc-search').addEventListener('input', () => renderIncidents());
  const open = (e) => { const r = e.target.closest('[data-inc]'); if (r) caseDialog(+r.dataset.inc); };
  $('#inc-list').addEventListener('click', open);
  $('#inc-list').addEventListener('keydown', (e) => { if (e.key === 'Enter') open(e); });
})();

// 📄 Rapport (PDF): afdrukbare pagina in een nieuw venster, meteen het afdrukvenster (daar: Opslaan als PDF)
(function anPdfWire() {
  const b = $('#an-pdf');
  if (!b) return;
  b.onclick = () => {
    const w = window.open('api.php?' + new URLSearchParams({ action: 'report', period: anPeriod }), '_blank');
    if (!w) return toast(L('Sta pop-ups toe voor RzSense om het rapport te openen'), 'err');
    w.addEventListener('load', () => setTimeout(() => { try { w.print(); } catch (e) { /* zelf afdrukken */ } }, 300));
  };
})();

// ---------------------------------------------------------------- Internet (1.157.0): Instellingen → Monitoring → Internet
async function loadInet() {
  const box = $('#inet-state');
  if (!box) return;
  let r;
  try { r = await api('inet_state'); } catch (ex) { box.innerHTML = `<p class="err-txt small">${esc(ex.message)}</p>`; return; }
  const fmtT = (t) => new Date(t * 1000).toLocaleString(LOCALE, { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
  const plan = { down: +($('[name=inet_down]').value || 1000), up: +($('[name=inet_up]').value || 1000) };
  const last = r.last;
  const val = (d) => (last && last[d] !== null ? `<b>${Math.round(last[d]).toLocaleString(LOCALE)}</b> <span class="muted">Mbit/s · ${Math.round(last[d] / plan[d] * 100)}%</span>` : '–');
  // Verloop van 30 dagen: download en upload als lijntjes, in procent van het abonnement
  const hist = r.history.filter((x) => x.down !== null);
  let chart = `<p class="muted small">${L('Het verloop verschijnt na een paar snelheidstesten.')}</p>`;
  if (hist.length >= 2) {
    const W = 600, H = 90, t0 = hist[0].at, t1 = hist[hist.length - 1].at || t0 + 1;
    const x = (t) => ((t - t0) / Math.max(1, t1 - t0)) * W;
    const y = (v, d) => H - Math.min(1.1, v / plan[d]) / 1.1 * (H - 6) - 3;
    const line = (d) => hist.map((p, i) => `${i ? 'L' : 'M'}${x(p.at).toFixed(1)},${y(p[d] || 0, d).toFixed(1)}`).join('');
    chart = `<svg class="inet-chart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="${esc(L('Snelheid, 30 dagen'))}">
      <line x1="0" x2="${W}" y1="${y(plan.down, 'down')}" y2="${y(plan.down, 'down')}" class="inet-plan"/>
      <path d="${line('down')}" class="inet-down"/><path d="${line('up')}" class="inet-up"/></svg>
      <div class="muted small"><span class="inet-key d"></span> ${L('download')} <span class="inet-key u"></span> ${L('upload')} · ${L('stippellijn = je abonnement')} · ${L('{n} testen in 30 dagen', { n: hist.length })}</div>`;
  }
  box.innerHTML = `
    ${r.host ? '' : `<div class="callout"><p>${L('Er is nog geen Internet-check. Met één klik komt er een apparaat <b>Internet</b> bij met vier checks: ping, responstijd, download en upload.')}</p>
      <button type="button" class="btn primary" id="inet-install">🌍 ${L('Internet-check toevoegen')}</button></div>`}
    <div class="inet-grid">
      <div><span class="muted small">${L('Download')}</span><div class="inet-v">↓ ${val('down')}</div></div>
      <div><span class="muted small">${L('Upload')}</span><div class="inet-v">↑ ${val('up')}</div></div>
      <div><span class="muted small">${L('Ping naar de testserver')}</span><div class="inet-v">${last && last.lat !== null ? `<b>${dec(String(Math.round(last.lat * 10) / 10))}</b> <span class="muted">ms${last.colo ? ' · ' + esc(last.colo) : ''}</span>` : '–'}</div></div>
      <div><span class="muted small">${L('Laatste test')}</span><div>${last ? esc(fmtT(last.at)) + (last.err ? ` <span class="err-txt small">✘ ${esc(last.err)}</span>` : ` <span class="muted small">(${L('{n} MB', { n: Math.round(last.mb) })})</span>`) : L('nog niet')}</div>
        <span class="muted small">${r.next ? L('Volgende: {t}', { t: esc(fmtT(r.next)) }) : ''}</span></div>
    </div>
    ${chart}
    <p class="muted small">${r.gateway ? L('Je router (standaardgateway van deze server): {ip}', { ip: esc(r.gateway) }) : L('Geen standaardgateway gevonden op deze server.')}</p>
    ${r.host ? `<p><button type="button" class="btn" id="inet-now" ${r.running ? 'disabled' : ''}>⚡ ${r.running ? L('Test loopt…') : L('Nu testen')}</button>
      <span class="muted small">${L('Duurt tot een halve minuut en trekt je lijn even vol.')}</span></p>` : ''}`;
  const ins = $('#inet-install');
  if (ins) ins.onclick = async () => { ins.disabled = true; try { const x = await api('inet_install', {}); toast(x.message); refresh(); loadInet(); } catch (ex) { toast(ex.message, 'err'); ins.disabled = false; } };
  const now = $('#inet-now');
  if (now) now.onclick = async () => {
    now.disabled = true; now.textContent = '⏳ ' + L('Test loopt…');
    try { const x = await api('inet_speed_now', {}); toast(x.message); } catch (ex) { toast(ex.message, 'err'); }
    loadInet(); refresh();
  };
}
// ---------------------------------------------------------------- 🧩 Onbekende programma's en 🔎 Jagen op sporen (1.229.0, agent 1.91.0)
// IDS → Programma's (wat er draait, toestaan/blokkeren), IDS → Jagen (sporen zoeken, ook op de servers, en bewaken),
// de kaart in de Agent Manager en Instellingen → IDS → Programma's / Jagen op sporen.
const APP_ST = {
  new: () => ['⚠', L('onbekend'), 'warn'], block: () => ['⛔', L('geblokkeerd'), 'bad'], ok: () => ['✔', L('toegestaan'), 'ok'],
  learn: () => ['🎓', L('geleerd'), 'muted'], pkg: () => ['📦', L('uit een pakket'), 'muted'],
};
const appChip = (s) => { const [ic, t, c] = (APP_ST[s] || (() => ['?', s, 'muted']))(); return `<span class="app-chip app-${c}">${ic} ${esc(t)}</span>`; };
const appVerdict = (v) => (v === 'malware' ? ` <b class="bad">☣ ${L('bekende malware')}</b>` : v === 'known_good' ? ` <span class="ok small">✔ ${L('bekend bestand (CIRCL)')}</span>` : '');
let appsOpt = { status: '', host: '', q: '' }, appsData = null;

async function loadApps() {
  const box = $('#apps-body');
  if (!box) return;
  try { appsData = await api('apps', null, appsOpt); } catch (ex) { box.innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  const d = appsData;
  const hs = $('#apps-host');
  if (hs && hs.options.length <= 1) hs.insertAdjacentHTML('beforeend', d.hosts.map((h) => `<option value="${h.id}">${esc(h.name)}</option>`).join(''));
  const c = d.counts;
  $('#it-n-apps').textContent = c.new + c.block || '';
  const learning = d.hosts.filter((h) => h.on && h.learning && h.until);
  const noAgent = d.hosts.filter((h) => h.on && !h.agent_ok).length;
  box.innerHTML = `${!d.on ? `<div class="callout small">${L('Onbekende programma\'s staat uit (Instellingen → IDS → Programma\'s).')}</div>` : ''}
    <div class="app-sum">${['new', 'block', 'ok', 'learn', 'pkg'].map((s) => `<button type="button" class="app-sum-b${appsOpt.status === s ? ' active' : ''}" data-app-st="${s}">${appChip(s)} <b>${c[s] || 0}</b></button>`).join('')}
      <button type="button" class="app-sum-b${appsOpt.status === '' ? ' active' : ''}" data-app-st="">${L('Zonder pakket')}</button><button type="button" class="app-sum-b${appsOpt.status === 'all' ? ' active' : ''}" data-app-st="all">${L('Alles')}</button></div>
    ${learning.length ? `<p class="muted small">🎓 ${L('Leert nog (wat nu draait wordt als normaal gezien):')} ${learning.map((h) => `${esc(h.name)} ${L('tot {d}', { d: new Date(h.until.replace(' ', 'T')).toLocaleDateString(LOCALE) })}`).join(' · ')}</p>` : ''}
    ${noAgent ? `<p class="muted small">${L('{n} servers hebben agent 1.91.0 of nieuwer nodig.', { n: noAgent })}</p>` : ''}
    ${d.rows.length ? `<div class="table-scroll"><table class="vuln-table small app-table"><thead><tr><th>${L('Status')}</th><th>${L('Programma')}</th><th>${L('Server')}</th><th>${L('Gebruiker')}</th><th>${L('Laatst gezien')}</th><th></th></tr></thead><tbody>
      ${d.rows.map((r, i) => `<tr><td>${appChip(r.status)}</td><td><code>${esc(r.path)}</code>${appVerdict(r.verdict)}<br><span class="muted">${r.pkg ? '📦 ' + esc(r.pkg) + ' · ' : ''}sha256 <code title="${esc(r.sha)}">${esc(r.sha.slice(0, 16))}…</code></span>${r.cmd ? `<br><code class="edr-cmd">${esc(r.cmd.slice(0, 160))}</code>` : ''}</td>
        <td>${esc(r.host)}</td><td>${esc(r.user || '–')}</td><td>${agoSpan(r.last)}</td>
        <td class="nowrap need-admin">${r.status !== 'ok' ? `<button type="button" class="btn small-btn" data-app-do="allow" data-i="${i}">✔ ${L('Toestaan')}</button>` : ''} ${r.status !== 'block' ? `<button type="button" class="btn small-btn danger" data-app-do="block" data-i="${i}">⛔</button>` : ''}</td></tr>`).join('')}
      </tbody></table></div>` : `<p class="muted">${L('Niets in deze lijst.')}</p>`}
    <h3 class="set-sub">${L('Wat je besliste')}</h3>
    ${d.rules.length ? `<div class="table-scroll"><table class="vuln-table small"><thead><tr><th>${L('Keuze')}</th><th>${L('Waarop')}</th><th>${L('Server')}</th><th>${L('Notitie')}</th><th>${L('Door')}</th><th></th></tr></thead><tbody>
      ${d.rules.map((r) => `<tr><td>${r.action === 'block' ? appChip('block') : appChip('ok')}</td><td>${r.sha ? `sha256 <code title="${esc(r.sha)}">${esc(r.sha.slice(0, 16))}…</code>` : `<code>${esc(r.path)}</code>${r.path.endsWith('/') ? ' ' + L('(alles in deze map)') : ''}`}</td>
        <td>${r.host_id ? esc(r.host || '?') : L('alle servers')}</td><td>${esc(r.note)}</td><td class="muted">${esc(r.by || '')} · ${agoSpan(r.at)}</td>
        <td class="need-admin"><button type="button" class="btn small-btn" data-app-rule-del="${r.id}" title="${esc(L('Keuze weghalen'))}">✕</button></td></tr>`).join('')}</tbody></table></div>`
      : `<p class="muted small">${L('Nog niets toegestaan of geblokkeerd.')}</p>`}`;
  box.onclick = async (e) => {
    const st = e.target.closest('[data-app-st]');
    if (st) { appsOpt.status = st.dataset.appSt; return loadApps(); }
    const del = e.target.closest('[data-app-rule-del]');
    if (del) {
      try { await api('apps_rule_delete', { id: +del.dataset.appRuleDel }); toast(L('Keuze weggehaald')); loadApps(); } catch (ex) { toast(ex.message, 'err'); }
      return;
    }
    const b = e.target.closest('[data-app-do]');
    if (b) appDecide(b.dataset.appDo, d.rows[+b.dataset.i], loadApps);
  };
}

/** Toestaan of blokkeren: op vingerafdruk, dit pad of de map; voor deze server of alle servers */
function appDecide(action, r, done) {
  const dir = r.path.replace(/[^/]+$/, '');
  modal({
    title: action === 'block' ? L('Programma blokkeren') : L('Programma toestaan'),
    body: `<p><code>${esc(r.path)}</code><br><span class="muted small">sha256 ${esc(r.sha)}</span></p>
      <label>${L('Waarop')}<select name="on"><option value="sha">${L('Deze vingerafdruk (precies dit programma)')}</option><option value="path">${L('Dit pad (ook na een update)')}</option>
        ${action === 'allow' && dir.length > 1 ? `<option value="dir">${L('Alles in {d}', { d: esc(dir) })}</option>` : ''}</select></label>
      <label>${L('Voor')}<select name="scope"><option value="host">${L('Alleen {h}', { h: esc(r.host || L('deze server')) })}</option><option value="all">${L('Alle servers')}</option></select></label>
      <label>${L('Notitie')} <span class="hint">${L('(waarom, voor later)')}</span><input name="note" maxlength="200"></label>
      ${action === 'block' ? `<p class="muted small">${L('Draait het, dan krijg je een critical incident. De agent stopt het alleen als "Geblokkeerde programma\'s stoppen" aan staat bij die server (Agent Manager).')}</p>` : ''}`,
    buttons: [{ label: action === 'block' ? '⛔ ' + L('Blokkeren') : '✔ ' + L('Toestaan'), cls: action === 'block' ? 'danger' : 'primary', submit: true }],
    onSubmit: async (f) => {
      const on = f.on;
      await api('apps_decide', { action, sha: on === 'sha' ? r.sha : '', path: on === 'path' ? r.path : on === 'dir' ? dir : '', host_id: f.scope === 'all' ? 0 : r.host_id, note: f.note });
      $('#modal').close();
      toast(action === 'block' ? L('Geblokkeerd; de agent krijgt het binnen een minuut') : L('Toegestaan'));
      done();
    },
  });
}

function initApps() {
  const hs = $('#apps-host'), q = $('#apps-q');
  if (!hs || hs.dataset.wired) return;
  hs.dataset.wired = '1';
  hs.onchange = () => { appsOpt.host = hs.value; loadApps(); };
  let tm = null;
  q.oninput = () => { clearTimeout(tm); tm = setTimeout(() => { appsOpt.q = q.value.trim(); loadApps(); }, 300); };
}

// ---------------------------------------------------------------- 🔎 Jagen
const IOC_KIND = { ip: () => 'IP', domain: () => L('domein'), sha: () => 'sha256', path: () => L('pad') };
const IOC_SRC = { ids: () => 'IDS', ssh: () => 'SSH', block: () => L('blokkade'), login: () => L('inloggen RzSense'), web: () => L('websites'), apps: () => L('programma\'s'),
  ti: () => L('dreigingsinfo'), edr: () => 'EDR', logs: () => L('logs') };
let huntCur = null, huntPoll = null;
const nTreffer = (n) => (+n === 1 ? L('1 treffer') : L('{n} treffers', { n }));

async function loadHunt() {
  const box = $('#hunt-side');
  if (!box) return;
  let d;
  try { d = await api('ioc_hunts'); } catch (ex) { box.innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  $('#hunt-off').hidden = d.on;
  box.innerHTML = `<h3 class="set-sub">👁 ${L('Bewaakte sporen')} <span class="muted small">(${d.watch.length})</span></h3>
    <p class="muted small">${L('Elke 10 minuten vergeleken met wat er nieuw binnenkomt; een treffer is een critical incident.')}</p>
    ${d.watch.length ? `<div class="table-scroll hunt-watch"><table class="vuln-table small"><tbody>${d.watch.map((w) => `<tr><td class="need-admin"><input type="checkbox" data-hw="${w.id}" aria-label="${esc(L('Kiezen'))}"></td>
      <td><span class="muted">${esc((IOC_KIND[w.kind] || (() => w.kind))())}</span> <code>${esc(w.value)}</code>${w.note ? `<br><span class="muted">${esc(w.note)}</span>` : ''}</td>
      <td class="small">${w.hits ? `<b class="bad">${nTreffer(w.hits)}</b><br>${agoSpan(w.last_hit)}` : `<span class="muted">${L('nog niet gezien')}</span>`}</td></tr>`).join('')}</tbody></table></div>
      <div class="btn-row need-admin"><button type="button" class="btn small-btn" id="hunt-watch-del">✕ ${L('Gekozen weghalen')}</button></div>` : `<p class="muted small">${L('Nog geen. Plak sporen links en kies "Bewaken".')}</p>`}
    <h3 class="set-sub">🕘 ${L('Eerdere jachten')}</h3>
    ${d.hunts.length ? `<ul class="hunt-hist">${d.hunts.map((h) => `<li><button type="button" class="linkish" data-hunt="${h.id}">${agoSpan(h.at)} · ${L('{n} sporen', { n: h.n })} · ${h.hits ? `<b class="bad">${nTreffer(h.hits)}</b>` : L('niets gevonden')}</button>
      <br><span class="muted small">${esc(h.iocs.map((i) => i.value).join(', ').slice(0, 90))}${h.by ? ' · ' + esc(h.by) : ''}</span></li>`).join('')}</ul>` : `<p class="muted small">${L('Nog geen.')}</p>`}`;
  box.onclick = async (e) => {
    const h = e.target.closest('[data-hunt]');
    if (h) { try { huntShow(await api('ioc_get', null, { id: +h.dataset.hunt })); } catch (ex) { toast(ex.message, 'err'); } return; }
    if (e.target.closest('#hunt-watch-del')) {
      const ids = $$('[data-hw]', box).filter((x) => x.checked).map((x) => +x.dataset.hw);
      if (!ids.length) return toast(L('Kies eerst een spoor'), 'err');
      try { await api('ioc_watch_delete', { ids }); toast(L('Weggehaald')); loadHunt(); } catch (ex) { toast(ex.message, 'err'); }
    }
  };
}

function huntShow(h) {
  huntCur = h;
  const box = $('#hunt-result');
  const r = h.result || { iocs: [] };
  const ag = h.agents;
  const agHits = ag ? Object.values(ag.done || {}).flatMap((x) => (x.hits || []).map((y) => ({ ...y, host: x.host }))) : [];
  box.innerHTML = `<div class="hunt-head"><b>${L('Jacht van {t}', { t: esc(new Date(h.at.replace(' ', 'T')).toLocaleString(LOCALE, { dateStyle: 'short', timeStyle: 'short' })) })}</b>
      · ${L('{n} sporen', { n: r.iocs.length })} · ${L('laatste {d} dagen', { d: h.days })} · ${h.hits ? `<b class="bad">${nTreffer(h.hits)}</b>` : `<span class="ok">✔ ${L('niets gevonden')}</span>`}
      ${r.partial ? `<span class="muted small"> · ${L('niet alles doorzocht (te veel): kies minder dagen')}</span>` : ''}</div>
    ${h.skipped && h.skipped.length ? `<p class="muted small">${L('Overgeslagen (geen spoor):')} ${esc(h.skipped.slice(0, 10).join(', '))}</p>` : ''}
    ${ag ? `<div class="callout small">🖥 ${L('Op de servers: {d} van {a} klaar', { d: Object.keys(ag.done || {}).length, a: ag.asked })}${ag.waiting ? ' · ⏳ ' + L('{n} wachten nog (de agent zoekt bij zijn volgende ronde, hooguit een paar minuten)', { n: ag.waiting }) : ''}
      ${Object.values(ag.done || {}).map((x) => `<br>${esc(x.host)}: ${x.hits.length ? `<b class="bad">${nTreffer(x.hits.length)}</b>` : L('niets')} <span class="muted">(${L('{n} bestanden in {s} s', { n: x.files, s: x.secs })})</span>`).join('')}</div>` : ''}
    ${agHits.length ? `<div class="hunt-ioc hunt-hit"><b>🖥 ${L('Gevonden op de servers')}</b><ul>${agHits.map((x) => `<li><b>${esc(x.host)}</b> · <code>${esc(x.p)}</code> <span class="muted">(${esc(x.t === 'sha' ? 'sha256 ' + x.v.slice(0, 16) + '…' : L('pad bestaat'))})</span></li>`).join('')}</ul></div>` : ''}
    ${r.iocs.map((i) => `<div class="hunt-ioc${i.n ? ' hunt-hit' : ''}"><div><span class="muted">${esc((IOC_KIND[i.kind] || (() => i.kind))())}</span> <code>${esc(i.value)}</code>
        ${i.n ? `<b class="bad">${nTreffer(i.n)}</b>` : `<span class="muted small">${L('niet gezien')}</span>`}
        ${i.ti ? ` <span class="bad small">☣ ${L('bekend bij {s}', { s: esc(i.ti.src || '') })}${i.ti.info ? ': ' + esc(i.ti.info) : ''}</span>` : ''}</div>
      ${i.n ? `<table class="vuln-table small"><tbody>${i.hits.map((x) => `<tr><td class="nowrap">${esc((IOC_SRC[x.src] || (() => x.src))())}</td><td>${esc(x.host)}</td><td class="nowrap">${x.at ? agoSpan(x.at) : ''}</td><td>${esc(x.text)}</td></tr>`).join('')}</tbody></table>` : ''}</div>`).join('')}`;
  clearTimeout(huntPoll);
  if (ag && ag.waiting && idsTab === 'hunt') {
    const id = h.id;
    huntPoll = setTimeout(async () => {
      if (idsTab !== 'hunt' || !huntCur || huntCur.id !== id) return;
      try { huntShow({ ...(await api('ioc_get', null, { id })), skipped: h.skipped }); } catch { /* volgende keer */ }
    }, 8000);
  }
}

function initHunt() {
  const go = $('#hunt-go');
  if (!go || go.dataset.wired) return;
  go.dataset.wired = '1';
  go.onclick = async () => {
    const text = $('#hunt-text').value;
    if (!text.trim()) return toast(L('Plak eerst sporen (IP, domein, URL, sha256 of pad)'), 'err');
    go.disabled = true;
    $('#hunt-result').innerHTML = `<p class="muted">⏳ ${L('Zoeken…')}</p>`;
    try { huntShow(await api('ioc_hunt', { text, days: +$('#hunt-days').value, agents: $('#hunt-agents').checked })); loadHunt(); }
    catch (ex) { $('#hunt-result').innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; }
    go.disabled = false;
  };
  $('#hunt-watch').onclick = async () => {
    const text = $('#hunt-text').value;
    if (!text.trim()) return toast(L('Plak eerst sporen (IP, domein, URL, sha256 of pad)'), 'err');
    const note = prompt(L('Notitie bij deze sporen (bv. waar ze vandaan komen):'), '') ?? null;
    if (note === null) return;
    try {
      const r = await api('ioc_watch_add', { text, note });
      toast(L('{n} sporen bewaakt', { n: r.added }) + (r.skipped.length ? ' · ' + L('{n} overgeslagen', { n: r.skipped.length }) : ''));
      loadHunt();
    } catch (ex) { toast(ex.message, 'err'); }
  };
}

// ---------------------------------------------------------------- 🧩 Agent Manager: programma's per server
async function amApps(h, body) {
  const box = $('#am-apps', body);
  if (!box) return;
  let d;
  try { d = await api('apps_info', null, { host_id: h.id }); } catch (ex) { box.innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  const c = d.counts;
  const until = d.since ? new Date(new Date(d.since.replace(' ', 'T')).getTime() + d.learn * 86400000) : null;
  box.innerHTML = `${!d.on ? `<div class="callout small">${L('Onbekende programma\'s staat uit voor alle servers (Instellingen → IDS → Programma\'s).')}</div>` : ''}
    ${!d.agent_ok ? `<div class="callout small">${L('Agent 1.91.0 of nieuwer nodig (en als root); werk de agent bij.')}</div>` : ''}
    ${amRow('🧩 ' + L('Programma\'s bijhouden'), L('wat er draait, met vingerafdruk en pakket; na de leerperiode valt een onbekend programma op'), amSw('ap-on', d.host_on))}
    ${amRow('⛔ ' + L('Geblokkeerde programma\'s stoppen'), L('de agent stopt een programma dat je blokkeerde zodra het draait. Aanzetten vraagt je wachtwoord.'), amSw('ap-kill', d.kill))}
    <p class="small">${d.since ? (d.learning && until ? `🎓 ${L('Leert tot {d}: wat nu draait geldt als normaal.', { d: until.toLocaleDateString(LOCALE) })}` : `✔ ${L('Leerperiode voorbij: nieuwe programma\'s zonder pakket vallen op.')}`) : `<span class="muted">${L('Wacht op het eerste rapport.')}</span>`}
      ${d.last ? ` · ${L('{n} programma\'s draaien nu', { n: d.last.n })}` : ''}</p>
    <div class="app-sum">${['new', 'block', 'ok', 'learn', 'pkg'].map((s) => `<span class="app-sum-b">${appChip(s)} <b>${c[s] || 0}</b></span>`).join('')}</div>
    ${d.rows.length ? `<div class="table-scroll"><table class="vuln-table small"><tbody>${d.rows.slice(0, 30).map((r, i) => `<tr><td>${appChip(r.status)}</td><td><code>${esc(r.path)}</code><br><span class="muted">${esc(r.user || '')} · ${agoSpan(r.last)}</span></td>
      <td class="nowrap">${r.status !== 'ok' ? `<button type="button" class="btn small-btn" data-ap-do="allow" data-i="${i}">✔</button>` : ''} ${r.status !== 'block' ? `<button type="button" class="btn small-btn danger" data-ap-do="block" data-i="${i}">⛔</button>` : ''}</td></tr>`).join('')}</tbody></table></div>` : ''}
    <div class="btn-row"><button type="button" class="btn primary small-btn" id="ap-save">${L('Opslaan')}</button> <a class="btn small-btn" href="#ids/apps" data-goto="ids/apps">${L('Alle programma\'s')} →</a></div>`;
  box.onclick = (e) => {
    const b = e.target.closest('[data-ap-do]');
    if (b) appDecide(b.dataset.apDo, { ...d.rows[+b.dataset.i], host_id: h.id, host: h.name }, () => agentInstructions(findHost(h.id)));
  };
  const send = async (data, reopen) => {
    await api('apps_host_save', data);
    toast(L('Opgeslagen; de agent pakt het binnen een minuut op'));
    if (reopen) agentInstructions(findHost(h.id)); else amApps(h, body);
  };
  $('#ap-save', box).onclick = () => {
    const data = { host_id: h.id, on: $('#ap-on', box).checked, kill: $('#ap-kill', box).checked };
    if (data.kill && !d.kill) {
      return modal({ title: L('Geblokkeerde programma\'s stoppen'), body: `<p>${L('De agent stopt een programma dat je blokkeerde zodra het draait (alleen dat proces, op PID). Bevestig met je wachtwoord.')}</p>${confirmField('STOPPEN')}`,
        buttons: [{ label: L('Bevestigen'), cls: 'primary', submit: true }], onSubmit: (f) => send({ ...data, confirm: f.confirm }, true) });
    }
    send(data, false).catch((ex) => toast(ex.message, 'err'));
  };
}

// ---------------------------------------------------------------- Instellingen → IDS → Programma's
async function loadAppsSet() {
  const box = $('#apps-hosts');
  if (!box) return;
  let d;
  try { d = await api('apps', null, { status: 'new' }); } catch (ex) { box.innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  box.innerHTML = d.hosts.length ? `<div class="table-scroll"><table class="vuln-table small"><thead><tr><th>${L('Server')}</th><th>${L('Bijhouden')}</th><th>${L('Stoppen')}</th><th>${L('Leerperiode')}</th><th></th></tr></thead><tbody>${d.hosts.map((h) => `<tr>
    <td><b>${esc(h.name)}</b>${!h.agent_ok ? `<br><span class="muted small">${L('agent 1.91.0 nodig')}</span>` : ''}</td>
    <td>${h.on ? '✔' : `<span class="muted">${L('uit')}</span>`}</td><td>${h.kill ? '⛔ ' + L('aan') : `<span class="muted">${L('uit')}</span>`}</td>
    <td class="small">${!h.until ? '–' : h.learning ? '🎓 ' + L('tot {d}', { d: new Date(h.until.replace(' ', 'T')).toLocaleDateString(LOCALE) }) : '✔ ' + L('voorbij')}</td>
    <td><button type="button" class="btn small-btn" data-ap-am="${h.id}">${L('Instellen')} →</button></td></tr>`).join('')}</tbody></table></div>
    <p class="small"><a href="#ids/apps" data-goto="ids/apps">${L('Naar IDS → Programma\'s ({n} onbekend)', { n: d.counts.new })}</a></p>`
    : `<p class="muted">${L('Nog geen servers met de agent.')}</p>`;
  box.onclick = (e) => { const b = e.target.closest('[data-ap-am]'); if (b) agentInstructions(findHost(+b.dataset.apAm)); };
}
// ---------------------------------------------------------------- 🩹 Updates installeren (patchbeheer, 1.230.0, agent 1.92.0)
// Kwetsbaarheden → Updates (overzicht en nu installeren), de kaart in de Agent Manager (keuze per server) en
// Instellingen → Beveiliging → Updates. Bijwerken zelf loopt via dezelfde opdracht als "pakketten bijwerken" (Vulns),
// dus de voortgang is hetzelfde venster (vulnUpgradeDialog).
const PATCH_MODE = { manual: () => L('met de hand'), window: () => L('in het onderhoudsvenster'), auto: () => L('elke dag') };
const PATCH_KIND = { ha: () => '🏠 Home Assistant', truenas: () => '🗄️ TrueNAS', linux: () => '🐧 Linux' };
let patchData = null;

const patchModeTxt = (h) => (h.mode === 'auto' ? L('elke dag om {t}', { t: h.time }) : (PATCH_MODE[h.mode] || (() => h.mode))());
const patchCount = (h) => (h.kind === 'ha' ? h.list.filter((x) => x[0] !== 'os').length : h.scope === 'all' ? h.avail : h.sec);

function patchBadge(h) {
  if (h.kind === 'truenas') return `<span class="muted small">${L('via TrueNAS zelf')}</span>`;
  if (!h.agent_ok) return `<span class="muted small">${L('agent 1.92.0 nodig')}</span>`;
  if (!h.at) return `<span class="muted small">${L('wacht op het eerste rapport')}</span>`;
  if (h.kind === 'ha') return h.avail ? `<b class="warn">${L('{n} updates', { n: h.avail })}</b>` : `<span class="ok">✔ ${L('alles bij')}</span>`;
  return h.avail ? `${h.sec ? `<b class="bad">🛡 ${L('{n} beveiliging', { n: h.sec })}</b> · ` : ''}${L('{n} updates', { n: h.avail })}` : `<span class="ok">✔ ${L('alles bij')}</span>`;
}

async function loadPatch() {
  const box = $('#patch-body');
  if (!box) return;
  try { patchData = await api('patch'); } catch (ex) { box.innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  const d = patchData;
  const hs = d.hosts;
  const sec = hs.reduce((n, h) => n + (h.kind === 'linux' ? h.sec : 0), 0);
  if ($('#vt-n-patch')) $('#vt-n-patch').textContent = sec || '';
  box.innerHTML = `${!d.on ? `<div class="callout small">${L('Updates installeren staat uit (Instellingen → Beveiliging → Updates). Je ziet wel wat er klaarstaat.')}</div>` : ''}
    <div class="app-sum"><span class="app-sum-b">🛡 <b>${sec}</b> ${L('beveiligingsupdates')}</span><span class="app-sum-b">⬆ <b>${hs.reduce((n, h) => n + h.avail, 0)}</b> ${L('updates')}</span>
      <span class="app-sum-b">↻ <b>${hs.filter((h) => h.rb).length}</b> ${L('herstart nodig')}</span><span class="app-sum-b">🤖 <b>${hs.filter((h) => h.mode !== 'manual').length}</b> ${L('automatisch')}</span></div>
    ${hs.length ? `<div class="table-scroll"><table class="vuln-table small patch-table"><thead><tr><th>${L('Server')}</th><th>${L('Klaar')}</th><th>${L('Hoe')}</th><th>${L('Laatst')}</th><th></th></tr></thead><tbody>
      ${hs.map((h) => `<tr data-ph="${h.id}"><td><b>${esc(h.name)}</b><br><span class="muted">${(PATCH_KIND[h.kind] || (() => h.kind))()}${h.self ? ' · ' + L('RzSense zelf') : ''}</span></td>
        <td>${patchBadge(h)}${h.rb ? `<br><span class="warn small">↻ ${L('herstart nodig (doe dat zelf)')}</span>` : ''}${h.list.length ? `<br><button type="button" class="linkish small" data-ph-list="${h.id}">${L('lijst')}</button>` : ''}</td>
        <td>${h.kind === 'truenas' ? '–' : esc(patchModeTxt(h)) + (h.kind === 'linux' ? `<br><span class="muted">${h.scope === 'all' ? L('alle updates') : L('alleen beveiligingsupdates')}${h.snap ? ' · 📸' : ''}</span>` : '')}
          ${h.mode === 'window' && !h.windows.length ? `<br><span class="warn small">${L('geen onderhoudsvenster ingesteld')}</span>` : ''}</td>
        <td>${h.status && ['queued', 'running'].includes(h.status.state) || h.ha_req ? `<b>⏳ ${L('bezig')}</b>` : h.last ? agoSpan(h.last) : '–'}</td>
        <td class="nowrap need-admin">${!h.blocked && patchCount({ ...h, scope: 'security' }) && h.kind === 'linux' ? `<button type="button" class="btn small-btn primary" data-ph-now="security">🛡 ${L('Beveiliging')}</button> ` : ''}
          ${!h.blocked && h.avail ? `<button type="button" class="btn small-btn" data-ph-now="all">⬆ ${h.kind === 'ha' ? L('Core en add-ons') : L('Alles')}</button> ` : ''}
          ${h.kind !== 'truenas' ? `<button type="button" class="btn small-btn" data-ph-am="1">${L('Instellen')} →</button>` : ''}
          ${h.blocked && h.kind !== 'truenas' && h.agent_ok ? `<br><span class="muted small">${esc(h.blocked)}</span>` : ''}</td></tr>`).join('')}
      </tbody></table></div>` : `<p class="muted">${L('Nog geen servers met de agent.')}</p>`}`;
  box.onclick = (e) => {
    const tr = e.target.closest('[data-ph]');
    if (!tr) return;
    const h = hs.find((x) => x.id === +tr.dataset.ph);
    if (e.target.closest('[data-ph-list]')) return patchList(h);
    if (e.target.closest('[data-ph-am]')) return agentInstructions(findHost(h.id));
    const now = e.target.closest('[data-ph-now]');
    if (now) patchNow(h, now.dataset.phNow, loadPatch);
  };
}

function patchList(h) {
  modal({
    title: L('Updates voor {name}', { name: h.name }),
    body: `<div style="padding:1rem 1.2rem"><table class="vuln-table small"><thead><tr><th>${L('Pakket')}</th><th>${L('Nieuwe versie')}</th><th></th></tr></thead><tbody>
      ${h.list.map((x) => `<tr><td><code>${esc(x[3] || x[0])}</code></td><td>${esc(x[1])}</td><td>${+x[2] ? `<b class="bad">🛡 ${L('beveiliging')}</b>` : ''}${x[0] === 'os' ? `<span class="muted">${L('in Home Assistant zelf (herstart alles)')}</span>` : ''}</td></tr>`).join('')}
      </tbody></table>${h.list.length >= 300 ? `<p class="muted small">${L('De eerste 300.')}</p>` : ''}</div>`,
    buttons: [{ label: L('Sluiten'), onClick: () => $('#modal').close() }],
  });
}

function patchNow(h, scope, done) {
  const ha = h.kind === 'ha';
  const n = ha ? h.list.filter((x) => x[0] !== 'os').length : scope === 'all' ? h.avail : h.sec;
  modal({
    title: ha ? L('Home Assistant bijwerken') : scope === 'all' ? L('Alle updates installeren op {name}', { name: h.name }) : L('Alle beveiligingsupdates installeren op {name}', { name: h.name }),
    body: `<div style="padding:1rem 1.2rem">
      <p>${ha ? L('De agent werkt Core en de add-ons met een update bij via de Supervisor, met een back-up vooraf. Het besturingssysteem (OS) niet: dat herstart het hele systeem.')
    : L('De agent installeert {n} pakketten met de pakketbeheerder van de server.', { n })}</p>
      ${!ha && h.snap ? `<p class="small">📸 ${L('Eerst een snapshot van / (ZFS, snapper of btrfs), zodat je terug kunt.')}</p>` : ''}
      <p class="small">${L('Er wordt niets herstart. Is dat daarna nodig, dan zie je ↻ bij de server.')}</p>
      ${h.self ? `<p class="warn-txt">${L('Dit is de server waar RzSense zelf op draait. Gaat er iets mis, dan zie je het hier niet meer: blijf erbij.')}</p>` : ''}
      ${confirmField('BIJWERKEN')}</div>`,
    buttons: [{ label: L('Annuleren'), onClick: () => $('#modal').close() }, { label: '⬆ ' + L('Bijwerken'), cls: 'primary', submit: true }],
    onSubmit: async (v) => {
      await api('patch_now', { host_id: h.id, scope, confirm: v.confirm });
      if (ha) { $('#modal').close(); toast(L('Gevraagd; de agent begint bij zijn volgende ronde. De uitkomst komt in het logboek.')); }
      else { vulnUpgradeDialog({ id: h.id, name: h.name }, true, { state: 'queued', pkgs: [] }); }
      if (done) done();
      return ha ? undefined : 'keep';
    },
  });
}

// ---------------------------------------------------------------- Agent Manager: keuze per server
async function amPatch(h, body) {
  const box = $('#am-patch', body);
  if (!box) return;
  let d;
  try { d = (await api('patch')).hosts.find((x) => x.id === h.id); } catch (ex) { box.innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  if (!d) { box.innerHTML = ''; return; }
  if (d.kind === 'truenas') { box.innerHTML = `<p class="muted small">${L('TrueNAS werk je bij met een TrueNAS-update (System → Update), nooit met apt. RzSense doet hier niets.')}</p>`; return; }
  const ha = d.kind === 'ha';
  box.innerHTML = `${!d.agent_ok ? `<div class="callout small">${L('Agent 1.92.0 of nieuwer nodig; werk de agent bij.')}</div>` : ''}
    <p class="small">${patchBadge(d)}${d.rb ? ` · <span class="warn">↻ ${L('herstart nodig (doe dat zelf)')}</span>` : ''}${d.at ? ` · <span class="muted">${L('bekeken')} ${agoSpan(new Date(d.at * 1000).toISOString())}</span>` : ''}</p>
    ${amRow('🤖 ' + L('Wanneer'), d.self ? L('dit is de RzSense-server zelf: alleen met de hand') : L('met de hand, in het vaste onderhoudsvenster van deze server, of elke dag om een tijd'),
    `<select id="pt-mode" ${d.self ? 'disabled' : ''}>${['manual', 'window', 'auto'].map((m) => `<option value="${m}" ${d.mode === m ? 'selected' : ''}>${esc(PATCH_MODE[m]())}</option>`).join('')}</select> <input id="pt-time" type="time" value="${esc(d.time)}" ${d.mode === 'auto' ? '' : 'hidden'} aria-label="${esc(L('Tijd'))}">`)}
    <p class="muted small" id="pt-win" ${d.mode === 'window' ? '' : 'hidden'}>${d.windows.length ? '🗓️ ' + d.windows.map((w) => esc(`${w.dow ? ['', L('ma'), L('di'), L('wo'), L('do'), L('vr'), L('za'), L('zo')][w.dow] : L('elke dag')} ${w.start} (${w.minutes} min)`)).join(', ')
    : `⚠ ${L('Deze server heeft nog geen vast onderhoudsvenster.')} <a href="#settings/advice" data-goto="settings/advice">${L('Instellen')} →</a>`}</p>
    ${ha ? `<p class="muted small">${L('Home Assistant: Core en add-ons, altijd met een back-up vooraf. Het OS niet (dat herstart alles).')}</p>`
    : `${amRow('🛡 ' + L('Wat'), L('alleen beveiligingsupdates is het veiligst; alles neemt ook nieuwe versies mee'),
      `<select id="pt-scope"><option value="security" ${d.scope === 'security' ? 'selected' : ''}>${L('alleen beveiligingsupdates')}</option><option value="all" ${d.scope === 'all' ? 'selected' : ''}>${L('alle updates')}</option></select>`)}
      ${amRow('📸 ' + L('Eerst een snapshot'), L('van / (ZFS, snapper of btrfs), zodat je terug kunt; anders gaat het gewoon door'), amSw('pt-snap', d.snap))}`}
    <div class="btn-row"><button type="button" class="btn primary small-btn" id="pt-save">${L('Opslaan')}</button>
      ${!d.blocked && (ha ? d.avail : d.sec) ? `<button type="button" class="btn small-btn" id="pt-now">⬆ ${ha ? L('Nu bijwerken') : L('Beveiligingsupdates nu')}</button>` : ''}
      <a class="btn small-btn" href="#vulns/patch" data-goto="vulns/patch">${L('Alle servers')} →</a></div>
    ${d.blocked && d.agent_ok ? `<p class="muted small">${esc(d.blocked)}</p>` : ''}`;
  $('#pt-mode', box).onchange = (e) => { $('#pt-time', box).hidden = e.target.value !== 'auto'; $('#pt-win', box).hidden = e.target.value !== 'window'; };
  $('#pt-save', box).onclick = async () => {
    try {
      await api('patch_save', { host_id: h.id, mode: $('#pt-mode', box).value, time: $('#pt-time', box).value, scope: ha ? 'security' : $('#pt-scope', box).value, snap: ha ? true : $('#pt-snap', box).checked });
      toast(L('Opgeslagen'));
      amPatch(h, body);
    } catch (ex) { toast(ex.message, 'err'); }
  };
  if ($('#pt-now', box)) $('#pt-now', box).onclick = () => patchNow(d, 'security', () => amPatch(h, body));
}

// ---------------------------------------------------------------- Instellingen → Beveiliging → Updates
async function loadPatchSet() {
  const box = $('#patch-hosts');
  if (!box) return;
  let d;
  try { d = await api('patch'); } catch (ex) { box.innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  box.innerHTML = d.hosts.length ? `<div class="table-scroll"><table class="vuln-table small"><thead><tr><th>${L('Server')}</th><th>${L('Hoe')}</th><th>${L('Klaar')}</th><th></th></tr></thead><tbody>${d.hosts.map((h) => `<tr>
    <td><b>${esc(h.name)}</b><br><span class="muted small">${(PATCH_KIND[h.kind] || (() => h.kind))()}${h.self ? ' · ' + L('RzSense zelf') : ''}</span></td>
    <td class="small">${h.kind === 'truenas' ? L('via TrueNAS zelf') : esc(patchModeTxt(h))}</td><td class="small">${patchBadge(h)}</td>
    <td>${h.kind !== 'truenas' ? `<button type="button" class="btn small-btn" data-pt-am="${h.id}">${L('Instellen')} →</button>` : ''}</td></tr>`).join('')}</tbody></table></div>
    <p class="small"><a href="#vulns/patch" data-goto="vulns/patch">${L('Naar Kwetsbaarheden → Updates')} →</a></p>`
    : `<p class="muted">${L('Nog geen servers met de agent.')}</p>`;
  box.onclick = (e) => { const b = e.target.closest('[data-pt-am]'); if (b) agentInstructions(findHost(+b.dataset.ptAm)); };
}
// ---------------------------------------------------------------- 🔑 Tijdelijk sudo en 🚫 AdGuard-blokkadelijst (1.231.0, agent 1.93.0)
const SUDO_ST = { pending: () => '⏳ ' + L('wacht op de agent'), active: () => '🔑 ' + L('actief'), expired: () => L('verlopen'), revoked: () => L('ingetrokken'),
  replaced: () => L('vervangen'), failed: () => '⚠ ' + L('mislukt') };
const sudoLeft = (s) => (s >= 3600 ? L('nog {h} u {m} min', { h: Math.floor(s / 3600), m: Math.floor((s % 3600) / 60) }) : L('nog {m} min', { m: Math.max(1, Math.ceil(s / 60)) }));

function sudoRows(grants, withHost) {
  return grants.length ? `<div class="table-scroll"><table class="vuln-table small"><tbody>${grants.map((g) => `<tr>
    ${withHost ? `<td><b>${esc(g.host)}</b></td>` : ''}<td><code>${esc(g.user)}</code></td>
    <td>${esc((SUDO_ST[g.state] || (() => g.state))())}${g.left && ['pending', 'active'].includes(g.state) ? ` · <b>${esc(sudoLeft(g.left))}</b>` : ''}${g.detail ? `<br><span class="muted">${esc(g.detail)}</span>` : ''}</td>
    <td class="muted">${esc(g.reason)}<br>${esc(g.by || '')} · ${agoSpan(g.at)}${g.ended_by ? ' · ' + L('ingetrokken door {u}', { u: esc(g.ended_by) }) : ''}</td>
    <td class="need-admin">${['pending', 'active'].includes(g.state) && g.left ? `<button type="button" class="btn small-btn danger" data-sudo-revoke="${g.id}">${L('Intrekken')}</button>` : ''}</td></tr>`).join('')}</tbody></table></div>`
    : `<p class="muted small">${L('Nog geen.')}</p>`;
}

async function sudoRevoke(id, done) {
  try { await api('sudo_revoke', { id }); toast(L('Ingetrokken; de agent haalt het binnen een minuut weg')); done(); } catch (ex) { toast(ex.message, 'err'); }
}

async function amSudo(h, body) {
  const box = $('#am-sudo', body);
  if (!box) return;
  let d;
  try { d = await api('sudo_list', null, { host_id: h.id }); } catch (ex) { box.innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  const active = d.grants.filter((g) => ['pending', 'active'].includes(g.state) && g.left);
  box.innerHTML = `${!d.on ? `<div class="callout small">${L('Tijdelijk sudo staat uit (Instellingen → Beveiliging → Tijdelijk sudo).')}</div>` : ''}
    ${!d.agent_ok ? `<div class="callout small">${L('Agent 1.93.0 of nieuwer nodig (op Linux, als root, met visudo).')}</div>` : ''}
    ${active.length ? `<p class="small"><b>${L('Nu actief')}</b></p>${sudoRows(active, false)}` : `<p class="muted small">${L('Nu heeft niemand tijdelijk sudo op deze server.')}</p>`}
    <div class="btn-row"><button type="button" class="btn primary small-btn" id="sudo-new" ${!d.on || !d.agent_ok ? 'disabled' : ''}>🔑 ${L('Tijdelijk sudo geven')}</button></div>
    ${d.grants.length > active.length ? `<details class="small"><summary>${L('Eerder ({n})', { n: d.grants.length - active.length })}</summary>${sudoRows(d.grants.filter((g) => !active.includes(g)), false)}</details>` : ''}`;
  box.onclick = (e) => {
    const r = e.target.closest('[data-sudo-revoke]');
    if (r) sudoRevoke(+r.dataset.sudoRevoke, () => amSudo(h, body));
  };
  const nb = $('#sudo-new', box);
  if (nb) nb.onclick = () => modal({
    title: L('Tijdelijk sudo op {name}', { name: h.name }),
    body: `<div style="padding:1rem 1.2rem">
      <label>${L('Gebruiker')}<input name="user" list="sudo-users" required pattern="[a-z_][a-z0-9_-]{0,31}" autocomplete="off" class="mono"></label>
      <datalist id="sudo-users">${d.users.map((u) => `<option value="${esc(u)}">`).join('')}</datalist>
      <label>${L('Hoe lang')}<select name="minutes">${d.durations.map((m) => `<option value="${m}" ${m === 30 ? 'selected' : ''}>${m < 60 ? L('{n} minuten', { n: m }) : L('{n} uur', { n: m / 60 })}</option>`).join('')}</select></label>
      <label>${L('Waarom')} <span class="hint">${L('(komt in het logboek)')}</span><input name="reason" required minlength="3" maxlength="200"></label>
      <p class="muted small">${L('De agent zet een eigen bestand in /etc/sudoers.d (gecontroleerd met visudo) en haalt het daarna vanzelf weg. Root kan niet.')}</p>
      ${confirmField('SUDO')}
      <label>${L('2FA-code')} <span class="hint">${L('(als je tweestapsverificatie hebt)')}</span><input name="totp" inputmode="numeric" autocomplete="one-time-code" maxlength="8" class="mono"></label></div>`,
    buttons: [{ label: L('Annuleren'), onClick: () => $('#modal').close() }, { label: '🔑 ' + L('Geven'), cls: 'primary', submit: true }],
    onSubmit: async (v) => {
      await api('sudo_grant', { host_id: h.id, user: v.user, minutes: +v.minutes, reason: v.reason, confirm: v.confirm, totp: v.totp });
      toast(L('Gegeven; de agent zet het binnen een minuut klaar'));
      agentInstructions(findHost(h.id));
    },
  });
}

async function loadSudoSet() {
  const box = $('#sudo-list');
  if (!box) return;
  let d;
  try { d = await api('sudo_list'); } catch (ex) { box.innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  box.innerHTML = sudoRows(d.grants.slice(0, 50), true) + `<p class="muted small">${L('Geven doe je per server in de Agent Manager (kaart Tijdelijk sudo).')}</p>`;
  box.onclick = (e) => { const r = e.target.closest('[data-sudo-revoke]'); if (r) sudoRevoke(+r.dataset.sudoRevoke, loadSudoSet); };
}

// ---------------------------------------------------------------- 🚫 AdGuard-blokkadelijst
async function loadDnsbl() {
  const box = $('#dnsbl-box');
  if (!box || !isAdmin()) return;
  let d;
  try { d = await api('dnsbl_status'); } catch (ex) { box.innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  const per = d.per || {};
  box.innerHTML = `<p class="small">${L('{n} domeinen', { n: d.n })} <span class="muted">(${['urlhaus', 'threatfox', 'ioc', 'own'].filter((k) => per[k]).map((k) => `${esc({ urlhaus: 'URLhaus', threatfox: 'ThreatFox', ioc: L('bewaakt'), own: L('eigen') }[k])} ${per[k]}`).join(' · ') || L('nog leeg')})</span>
      ${d.fetched ? ` · ${L('laatst opgehaald')} ${agoSpan(d.fetched)} ${L('door {ip}', { ip: esc(d.fetched_by || '?') })}` : ` · <span class="muted">${L('nog niet opgehaald')}</span>`}</p>
    ${d.on ? `<label>${L('Geheime URL voor AdGuard')} <span class="hint">${L('(alleen vanaf je lokale netwerk)')}</span></label>${copyBox('dnsbl-url', d.url)}
    <div class="btn-row">${d.adguard ? `<button type="button" class="btn small-btn primary" id="dnsbl-add">➕ ${L('Toevoegen aan AdGuard')}</button>` : `<span class="muted small">${L('Koppel AdGuard (Koppelingen → AdGuard) om hem met één klik toe te voegen.')}</span>`}
      <button type="button" class="btn small-btn" id="dnsbl-new">🔄 ${L('Nieuwe geheime URL')}</button></div>` : `<p class="muted small">${L('Zet de lijst aan om de URL te zien.')}</p>`}
    <div id="dnsbl-res"></div>`;
  wireCopy(box);
  if ($('#dnsbl-add', box)) $('#dnsbl-add', box).onclick = async () => {
    try {
      const r = await api('dnsbl_adguard_add', { url: d.url });
      $('#dnsbl-res', box).innerHTML = r.results.map((x) => `<p class="small ${x.ok ? 'ok' : 'bad'}">${x.ok ? '✔' : '✘'} ${esc(x.host)}: ${esc(x.msg)}</p>`).join('');
    } catch (ex) { toast(ex.message, 'err'); }
  };
  if ($('#dnsbl-new', box)) $('#dnsbl-new', box).onclick = () => modal({
    title: L('Nieuwe geheime URL'),
    body: `<div style="padding:1rem 1.2rem"><p>${L('De oude URL werkt daarna niet meer: zet de nieuwe in AdGuard (of klik daarna op Toevoegen aan AdGuard en haal de oude daar weg).')}</p>${confirmField('VERNIEUWEN')}</div>`,
    buttons: [{ label: L('Annuleren'), onClick: () => $('#modal').close() }, { label: L('Vernieuwen'), cls: 'primary', submit: true }],
    onSubmit: async (v) => { await api('dnsbl_token_new', { confirm: v.confirm }); $('#modal').close(); loadDnsbl(); },
  });
}
// ---------------------------------------------------------------- 🇪🇺 NIS2 (1.232.0): maatregelen, notities en meldtermijnen
const NIS2_ST = { ok: ['✔', () => L('geregeld'), 'ok'], manual: ['✔', () => L('zelf als geregeld gemarkeerd'), 'ok'], partial: ['◐', () => L('deels'), 'warn'], missing: ['✘', () => L('ontbreekt'), 'bad'] };
const nis2Left = (due) => {
  const s = Math.round((new Date(due.replace(' ', 'T')).getTime() - Date.now()) / 1000);
  if (s <= 0) return `<b class="bad">${L('verlopen')}</b>`;
  return s >= 86400 ? L('nog {d} d {h} u', { d: Math.floor(s / 86400), h: Math.floor((s % 86400) / 3600) }) : `<b class="warn">${L('nog {h} u {m} min', { h: Math.floor(s / 3600), m: Math.floor((s % 3600) / 60) })}</b>`;
};

async function loadNis2() {
  const box = $('#nis2-box');
  if (!box) return;
  let d;
  try { d = await api('nis2'); } catch (ex) { box.innerHTML = `<p class="form-error">${esc(ex.message)}</p>`; return; }
  const cnt = (s) => d.measures.filter((m) => m.status === s || (s === 'ok' && m.status === 'manual')).length;
  const step = (i, w, label) => `<div class="nis2-step ${i[w] ? 'done' : ''}"><b>${label}</b><br>${i[w] ? `✔ ${L('verstuurd')} ${agoSpan(i[w])}` : `${L('uiterlijk {d}', { d: esc(fmtDateTime(i[w + '_due'])) })}<br>${nis2Left(i[w + '_due'])}`}
    <label class="small need-admin"><input type="checkbox" data-nis2-sent="${w}" data-id="${i.id}" ${i[w] ? 'checked' : ''}> ${L('verstuurd')}</label></div>`;
  box.innerHTML = `${!d.on ? `<div class="callout small">${L('Het NIS2-overzicht staat uit; je ziet het wel, maar er komen geen meldingen over termijnen.')}</div>` : ''}
    <div class="app-sum"><span class="app-sum-b"><span class="ok">✔</span> <b>${cnt('ok')}</b> ${L('geregeld')}</span><span class="app-sum-b"><span class="warn">◐</span> <b>${cnt('partial')}</b> ${L('deels')}</span>
      <span class="app-sum-b"><span class="bad">✘</span> <b>${cnt('missing')}</b> ${L('ontbreekt')}</span>
      <a class="btn small-btn" href="api.php?action=nis2_report" target="_blank" rel="noopener">📄 ${L('NIS2-rapport (afdrukken als PDF)')}</a></div>
    <h3 class="set-sub">${L('Maatregelen (art. 21 lid 2)')}</h3>
    <div class="nis2-list">${d.measures.map((m) => { const [ic, lbl, c] = NIS2_ST[m.status]; return `<details class="nis2-m nis2-${c}" ${m.status === 'missing' ? 'open' : ''}>
      <summary><span class="${c}">${ic}</span> <b>${m.code.toUpperCase()}. ${esc(m.title)}</b> <span class="muted small">${esc(lbl())}</span></summary>
      <p class="muted small">${esc(m.desc)}</p>
      <ul class="nis2-ev">${m.evidence.map((e) => `<li>${e.ok === true ? '<span class="ok">✔</span>' : e.ok === false ? '<span class="bad">✘</span>' : '<span class="muted">•</span>'} ${esc(e.text)}${e.go ? ` <a href="#${esc(e.go)}" data-goto="${esc(e.go)}" class="small">${L('bekijken')} →</a>` : ''}</li>`).join('')}</ul>
      <label class="small">${L('Notitie')} <span class="hint">${L('(wat je verder geregeld hebt: beleid, afspraken, wie, wanneer)')}</span><textarea rows="3" data-nis2-note="${m.code}" class="need-admin-input">${esc(m.note)}</textarea></label>
      <div class="btn-row need-admin"><label class="switch small"><input type="checkbox" data-nis2-manual="${m.code}" ${m.manual ? 'checked' : ''}><span></span> ${L('Zelf als geregeld markeren')}</label>
        <button type="button" class="btn small-btn" data-nis2-save="${m.code}">${L('Opslaan')}</button>${m.by ? ` <span class="muted small">${esc(m.by)} · ${agoSpan(m.at)}</span>` : ''}</div></details>`; }).join('')}</div>
    <h3 class="set-sub">${L('Significante incidenten en meldtermijnen (art. 23)')}</h3>
    ${d.csirt ? `<p class="small">${L('Melden bij: {c}', { c: `<b>${esc(d.csirt)}</b>` })}</p>` : ''}
    ${d.incidents.length ? d.incidents.map((i) => `<div class="nis2-inc"><div><b>${esc(i.title)}</b> <span class="muted small">${esc(i.host || '')} · ${L('bekend sinds {d}', { d: esc(fmtDateTime(i.at)) })}</span>
        <button type="button" class="linkish small need-admin" data-nis2-unmark="${i.id}">${L('niet significant')}</button></div>
      <div class="nis2-steps">${step(i, 'warn', L('Vroegtijdige waarschuwing (24 uur)'))}${step(i, 'notify', L('Incidentmelding (72 uur)'))}${step(i, 'final', L('Eindverslag (een maand)'))}</div></div>`).join('')
    : `<p class="muted small">${L('Geen significante incidenten.')}</p>`}
    <div class="btn-row need-admin">${d.recent.length ? `<select id="nis2-pick" aria-label="${esc(L('Incident'))}"><option value="">${L('Incident van de laatste 30 dagen…')}</option>${d.recent.map((r) => `<option value="${r.id}">${esc(fmtDateTime(r.at))} · ${esc(r.title.slice(0, 80))}${r.host ? ' · ' + esc(r.host) : ''}</option>`).join('')}</select>
      <button type="button" class="btn small-btn" id="nis2-mark">⚠ ${L('Als significant markeren')}</button>` : `<span class="muted small">${L('Geen incidenten van de laatste 30 dagen om te markeren (Incidenten).')}</span>`}</div>
    <p class="muted small">${L('Dit is geen juridisch advies en geen certificering: het laat zien wat RzSense technisch ziet. Of je onder NIS2 valt en wat significant is, bepaal je zelf (of met je adviseur).')}</p>`;
  box.onclick = async (e) => {
    const s = e.target.closest('[data-nis2-save]');
    const un = e.target.closest('[data-nis2-unmark]');
    try {
      if (s) {
        const c = s.dataset.nis2Save;
        await api('nis2_note', { code: c, note: $(`[data-nis2-note="${c}"]`, box).value, manual: $(`[data-nis2-manual="${c}"]`, box).checked });
        toast(L('Opgeslagen'));
        loadNis2();
      } else if (un) {
        await api('nis2_mark', { id: +un.dataset.nis2Unmark, on: false });
        loadNis2();
      } else if (e.target.closest('#nis2-mark')) {
        const id = +$('#nis2-pick', box).value;
        if (!id) return toast(L('Kies eerst een incident'), 'err');
        await api('nis2_mark', { id, on: true });
        loadNis2();
      }
    } catch (ex) { toast(ex.message, 'err'); }
  };
  box.onchange = async (e) => {
    const c = e.target.closest('[data-nis2-sent]');
    if (!c) return;
    try { await api('nis2_sent', { id: +c.dataset.id, which: c.dataset.nis2Sent, on: c.checked }); loadNis2(); } catch (ex) { toast(ex.message, 'err'); }
  };
}
